"use strict";(globalThis.webpackChunkdocusaurus_blog_rudevico=globalThis.webpackChunkdocusaurus_blog_rudevico||[]).push([[3518],{4369:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"a-day-of-kakao-problems","metadata":{"permalink":"/a-day-of-kakao-problems","editUrl":"https://github.com/hyoyoonnam/blog/2026-11-06-a-day-of-kakao-problems/index.md","source":"@site/blog/2026-11-06-a-day-of-kakao-problems/index.md","title":"\uce74\uce74\uc624\ub85c \ub9de\uc740 \ub0a0","description":"\uc54c\uace0\ub9ac\uc998\uc740 \ubabb\ud480\uc5b4\uc57c \uc131\uc7a5\uc774\uc57c","date":"2026-11-06T07:05:22.829Z","tags":[{"inline":false,"label":"\uae30\uc220","permalink":"/tags/tech"}],"readingTime":1.07,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"a-day-of-kakao-problems","title":"\uce74\uce74\uc624\ub85c \ub9de\uc740 \ub0a0","date":"2026-11-06T07:05:22.829Z","authors":"hyoyoonnam","tags":["\uae30\uc220"],"image":"./hide-the-cactus.png"},"unlisted":false,"nextItem":{"title":"\uc81c\ucd9c\ud560 \ub54c \ub514\ubc84\uae45 \ucd9c\ub825\uc744 \uc228\uae30\uae30","permalink":"/hide-debug-output-on-submission"}},"content":"## \uc54c\uace0\ub9ac\uc998\uc740 \ubabb\ud480\uc5b4\uc57c \uc131\uc7a5\uc774\uc57c\\n\\n![image.png](./hide-the-cactus.png)\\n\\n\x3c!-- truncate --\x3e\\n\\n## \uc18d \uc4f0\ub9bc\uc758 \uc6d0\uc778\\n\\n![17bcf00719bce84c1058d82030c7fe08307e20d2.heic](./photo-1.jpg)\\n\\n## \ub2d8\uc544 \uadf8 \uac15\uc744 \uac74\ub108\uc9c0 \ub9c8\uc624\\n\\n\ub0b4\uac00 \uc608\uc804\uc5d0 \ud480\uc5c8\ub358 \uc815\ub2f5\ub960 \ub0ae\uc740 Lv1 \ubb38\uc81c\ub4e4\uc774 1\ub144\ub3c4 \ub354 \uc9c0\ub09c \ud6c4\uc5d0 \ubcf4\ub2c8 \uc815\ub2f5\ub960\uc774 \ub9ce\uc774 \uc62c\ub77c\uac04 \uac8c \ubcf4\uc600\ub2e4.\\n\\n![9f16ab6e49b557894e94c39a26da45c22d0aff1e.heic](./photo-2.jpg)\\n\\n\uadf8\ub798\uc11c \uc120\uc778\uc7a5 \uc228\uae30\uae30\ub3c4 \uadf8\ub7f0 \uc904 \uc54c\uc558\ub2e4.\\\\\\n\uadf8\ub7f0 \uc9d3\uc740 \ud558\uc9c0 \ub9d0\uc544\uc57c \ud588\ub294\ub370\u2026-\\n\\n## \uc2dc\uac04 \ubcf5\uc7a1\ub3c4\\n\\n\ubb38\uc81c \uc774\uc57c\uae30\ub294 \uc801\ub2f9\ud788 \uc7ac\uad6c\uc131\ud558\uaca0\ub2e4. \uc808\ub300 \ub2e4\uc2dc \ubcf4\uae30 \ubb34\uc11c\uc6cc\uc11c\uac00 \uc544\ub2c8\ub2e4..\\n\\n* 1 &lt;= m, n &lt;= 500_000\\n* 1 &lt;= m x n &lt;= 500_000\\n\\n\uc704 \uc870\uac74\uc73c\ub85c \uc778\ud574\uc11c \uacb0\uad6d m -> n 2-depth for loop\uc744 \ub3cc\uc544\ub3c4 \uc2dc\uac04\ubcf5\uc7a1\ub3c4\uac00 \uc801\uc5c8\uace0, \uadf8\ub798\uc11c \u201c\uac4d \uc644\ud0d0 \ub3cc\uba74 \ub418\uaca0\ub124\u201d\ub77c\uace0 \uc0dd\uac01\ud588\ub2e4.\\n\\n\uadf8\ub7ec\ub2e4 \ub0b4 \ubbf8\ucc9c\ud55c \ud480\uc774(\ud480\uc9c0 \ubabb\ud588\uc73c\ub2c8 \ud480\uc774\uac00 \uc544\ub2cc\uac00..)\ub97c \uc9c4\ud589\ud558\ub824\ub2c8 4-depth\uac00 \ud544\uc694\ud574\uc84c\uace0 `250_000_000_000`\uc774\ub77c\ub294 \ubb34\uc9c0\ub9c9\uc9c0\ud55c \uc218\uac00 \ub4f1\uc7a5\ud588\ub2e4.\\n\\n\uc5ec\uae30\uc11c \u201c\ub0b4 \uba38\ub9ac\ub85c \ubb54\uac00 \ube44\uc0c1\ud55c \uc218\ub97c \ub5a0\uc62c\ub824, \ub8e8\ub374\uc2a4\uae4c\uc9c0 \ub4a4\ub85c \uc790\ube60\uc9c0\uac8c \ud560 \uc218 \uc788\uc744 \uac70\uc57c\u201d\ub77c\ub294 \uc0dd\uac01\uc5d0 \uc774\ub9ac\uc800\ub9ac \uace0\ubbfc\ud588\ub2e4. \uadf8\ub807\uac8c 2\uc2dc\uac04\uc774 \uadf8\ub0e5 \ub3c4\ub791 \uc18d\uc73c\ub85c \uc790\ube60\uc84c\ub2e4..\\n\\n![2fd49a82ca3d4bc0b6da2b998aeaa165ed8b23e2.jpeg](./reaction.jpg)\\n\\n\uadf8\ub7ec\uace0 \uce74\uce74\uc624 \ub354 \uc26c\uc6b4 \ubb38\uc81c\ub97c \uc2dc\ub3c4\ud588\ub294\ub370.. \ubaa8\ub974\uaca0\ub2e4, \ubb38\uc81c\ub294 \uad1c\ucc2e\uc740 \uac70 \uac19\uc740\ub370 \ub0b4 \ub9c8\uc778\ub4dc\uc640 \ub1cc\uac00 \uad1c\ucc2e\uc9c0 \uc54a\uc558\ub2e4.\\\\\\n\uadf8\ub807\uac8c \ub610 \uc2e4\ud328\ud558\uace0 11\uc2dc \ucc28\ub97c \ud0c0\uace0 \ud558\uad50..\\n\\n\uc5b4\ub514\uac14\uc9c0, \ub0b4 \uc2dc\uac04.\\n\\n## \ub2e4\uc74c\uc5d0 \uaf2d \ud63c\ub0b8\ub2e4\\n\\n\ub8e8\ub374\uc2a4\uac00 \ube14\ub85c\uadf8\ub97c \uc880 \ucc3e\ub354\ub2c8 \ub2e8\uc870 \ud050\ub85c \ud480\uc5b4\uc57c \ub418\ub294 \ubb38\uc81c\ub77c\uace0 \uc54c\ub824\uc92c\ub2e4. \uacfc\uac70\uc5d0 \ub2e8\uc870 \uc2a4\ud0dd \ubb38\uc81c\ub294 \uba87 \uac1c \ud480\uc5c8\uc5c8\ub294\ub370... \uacb0\uad6d \ube44\uc2b7\ud558\ub824\ub098? \ub2e8\uc870 \uc2a4\ud0dd\uc880 \uba87 \ubb38\uc81c \ud480\uace0 \ub2e4\uc74c \uc8fc\uc5d0 \ub2e4\uc2dc \ud63c\ub0b4\ubd10\uc57c\uc9c0.\\n\\n![image.png](./next-problem.png)\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/512)"},{"id":"hide-debug-output-on-submission","metadata":{"permalink":"/hide-debug-output-on-submission","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-30-hide-debug-output-on-submission/index.md","source":"@site/blog/2026-10-30-hide-debug-output-on-submission/index.md","title":"\uc81c\ucd9c\ud560 \ub54c \ub514\ubc84\uae45 \ucd9c\ub825\uc744 \uc228\uae30\uae30","description":"\uc81c\ucd9c\ud560 \ub54c \ub514\ubc84\uae45 \ucd9c\ub825\uc744 \uc228\uae30\uae30","date":"2026-10-29T23:56:14.559Z","tags":[{"inline":false,"label":"\uae30\uc220","permalink":"/tags/tech"}],"readingTime":1.96,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"hide-debug-output-on-submission","title":"\uc81c\ucd9c\ud560 \ub54c \ub514\ubc84\uae45 \ucd9c\ub825\uc744 \uc228\uae30\uae30","date":"2026-10-29T23:56:14.559Z","authors":"hyoyoonnam","tags":["\uae30\uc220"],"image":"./cover.png"},"unlisted":false,"prevItem":{"title":"\uce74\uce74\uc624\ub85c \ub9de\uc740 \ub0a0","permalink":"/a-day-of-kakao-problems"},"nextItem":{"title":"\ud504\ub85c\uadf8\ub798\uba38\uc2a4\ub97c \ud480\uc5c8\ub2e4. \uadf8\ub7f0\ub370 1\ub144 6\uac1c\uc6d4 \ub9cc\uc5d0..","permalink":"/back-to-programmers"}},"content":"![\uc81c\ucd9c\ud560 \ub54c \ub514\ubc84\uae45 \ucd9c\ub825\uc744 \uc228\uae30\uae30](./cover.png)\\n\\n\uc774 \uae00\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc608\uc81c \ucf54\ub4dc\ub294 **Java**\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, [\uacf5\uc6d0 \uc0b0\ucc45 | \ud504\ub85c\uadf8\ub798\uba38\uc2a4](https://school.programmers.co.kr/learn/courses/30/lessons/172928) \ud480\uc774\uc758 \uc77c\ubd80\uc785\ub2c8\ub2e4.\\n\\n**\uc774 \uae00\uc744 \uc77d\uc73c\uba74:**\\n\\n```text\\n\ud480\uc774\uac00 \ud5f7\uac08\ub824\uc11c \uc911\uac04 \ucd9c\ub825\uc774 \ud544\uc694\ud55c \ubb38\uc81c\uc5d0\uc11c \uc6d0\ud558\ub294 \ub300\ub85c \ucd9c\ub825\ud558\uba74\uc11c\ub3c4,\\n\ucc44\uc810 \uacb0\uacfc\uc5d0\ub294 \uc911\uac04 \ucd9c\ub825\uc774 \ud3ec\ud5d8\ub418\uc9c0 \uc54a\uac8c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n```\\n\\n\x3c!-- truncate --\x3e\\n\\n## \uacb0\ub860\ubd80\ud130\\n\\n\uc544\ub798 \ucf54\ub4dc \ube14\ub85d\uc5d0 \uc788\ub294 `print(String format, Object... args)` \uba54\uc11c\ub4dc\ub97c \uc815\uc758\ud574\uc11c \uc0ac\uc6a9\ud558\uba74 \ub41c\ub2e4.\\n\\n```java\\n// \uc608\uc2dc 1\\nprint(\\"\uc774\ub3d9 \uac00\ub2a5?: now=%s(%d, %d)%n\\", mat[x][tempY], x, tempY);\\nprint(\\"\uc774\ub3d9 \uac00\ub2a5!: now=%s(%d, %d)%n\\", mat[x][tempY], x, tempY);\\nprint(\\"\uc774\ub3d9(Y): %d -> %d%n\\", y, tempY);\\n// \uc608\uc2dc 2\\nprint(\\"=== %d\ubc88 \uc9f8(start_%s) | oper_%s ===%n\\", count++, start, oper);\\n\\n\\npublic static final boolean DEBUG_MODE = false;\\n\\nprivate static void print(String format, Object... args) {\\n    if (DEBUG_MODE) System.out.printf(format, args);\\n}\\n```\\n\\n## \ub0b4\uac00 \uacaa\uc740 \uc5b4\ub824\uc6c0\\n\\n\ubb38\uc81c\ub97c \ud480 \ub54c \ud0d0\uc0c9 \ubc94\uc704\uc640 \uae30\uc900\uc774 \ud5f7\uac08\ub824\uc11c \ucd08\ubc18\uc5d0 \ud5e4\ub9f8\ub2e4.. \uadf8\ub798\uc11c \uc911\uac04\uc911\uac04 \uacb0\uacfc\ub97c \ucd9c\ub825\ud560 \ud544\uc694\ub97c \ub290\uaf08\uace0, \ucc98\uc74c\uc5d0\ub294 \ub2e8\uc21c\ud788 `System.out.println()`\uc73c\ub85c \ucd9c\ub825\ud588\ub2e4.\\n\\n\uadf8\ub7ac\ub354\ub2c8 <u>\ubc18\ubcf5\ub418\ub294 \ucd9c\ub825 \uba54\uc11c\ub4dc \ud0c0\uc774\ud551</u>\uacfc <u>\uac12 \ub514\ubc84\uae45\uc744 \uc704\ud55c \ubb38\uc790\uc5f4 </u>`+`<u> \uc5f0\uc0b0</u> \ub4f1\uc73c\ub85c \uc778\ud574 \ud53c\ub85c\ud574\uc84c\uace0, \ub450 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 `print()` \uba54\uc11c\ub4dc\ub97c \uc815\uc758\ud588\ub2e4.\\n\\n```java\\nprivate static void print(String format, Object... args) {\\n    System.out.printf(format, args);\\n}\\n```\\n\\n* <u>\ubc18\ubcf5\ub418\ub294 \ucd9c\ub825 \uba54\uc11c\ub4dc \ud0c0\uc774\ud551</u>\uc740 \uba54\uc11c\ub4dc\ub85c \ub9cc\ub4e0 \uadf8 \uc790\uccb4\ub85c \ud574\uacb0\ud55c\ub2e4.\\n* <u>\uac12 \ub514\ubc84\uae45\uc744 \uc704\ud55c \ubb38\uc790\uc5f4 + \uc5f0\uc0b0</u>\uc740 `printf()`\uc640 \uac00\ubcc0\uc778\uc790 `Object... args`\ub85c \ud574\uacb0\ud55c\ub2e4.\\n\\n## \ud480\uc774 \ucf54\ub4dc \uc6d0\ubb38 \uc911 \uc77c\ubd80\\n\\n```java\\n    public static char[][] mat = new char[55][55];\\n    public static int ROW_SIZE;\\n    public static int COL_SIZE;\\n\\n    public int[] solution(\\n        String[] park, // S, O, X \uc911 \ud558\ub098\\n        String[] routes // \uac15\uc544\uc9c0\uac00 \uc218\ud589\ud560 \uba85\ub839. \\"op n\\" \ud615\ud0dc. op=\uc774\ub3d9 \ubc29\ud5a5, n=\uce78 \uc218\\n    ) {\\n        ROW_SIZE = park.length - 1;\\n        COL_SIZE = park[0].length() - 1;\\n\\n        Pos start = new Pos();\\n        print(\\"<ROW_SIZE=%d, COL_SIZE=%d>%n\\", ROW_SIZE, COL_SIZE);\\n        for (int row = 0; row < ROW_SIZE + 1; row++) {\\n            for (int col = 0; col < COL_SIZE + 1; col++) {\\n                char target = park[row].charAt(col);\\n                mat[row][col] = target;\\n                if (target == \'S\') start = new Pos(row, col);\\n            }\\n        }\\n\\n        for (int row = 0; row < ROW_SIZE + 1; row++) {\\n            for (int col = 0; col < COL_SIZE + 1; col++) {\\n                print(\\"%s \\", mat[row][col]);\\n            }\\n            print(\\"%n\\");\\n        }\\n\\n        int count = 1;\\n        for (String oper : routes) {\\n            print(\\"=== %d\ubc88 \uc9f8(start_%s) | oper_%s ===%n\\", count++, start, oper);\\n            if (start.canMoveTo(oper)) {\\n                start.move(oper);\\n            }\\n        }\\n\\n        int[] answer = {start.x, start.y}; // \ubaa8\ub4e0 \uba85\ub839\uc744 \uc218\ud589 \ud6c4 \uac15\uc544\uc9c0\uac00 \ub193\uc778 \uc704\uce58: [\uc138\ub85c, \uac00\ub85c]\\n        return answer;\\n    }\\n```\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/328)"},{"id":"back-to-programmers","metadata":{"permalink":"/back-to-programmers","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-28-back-to-programmers/index.md","source":"@site/blog/2026-10-28-back-to-programmers/index.md","title":"\ud504\ub85c\uadf8\ub798\uba38\uc2a4\ub97c \ud480\uc5c8\ub2e4. \uadf8\ub7f0\ub370 1\ub144 6\uac1c\uc6d4 \ub9cc\uc5d0..","description":"\ud504\ub85c\uadf8\ub798\uba38\uc2a4\ub97c \ud480\uc5c8\ub2e4. \uadf8\ub7f0\ub370 1\ub144 6\uac1c\uc6d4 \ub9cc\uc5d0..","date":"2026-10-27T15:32:08.750Z","tags":[{"inline":false,"label":"\uae30\uc220","permalink":"/tags/tech"}],"readingTime":2.54,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"back-to-programmers","title":"\ud504\ub85c\uadf8\ub798\uba38\uc2a4\ub97c \ud480\uc5c8\ub2e4. \uadf8\ub7f0\ub370 1\ub144 6\uac1c\uc6d4 \ub9cc\uc5d0..","date":"2026-10-27T15:32:08.750Z","authors":"hyoyoonnam","tags":["\uae30\uc220"],"image":"./cover.jpg"},"unlisted":false,"prevItem":{"title":"\uc81c\ucd9c\ud560 \ub54c \ub514\ubc84\uae45 \ucd9c\ub825\uc744 \uc228\uae30\uae30","permalink":"/hide-debug-output-on-submission"},"nextItem":{"title":"\uc0c1\ub300\ub97c \ubd88\uc30d\ud788 \uc5ec\uae30\ub294 \ub9c8\uc74c","permalink":"/a-moment-of-compassion"}},"content":"![\ud504\ub85c\uadf8\ub798\uba38\uc2a4\ub97c \ud480\uc5c8\ub2e4. \uadf8\ub7f0\ub370 1\ub144 6\uac1c\uc6d4 \ub9cc\uc5d0..](./cover.jpg)\\n\\n## \uc7a1\uc124\\n\\n### \uafb8\uc900\ud568\uc774 \ubb34\uae30\ub2e4\\n\\n<figure>\\n\\n![250. \uc81c\ub274\ubbf8\uc2a4\ud2b8\uc758 \ub9dd\ud1a0(2) - \uc81c\ub274\ubbf8\uc2a4\ud2b8\uc758 \ub9dd\ud1a0](./ordinary-twig.png)\\n\\n<figcaption>\ud3c9\ubc94\ud55c \ub098\ubb47\uac00\uc9c0 | \uc5f0\uc131\uc73c\ub85c \ub9cc\ub4e4\uc5b4\ub0b8 \ud3c9\ubc94\ud574 \ubcf4\uc774\ub294 \ub098\ubb47\uac00\uc9c0\uc774\ub2e4. \ud2b9\ubcc4\ud55c \ud798\uc774 \uc788\uc744 \uac83 \uac19\uc9c0\ub294 \uc54a\ub2e4. (<a href=\\"https://zyquest.tistory.com/270\\">\uc774\ubbf8\uc9c0 \ucd9c\ucc98</a>)</figcaption>\\n</figure>\\n\\n\u3134 \uadf8\ub9ac\uace0 \ub0b4 \ubb34\uae30..\\n\\n\x3c!-- truncate --\x3e\\n\\n![image.png](./solving-history.png)\\n\\n\uae30\ub85d\uc744 \ubcf4\ub2c8\uae4c *25\ub144 \uc5ec\ub984* \uc815\ub3c4\uae4c\uc9c0\ub294 \ubb38\uc81c\ub97c \ud480\ub358 \uae30\ub85d\uc774 \uc788\ub294\ub370, \uadf8 \ub4a4\ub85c\ub294 \uc5c6\ub2e4. \uadf8\ub798\uc11c \ub2e4\uc2dc re-zero..?\\n\\n### \ub8e8\ub4dc\ube44\ucf54\ub294 \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 \ub420 \uc218\ub3c4 \uc788\uc5c8\ub2e4..?\\n\\n![image.png](./javascript-history.png)\\n\\njs\ub85c\ub3c4 \ud480\uc5c8\uc5c8\ub124.. \ub124\ubd80\ucea0 \uc900\ube44\ud558\ub358 \ub550\uac00? \uc0c8\ub85c\uc6b4 \uc5b8\uc5b4\ub97c \uc0ac\uc6a9\ud55c\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \ubb54\uac00 \ub354 \uc124\ub808\uace0 \uc7ac\ubc0c\uc5c8\ub358 \uae30\uc5b5\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uc2e4 \uadf8\ub54c \ub2f9\uc2dc\uc5d0\ub294 \ub9e4\uc77c \ucd94\uac00\ub418\ub294 \ubbf8\uc158\uc774 \ub108\ubb34............. \uc5b4\ub824\uc6cc\uc11c \ub9e8\ub0a0 \ubc24\uc0c8\uace0 \uc624\ud6c4 4\uc2dc\uc5d0 \ub0ae\uc7a0\uc790\uace0\ub97c \ubc18\ubcf5\ud558\ub294 \uc544\uc8fc \ub9dd\uac00\uc9c0\uace0 \ud798\ub4e4\ub358 \uc0b6\uc774\uc5c8\ub294\ub370, \uc9c0\ub098\uace0 \ubcf4\ub2c8 \ub610 \uc88b\uc740 \uae30\uc5b5\uc774 \ub9ce\uc774 \ub0a8\ub294\ub2e4..-\\n\\n## \uc774\ubc88 \ub3c4\uc804\uc758 \uccab \ubb38\uc81c\ub294\\n\\n`\ub2ec\ub9ac\uae30 \uacbd\uc8fc | \uc5f0\uc2b5\ubb38\uc81c | Lv. 1`\ub97c \ud480\uc5c8\ub2e4.\\n\\n![image.png](./running-race.png)\\n\\n### \ub0b4 \ud480\uc774\\n\\n```java\\nimport java.util.*;\\n\\nclass Solution {\\n    // \ucd94\uc6d4\ud560 \ub54c \uc120\uc218\uc758 \uc774\ub984\uc744 \ubd80\ub978\ub2e4\\n    public String[] solution(\\n        String[] players, // 1\ub4f1\ubd80\ud130 \ud604\uc7ac \ub4f1\uc218 \uc21c\uc11c\ub300\ub85c \ub2f4\uae40. \uc120\uc218\uc758 \uc774\ub984\\n        String[] callings // \uc120\uc218\uc758 \uc774\ub984\uc744 \ubd80\ub974\ub294 \uc21c\uc11c\\n    ) {\\n        Map<String, Integer> playerOrderMap = new HashMap<>();\\n        for (int i = 0; i < players.length; i++) {\\n            playerOrderMap.put(players[i], i);\\n        }\\n\\n        // 1. \uc774\ub984\uc744 \ubd80\ub978\ub2e4\\n        for (String calling : callings) {\\n            int order = playerOrderMap.get(calling); // 2\ub4f1\\n            String temp = players[order-1]; // 1\ub4f1\\n\\n            players[order-1] = players[order]; // 2\ub4f1(order) \uc120\uc218\ub97c 1\ub4f1\uc73c\ub85c\\n            players[order] = temp; // 1\ub4f1(order-1) \uc120\uc218\ub97c 2\ub4f1\uc73c\ub85c\\n\\n            playerOrderMap.put(calling, order - 1); // \ucd94\uc6d4\\n            playerOrderMap.put(temp, order); // \ucd94\uc6d4\ub2f9\ud568\\n        }\\n\\n\\n        // \uc120\uc218\ub4e4 \uc774\ub984. 1\ub4f1, ...,  n\ub4f1\\n        return players;\\n    }\\n}\\n```\\n\\n### \ubcf5\uae30\\n\\n\ucc98\uc74c\uc5d0\ub294 `Map`\uc5c6\uc774 `for (String calling : callings) { brute-force : players }`\ub85c \ud480\uc5c8\uace0, \uc2dc\uac04 \ucd08\uacfc\uac00 \ub0ac\ub2e4. \uc5ec\uae30\uae4c\uc9c0\ub294 ok. \uc2e4\ud328\ub97c \uc5fc\ub450\ud55c \ube60\ub978 \ud480\uc774\uc6a9 \uc811\uadfc\uc774\uc5c8\uace0, \\"\uc5b4\ucc28\ud53c Map\uc744 \uc0ac\uc6a9\ud574\uc57c \ub418\uae34 \ud558\uaca0\ub294\ub370\\"\ub77c\ub294 \uc9c1\uad00\uc744 \uac00\uc9c0\uace0, \uac04\ub2e8\ud55c \ud480\uc774\ub85c\ubd80\ud130 \uc811\uadfc\uc774 \ub9de\ub294\uc9c0\ub97c \ud310\ub2e8\ud558\uae30 \uc704\ud574\uc11c\uc600\ub2e4.\\n\\n#### \ubb38\uc81c \ubc1c\uacac\\n\\n\uadf8\ub7f0\ub370 \uadf8 \ub4a4\uc5d0 `temp`\ub97c \uc0ac\uc6a9\ud574\uc11c n\ub4f1 \uc120\uc218\uc640 n-1\ub4f1 \uc120\uc218\ub97c swap\ud560 \ub54c \ub9ce\uc774 \ud2c0\ub838\ub2e4.\\n\\n```java\\nplayerOrderMap.put(calling, order - 1); // \ucd94\uc6d4\\n// \uac1c\uc120 \ud480\uc774: [order-1]\uc5d0 \uc788\ub358 \ud50c\ub808\uc774\uc5b4\ub294 temp\uc5d0 \ubcf4\uad00\\nplayerOrderMap.put(temp, order); // \ucd94\uc6d4\ub2f9\ud568\\n// \uae30\uc874\uc5d0 \ud2c0\ub9b0 \ud480\uc774: \uc774\ubbf8 [order-1]\uc758 \ud50c\ub808\uc774\uc5b4\ub97c \ubc14\uafe8\ub294\ub370, \uadf8\uac78 \ubc14\uafb8\uae30 \uc804 [order-1] \ud50c\ub808\uc774\uc5b4\ub85c \uc0ac\uc6a9\ud568\\n// playerOrderMap.put(players[order-1], order);\\n```\\n\\n* `playerOrderMap.put(temp, order)` \ubd80\ubd84\uc744 `playerOrderMap.put(players[order-1], order)`\ub85c \uc798\ubabb \ud480\uc774\ud558\ub2c8 \uc6d0\ub798 n-1\ub4f1 \uc120\uc218\uac00 \uc9c0\uc6cc\uc9c0\uace0, n\ub4f1 \uc120\uc218\uac00 \uadf8 \uc790\ub9ac\ub97c \uc911\ubcf5 \ub300\uccb4\ud55c\ub2e4.\\n\\n\uc624\ub79c\ub9cc\uc5d0 \ud480\uc5b4\uc11c \uadf8\ub7f0\uac00.. \uc774\uac8c \ub208\uc5d0 \uc548 \ubcf4\uc5ec\uc11c \ud504\ub9b0\ud2b8\uae4c\uc9c0 \ucc0d\uc5b4\uac00\uba70 \uaca8\uc6b0 \ucc3e\uc558\ub2e4.\\n\\n```shellscript\\nkai\uac00 poe\ub97c \ucd94\uc6d4\\n# bug: poe\uac00 \uc0ac\ub77c\uc9c0\uace0 kai\uac00 \uc911\ubcf5 \ub300\uccb4\\n\ud604\uc7ac \uc21c\uc11c: mumu,soe,kai,kai,mine,\\nkai\uac00 kai\ub97c \ucd94\uc6d4\\n# bug: kai\uac00 \uc0ac\ub77c\uc9c0\uace0 mine\uc774 \uc911\ubcf5 \ub300\uccb4\\n\ud604\uc7ac \uc21c\uc11c: mumu,soe,kai,kai,mine,\\nmine\uac00 kai\ub97c \ucd94\uc6d4\\n\ud604\uc7ac \uc21c\uc11c: mumu,soe,kai,mine,mine,\\nmine\uac00 mine\ub97c \ucd94\uc6d4\\n\ud604\uc7ac \uc21c\uc11c: mumu,soe,kai,mine,mine,\\n```\\n\\n#### \ub2e4\uc74c\uc5d0 \ub354 \uc798 \ud558\ub824\uba74\\n\\n\uc218\uc0c1\ud558\uac8c \ubb38\uc81c\ub97c \uc798 \ud478\ub294 \uc624\ub9ac\uac00 \uc788\ub2e4. \uadf8 \ub140\uc11d\uc744 \uc5ff\ubcf4\uc558\ub2e4. \ub0b4\uac00 swap\uc5d0\uc11c \ud5e4\ub9ec \ub54c `temp`\uac00 \ubb50\uace0 `players[order]`\uac00 \ubb50\uace0, `players[order-1]`\uac00 \ubb50\uace0, ... \ud5f7\uac08\ub824\uc11c \ud2b9\ud788 \ud798\ub4e4\uc5c8\ub294\ub370, \uc774 \uc624\ub9ac\ub294 `frontName`\uc774\ub77c\ub294 \ubcc0\uc218\uba85\uc744 \uc0ac\uc6a9\ud558\ub354\ub77c. `front`\ub77c\ub294 \ud45c\ud604\uc774 \uc88b\ub2e4\uace0 \ub290\uaf08\ub2e4.\\n\\n\uadf8\ub798\ub3c4 \uc624\ub9ac\uac00 \ud480\uc774\ub97c \uce6d\ucc2c\ud574\uc92c\ub294\ub370 \uc775\uc0ac\ud558\ub824\ub294 \ub274\ube44\uc758 \ubaa9\uc904\uc744 \uc7a1\uace0 \ubaa8\uc784\uc5d0\uc11c \ube60\uc838\ub098\uac00\uc9c0 \ubabb\ud558\uac8c \ud558\ub294 \uac74\uc9c0... \uc544\uc9c1\uc740 \uc798 \ubaa8\ub974\uaca0\ub2e4.\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/313)"},{"id":"a-moment-of-compassion","metadata":{"permalink":"/a-moment-of-compassion","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-27-a-moment-of-compassion/index.md","source":"@site/blog/2026-10-27-a-moment-of-compassion/index.md","title":"\uc0c1\ub300\ub97c \ubd88\uc30d\ud788 \uc5ec\uae30\ub294 \ub9c8\uc74c","description":"\uc0c1\ub300\ub97c \ubd88\uc30d\ud788 \uc5ec\uae30\ub294 \ub9c8\uc74c","date":"2026-10-26T20:57:30.920Z","tags":[{"inline":false,"label":"\uae30\uc220","permalink":"/tags/tech"}],"readingTime":1.15,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"a-moment-of-compassion","title":"\uc0c1\ub300\ub97c \ubd88\uc30d\ud788 \uc5ec\uae30\ub294 \ub9c8\uc74c","date":"2026-10-26T20:57:30.920Z","authors":"hyoyoonnam","tags":["\uae30\uc220"],"image":"./cover.png"},"unlisted":false,"prevItem":{"title":"\ud504\ub85c\uadf8\ub798\uba38\uc2a4\ub97c \ud480\uc5c8\ub2e4. \uadf8\ub7f0\ub370 1\ub144 6\uac1c\uc6d4 \ub9cc\uc5d0..","permalink":"/back-to-programmers"},"nextItem":{"title":"\ucc45\uc744 \ub450 \uad8c \uc0c0\uc9c0\ub9cc, \uc774\uc804\ubcf4\ub2e4\ub294 \ubb34\ub364\ub364\ud55c \ud558\ub8e8","permalink":"/buying-two-books"}},"content":"![\uc0c1\ub300\ub97c \ubd88\uc30d\ud788 \uc5ec\uae30\ub294 \ub9c8\uc74c](./cover.png)\\n\\n\uc544\ub9c8\ub3c4 2-3\uc8fc \uc804\uc774\uc5c8\uc744\uae4c. \uc5b4\uc9f8\uc11c\uc778\uc9c0 \ub208\uc774 \uc77c\ucc0d \ub5a0\uc838 \ud0c4\ucc9c\uc73c\ub85c \ub7ec\ub2dd\uc744 \ub098\uac14\ub2e4. \uc0c8\ubcbd\uc774 \uc9c0\ub098 \ud0dc\uc591\ube5b\uc774 \ud478\ub974\uac8c \ubcf4\uc774\ub294 \uc2dc\uac04\uc774\uc5c8\ub2e4. \uac00\ubccd\uac8c 2Km \uc815\ub3c4\ub97c \ub6f0\uace0 \uc704\ub85c \uc62c\ub77c\uac00\uace0 \uc788\uc5c8\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n\uc791\uc5c5\ucc28\ub7c9\ub4e4\uc774 \uc624\uac08 \uc218 \uc788\uac8c \ub113\uc740 \uc544\uc2a4\ud314\ud2b8\ub85c \ub41c \uc624\ub974\ub9c9\uc774\uc5c8\uc9c0\ub9cc, \ud3c9\uc18c\uc5d0\ub294 \ucc28\ub7c9 \ucd9c\uc785\uc744 \uc81c\ud55c\ud558\uae30 \uc704\ud574 \ucca0\uc81c \ud39c\uc2a4\ub85c \ub9c9\uc544\ub454, \uadf8\ub798\uc11c \uc0ac\ub78c 1\uba85 \uc815\ub3c4\uac00 \ub4dc\ub098\ub4e4 \uc218 \uc788\ub294 \uc881\uc74c\uc774\uc5c8\ub2e4.\\n\\n[\uc624\ub974\ub9c9 \uc0ac\uc9c4 \ucca8\ubd80]\\n\\n\ub9c9 \ub7ec\ub2dd\uc774 \ub05d\ub09c \ucc38\uc778 \ub098\ub294 \ud5e5\ud5e5\uac70\ub9ac\uba70 \uc624\ub974\ub9c9\uc744 \uc62c\ub77c \uac14\uace0, \ub0b4 \ub4a4\ub85c\ub294 \uc5ec\uc720\ub86d\uac8c \uc0b0\ucc45\ud55c \uac78\ub85c \ubcf4\uc774\ub294 \uc911\ub144\uc758 \ub0a8\uc131\uc774 \ub530\ub77c\uc654\ub2e4.\\n\\n\uadf8\ub9ac\uace0 \uc624\ub974\ub9c9\uc744 \ub2e4 \uc62c\ub77c\uc628 \ub0b4 \uc606\uc73c\ub85c\ub294 \uc790\uc804\uac70\ub97c \ud0c4 \uc911\ub144\uc758 \ub0a8\uc131(\ud558\uc9c0\ub9cc \ubc11\uc5d0\uc11c \uc62c\ub77c\uc624\uace0 \uc788\ub294 \ub0a8\uc131\ubcf4\ub2e4\ub294 \uc5b4\ub9b0 \ub4ef\ud55c)\uc774 \uc9c0\ub098\uac14\ub2e4.\\n\\n\uc774 \ub458\uc774 \uc9c0\ub098\ub824\ub294 \uacf3\uc740 \uac19\uc558\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \uc9c0\ub098\uac08 \uc21c \uc5c6\uc5c8\ub2e4. \uc2ec\uc9c0\uc5b4 \uc62c\ub77c\uc624\uace0 \uc788\ub294 \ub0a8\uc790\ub294 \ud578\ub4dc\ud3f0\uc744 \ubcf4\uace0 \uc788\uc5c8\uace0, \uc790\uc804\uac70\ub97c \ud0c4 \ub0a8\uc790\uac00 \ud578\ub4dc\ud3f0 \ubcf4\ub294 \ub0a8\uc790\uc758 \ubaab\uae4c\uc9c0 \ud53c\ud574\uc57c \ub418\ub294 \uaf64\ub098 \ub2e4\uae09\ud55c \uc0c1\ud669\uc774\uc5c8\ub098 \ubcf4\ub2e4.\\n\\n\uadf8\ub798\ub3c4 \uc790\uc804\uac70\ub97c \ub0a0\ub835\ud558\uac8c \uc6c0\uc9c1\uc600\ub294\uc9c0, \uc0ac\uace0\ub294 \ub098\uc9c0 \uc54a\uc558\ub2e4. \ub300\uc2e0 \ub108\ubb34 \ub180\ub77c\uc11c\uc778\uc9c0 \\"\uc5d0\uc774\uc528..\\"\ub77c\uace0 \uc911\uc5bc\uac70\ub9ac\uba70 \ub9c8\uc800 \ub0b4\ub824\uac00\ub294 \ub0a8\uc790\uac00 \uc788\uc5c8\ub2e4.\\n\\n\ud578\ub4dc\ud3f0 \ub0a8\uc790\ub294 \uc5ec\uc804\ud788 \ud578\ub4dc\ud3f0\uc5d0 \uc9d1\uc911\ud558\uba74\uc11c\ub3c4 \uadf8 \ub9d0\ub9cc\uc740 \ub610\ub837\uc774 \ub4e4\uc5c8\ub294\uc9c0 \\"\uc544\uc800\uc528, \uc9c0\uae08 \ubb50\ub77c\uace0 \ud588\uc5b4\uc694!\\"\ub77c\uba70 \uc11c\ub85c \uc5b8\uc131\uc774 \ub192\uc544\uc9c0\uae30 \uc2dc\uc791\ud588\ub2e4.\\n\\n...\\n\\n\uc774\uac78 \ubcf4\uace0 \ub0b4\uac00 \ub290\ub080 \uac10\uc815\uc740 \ubd88\uc30d\ud568\uacfc \uce21\uc740\ud568\uc774\uc5c8\ub2e4. \ub098\uc5d0\uac8c \uc788\uc5b4 \uc544\uce68\uc5d0 \ub098\uc640\uc11c \ubc14\uae65 \uacf5\uae30\ub97c \ub204\ub9ac\ub294 \uac74 \uac10\uc0ac\ud558\uba74\uc11c\ub3c4 \uc804 \ub0a0\ubd80\ud130\uc758 \uc774\ub978 \ucde8\uce68\uc774\ub77c\ub294 \uc900\ube44\uc640, \uc544\uce68\uc5d0 5\ubd84\ub9cc \ub354 \uc774\ubd88 \uc18d\uc5d0 \uc788\uace0\ud508 \ub9c8\uc74c. \uadf8\ub7f0 \uc5ec\ub7ec\uac00\uc9c0 \uac83\ub4e4\uc774 \uc870\ud569\ub418\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud55c \ud589\uc704\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \uc870\ud569\uc758 \uacb0\uacfc\ubb3c\uc744 \uc77c\uc21c\uac04\uc744 \ucc38\uc9c0 \ubabb\ud574\uc11c \ub9dd\uccd0\ubc84\ub9ac\ub2e4\ub2c8. \uc544\ub9c8 \uadf8 \ub458\uc758 \ud558\ub8e8\ub294 \uac00\uc871\uc5d0\uac8c \uc0c1\ub300\ub97c \uc695\ud558\uac70\ub098, \ud63c\uc790\uc11c \ud68c\uc0c1\ud558\uba70 \uae30\ubd84 \ub098\ube60\ud558\ub294 \ud558\ub8e8\uac00 \uc544\ub2c8\uc5c8\uc744\uae4c.\\n\\n![\u1109\u1173\u110f\u1173\u1105\u1175\u11ab\u1109\u1163\u11ba 2026-10-26 20.52.30.png](./cover.png)\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/288)"},{"id":"buying-two-books","metadata":{"permalink":"/buying-two-books","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-24-buying-two-books/index.md","source":"@site/blog/2026-10-24-buying-two-books/index.md","title":"\ucc45\uc744 \ub450 \uad8c \uc0c0\uc9c0\ub9cc, \uc774\uc804\ubcf4\ub2e4\ub294 \ubb34\ub364\ub364\ud55c \ud558\ub8e8","description":"\ucc45\uc744 \ub450 \uad8c \uc0c0\uc9c0\ub9cc, \uc774\uc804\ubcf4\ub2e4\ub294 \ubb34\ub364\ub364\ud55c \ud558\ub8e8","date":"2026-10-23T15:27:35.344Z","tags":[{"inline":false,"label":"\ud68c\uace0","permalink":"/tags/retrospective"}],"readingTime":1.66,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"buying-two-books","title":"\ucc45\uc744 \ub450 \uad8c \uc0c0\uc9c0\ub9cc, \uc774\uc804\ubcf4\ub2e4\ub294 \ubb34\ub364\ub364\ud55c \ud558\ub8e8","date":"2026-10-23T15:27:35.344Z","authors":"hyoyoonnam","tags":["\ud68c\uace0"],"image":"./postcard.jpg"},"unlisted":false,"prevItem":{"title":"\uc0c1\ub300\ub97c \ubd88\uc30d\ud788 \uc5ec\uae30\ub294 \ub9c8\uc74c","permalink":"/a-moment-of-compassion"},"nextItem":{"title":"\ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub41c\ub2e4.","permalink":"/on-marriage-and-single-life"}},"content":"![\ucc45\uc744 \ub450 \uad8c \uc0c0\uc9c0\ub9cc, \uc774\uc804\ubcf4\ub2e4\ub294 \ubb34\ub364\ub364\ud55c \ud558\ub8e8](./postcard.jpg)\\n\\n## \ucc45 \uc0c0\uc5b4\uc694.\\n\\n\ucc45\uc744 \uc0c0\ub2e4. `<\ud0dc\uc5fd \uac10\ub294 \uc0c8 1 - \ubb34\ub77c\uce74\ubbf8 \ud558\ub8e8\ud0a4>`\ub97c..\\n\\n\x3c!-- truncate --\x3e\\n\\n<figure>\\n\\n![IMG_2332.jpeg](./wind-up-bird.jpg)\\n\\n<figcaption>\uc54c\ub77c\ub518 \uc911\uace0\uc11c\uc810\uc5d0\uc11c \uad6c\ub9e4\ud55c &lt;\ud0dc\uc5fd \uac10\ub294 \uc0c8 1 - \ubb34\ub77c\uce74\ubbf8 \ud558\ub8e8\ud0a4&gt;</figcaption>\\n</figure>\\n\\n\uc54c\ub77c\ub518 \uc911\uace0\uc11c\uc810\uc5d0\uc11c \uc0c0\ub354\ub2c8 4,900\uc6d0\uc778\ub370 \ub108\ubb34 \uc800\ub834\ud558\uc9c0 \uc54a\uc740\uac00..? \uadf8\ub0e5 \uae30\ubd84\uc774 \uc88b\uc558\ub2e4. \ub098\ub97c \ub354 \uae30\ubd84\uc88b\uac8c \ud558\ub294 \uac74, **\uc219\uc131\ub41c \ucc45**\uc774\ub77c\ub294 \uc810.\\n\\n<figure>\\n\\n![IMG_2333.jpeg](./postcard.jpg)\\n\\n<figcaption>2008\ub144\uc774 \ub9cc\ub8cc\uc778 \uc6b0\ud3b8\uc5fd\uc11c\uac00 \ucc45\uc5d0 \ub3d9\ubd09\ub418\uc5b4 \uc788\ub2e4..</figcaption>\\n</figure>\\n\\n\uc544, \uadf8\ub9ac\uace0 \ud328\ube0c\ub9ad \ubd81\ucee4\ubc84\ub3c4 \uc0c0\ub2e4. 10800\uc6d0\uc778\uac00..?\\n\\n## \uadf8\ub7f0\ub370...\\n\\n\uc5ec\uae30\uc11c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud55c\ub2e4. \uacc4\uc0b0\ub300\uc5d0\uc11c \ubc14\ucf54\ub4dc \ucc0d\ub294 \uc18c\ub9ac\uac00 \ub450 \ubc88, \uc810\uc6d0\uc774 \ub0b4\uac8c \ub9d0\ud55c\ub2e4.\\n\\n> \\"20,000\uc6d0 \uc774\uc0c1 \uad6c\ub9e4\ud558\uc2dc\uba74 3,000\uc6d0 \ud560\uc778\uc778\ub370 \uadf8\ub300\ub85c \uacb0\uc81c\ud560\uae4c\uc694?\\"\\n\\n\uc9c0\ub09c \ubc88\uc5d0\ub3c4 \uac19\uc740 \uc0c1\ud669\uc774 \uc788\uc5c8\ub2e4. \uadf8\ub54c\ub294 \\"\ub354 \uad6c\ub9e4\ud574\uc11c \ud560\uc778\ubc1b\ub294 \uac83\uc774, \ud560\uc778\ubc1b\uc9c0 \uc54a\ub294 \uac83\ubcf4\ub2e4 \uc190\ud574\ub2e4\\"\ub77c\ub294 \uc0dd\uac01\uc73c\ub85c\\n\\n> \\"\uadf8\ub0e5 \uacb0\uc81c\ud574 \uc8fc\uc138\uc694.\\"\\n\\n\ub77c\uace0 \ub9d0\ud55c \ub4a4 \uc9d1\uc73c\ub85c \ud5a5\ud588\ub2e4.\\n\\n## \uadf8\ub7f0\ub370 \uc65c..?\\n\\n\uc65c \uc624\ub298\uc740\\n\\n> \\"\uc544, \uadf8\ub7fc \ub354 \ub458\ub7ec\ubcfc\uac8c\uc694.\\"\\n\\n\ub77c\ub294 \ub9d0\uc774 \ub098\uc654\uc744\uae4c..?\\n\\n\uadf8\ub807\uac8c \uad6c\ub9e4 \uac00\uaca9\uc744 \ucc44\uc6b0\uae30 \uc704\ud55c \ucc45 \ud0d0\ubc29\uc774 \uc2dc\uc791\ub418\uc5c8\uace0, \uc774\uc655 \uad6c\ub9e4\ud560 \ucc45 \uc9c4\uc9dc \uad00\uc2ec\uac00\ub294 \ucc45\uc744 \uace0\ub974\uace0\uc790 \uc601\ubbf8 \ubb38\ud559, \uc77c\ubcf8 \ubb38\ud559, \uad50\uc591 \uacfc\ud559, \ubbfc\uc74c\uc0ac \uc138\uacc4\ubb38\ud559\uc804\uc9d1, ... \ub3c4\uc11c \ucf54\ub108 \uc5ec\uae30\uc800\uae30\ub85c \uc62e\uaca8 \ub2e4\ub154\ub2e4.\\n\\n\uadf8\ub7f0\ub370... \ubcf4\uc774\uc9c8 \uc54a\ub294\ub2e4. \ub9c8\uc74c \ub04c\ub9ac\ub294 \ucc45\uc774 \uc548 \ubcf4\uc778\ub2e4.\\n\\n\uc54c\ub77c\ub518 \ub0b4\ubd80\ub294 \ub365\ub2e4.. \uae34\ud314 + \uc587\uc740 \ud328\ub529 + \ud2b8\ub80c\uce58 \ucf54\ud2b8\ub97c \uc785\uace0 \uc788\uc5c8\ub2e4. \ud2b8\ub80c\uce58 \ucf54\ud2b8\ub294 \uc774\ubbf8 \ub0b4 \ud314\uc5d0 \uac78\uccd0\uc9c4 \uc9c0 \uc624\ub798\ub2e4. \ud328\ub529\uae4c\uc9c0 \uac00\uc138\ud558\uba74 \ud314\uc774 \ub108\ubb34 \ud798\ub4e4\uae4c \ubab8\uc5d0\uc11c \ubc18\ucbe4 \ubc97\uc740 \ucc44 \ud718\ub0a0\ub9ac\uba70 \ub2e4\ub2c8\uace0 \uc788\uc5c8\ub2e4.\\n\\n\uadf8\ub798\uc11c \ub354\uc704\ub3c4 \ubc18\ucbe4 \uc62c\ub77c\uc628\ub2e4.. \ud314\uc774 \ubb34\uac70\uc6b0\ub2c8 \ubab8\uc740 \ud798\ub4e4\uc5b4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \ucc45\uc774 \uc548 \ubcf4\uc778\ub2e4... \uc774\ubbf8 \ucc45 \ucc3e\uae30\uc5d0 10\ubd84 \uc774\uc0c1 \ub9e4\ubab0\ube44\uc6a9\uc774 \ubc1c\uc0dd. \uc774\uc81c \ud328\ub529\uae4c\uc9c0 \uc628\uc804\ud788 \ubc97\uace0 \uc870\uae08\uc740 \uc2dc\uc6d0\ud558\uac8c \ub458\ub7ec\ubcf8\ub2e4. \uadf8\ub7f0\ub370 \uc774\ubbf8 \ubab8\uc740 \ud53c\ub85c\ub97c \uc778\uc9c0\ud588\ub2e4.\\n\\n\uadf8\ub807\uac8c.... \uae09 \ud53c\ub85c\uc5d0 \ucc0c\ub4e4\uc5b4\ubc84\ub9ac\uace0 `<\ub5a0\ub09c \uac83\uc740 \ub3cc\uc544\uc624\uc9c0 \uc54a\ub294\ub2e4 - \uc904\ub9ac\uc5b8 \ubc18\uc2a4>`\ub97c \uace8\ub77c \uc9d1\uc73c\ub85c \ud130\ub35c\ud130\ub35c \uc654\ub2e4.\\n\\n<figure>\\n\\n![IMG_2334.jpeg](./departures.jpg)\\n\\n<figcaption>\uaca8\uc6b0 \uace0\ub978 \ucc45. &lt;\ub5a0\ub098\uac04 \uac83\uc740 \ub3cc\uc544\uc624\uc9c0 \uc54a\ub294\ub2e4 - \uc904\ub9ac\uc5b8 \ubc18\uc2a4&gt;</figcaption>\\n</figure>\\n\\n\ub0b4\uac00 \ucc45\uc744 \uace0\ub97c \ub550 \uc81c\ubaa9\uacfc \uc791\uac00\uc758 \uc774\ub984\uc744 \ubcf4\uace0 \uc9c1\uad00\uc801\uc73c\ub85c \ub04c\ub9ac\ub294 \ubb34\uc5b8\uac00\uac00 \uc788\uc5b4\uc57c \ub41c\ub2e4. \ub0b4\uac8c \uc788\uc5b4 \uba4b\uc788\uac8c \ub290\uaef4\uc838\uc57c \ub41c\ub2e4. \uc774 \ucc45\uc740 \uc81c\ubaa9\uc774 \ub108\ubb34 \ub0b4 \uc2a4\ud0c0\uc77c\uc774\ub77c \uc608\uc804\ubd80\ud130 \ucc1c\ud574\ub450\uae34 \ud588\uc5c8\ub2e4. \uc65c\uc774\ub9ac \ub2a6\uac8c \ub208\uc5d0 \ubcf4\uc600\uc744\uae4c\ub098...?\\n\\n\uc0ac\uc2e4 \uc774 \uae00\uc744 \uc801\uae30 \uc2dc\uc791\ud560 \ub54c\uae4c\uc9c0\ub9cc \ud574\ub3c4 \ub418\uac8c \'**\ucc45 \ud5db\uc0ac\ub7ec \uac14\ub2e4**\'\ub294 \uc0dd\uac01\uae4c\uc9c0 \ub4e4\uc5c8\ub294\ub370, \ub9c9\uc0c1 \ub450 \uac1c\uc758 \ucc45\uc744 \ubcf4\ub2c8 \ub9c8\uc74c\uc774 \uc88b\ub2e4. \uc5ed\uc2dc \uac10\uc815\uc740 \ub9c8\ubb34\ub9ac\ud558\uae30 \ub098\ub984..?\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/264)"},{"id":"on-marriage-and-single-life","metadata":{"permalink":"/on-marriage-and-single-life","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-23-on-marriage-and-single-life/index.md","source":"@site/blog/2026-10-23-on-marriage-and-single-life/index.md","title":"\ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub41c\ub2e4.","description":"\ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub41c\ub2e4.","date":"2026-10-22T16:43:06.876Z","tags":[{"inline":false,"label":"Life","permalink":"/tags/life","description":"rudevico\uc758 \uc804\ubc18\uc801\uc778 \uc77c\uc0c1 \uc774\uc57c\uae30"}],"readingTime":1.07,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"on-marriage-and-single-life","title":"\ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub41c\ub2e4.","date":"2026-10-22T16:43:06.876Z","authors":"hyoyoonnam","tags":["life"],"image":"./cover.png"},"unlisted":false,"prevItem":{"title":"\ucc45\uc744 \ub450 \uad8c \uc0c0\uc9c0\ub9cc, \uc774\uc804\ubcf4\ub2e4\ub294 \ubb34\ub364\ub364\ud55c \ud558\ub8e8","permalink":"/buying-two-books"},"nextItem":{"title":"\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \uaca8\uc6b8\uafc8 | \ud53c\uce20\uc81c\ub7f4\ub4dc","permalink":"/fading-indifference-in-winter-dreams"}},"content":"![\ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub41c\ub2e4.](./cover.png)\\n\\n> *\ucc98\uc790\uc2dd\uc744 \uac00\uc9c4 \uc790\ub294 \uc6b4\uba85\uc758 \uc190\uc5d0 \uc778\uc9c8\ub85c \ub118\uc5b4\uac04 \uc790\ub2e4. \uc88b\uc740 \uc77c\uc774\ub4e0 \ub098\uc05c \uc77c\uc774\ub4e0 \ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub418\uae30 \ub54c\ubb38\uc774\ub2e4.* - [&lt;\uacb0\ud63c\uacfc \ub3c5\uc2e0 \uc0dd\ud65c | \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8 | \ubb38\uc608\ucd9c\ud310\uc0ac&gt;](https://www.yes24.com/product/goods/147564050)\\n\\n\uc0c1\ub2f9\ud788 \ub3c4\ubc1c\uc801\uc778 \ubc1c\uc5b8\uc774\ub2e4. \uc544\uc774\uac00 \uc5c6\ub2e4\uba74 \uadf8\ub9cc\ud07c \uc77c\uc5d0 \ub354 \uc9d1\uc911\ud560\uae4c? \uc544\uc774\uc5d0 \ub300\ud55c \ucc45\uc784\uac10\uc744 \uc6d0\ub3d9\ub825\uc73c\ub85c \uc77c\uc5d0 \ub354 \uc9d1\uc911\ud558\uac8c \ub418\uc9c0\ub294 \uc54a\uc744\uae4c?\\n\\n\x3c!-- truncate --\x3e\\n\\n\ub300\ud559\uad50 \uc2dc\ud5d8\uae30\uac04, \'\ubc24\uc744 \uc0c8\uc790\'\ub294 \ub2e4\uc9d0\uc744 \ud558\uace0 \ub3c4\uc11c\uad00\uc5d0 \ub4e4\uc5b4\uc120\ub2e4. \uc800\ub141 10\uc2dc\uc5d0 \ub4e4\uc5b4\uac00\ub2c8, \ub2e4\uc74c \ub0a0 \uc624\ud6c4 2\uc2dc\uc5d0 \uc788\ub294 \ucef4\ud4e8\ud130 \uc2dc\ubbac\ub808\uc774\uc158 \uc218\uc5c5\uae4c\uc9c0\ub294 \ubb34\ub824 16\uc2dc\uac04\uc774 \ub0a8\ub294\ub2e4. 3\uc2dc\uac04\ub9c8\ub2e4 \ud55c \uac1c \ucc55\ud130\uc529\ub9cc \ub05d\ub0b4\uba74 \ucda9\ubd84\ud558\ub2e4.\\n\\n\u3030\ufe0f\u3030\ufe0f\\n\\n\ubc24\uc744 \uc9c0\uc0c8\uc6c0\uc73c\ub85c\uc368 \uc0dd\uaca8\ub09c 16\uc2dc\uac04\uc740 \uc628\uc804\ud788 \ub0b4 \uc2dc\uac04\uc77c\uae4c?\\n\\n\u3030\ufe0f\u3030\ufe0f\\n\\n\uc544\uc774\uac00 \uc5c6\uc5b4\uc11c \uc0dd\uae30\ub294 \uc2dc\uac04\uc740 \uc628\uc804\ud788 \ub2e4 \uc9d1\uc911\ud560 \uc218 \uc788\ub294 \uc2dc\uac04\uc77c\uae4c..? \uadf8\ub807\uc9c0 \uc54a\ub2e4. \uc704\uc5d0\uc11c \ub9d0\ud588\ub4ef \uc544\uc774\ub85c \uc778\ud574 \uc624\ud788\ub824 \ub354 \uae4a\uc740 \ubab0\uc785\uacfc \uc9d1\uc911\uc744 \ud55c \ub355\ubd84\uc5d0 \uc77c\uc744 \uc798 \ud574\ub0bc \uc218\ub3c4 \uc788\ub2e4. \ubb3c\ub860 \uc2e0\uc0dd\uc544 \ub54c\uc5ec\uc11c \uc544\uc774\uac00 \uc2dc\ub3c4\ub54c\ub3c4 \uc5c6\uc774 \uae68\uace0, \uc790\uace0, \uc6b8\uace0, \ubcf4\ucc44\uace0 \ud558\ub290\ub77c \uc218\uba74 \ud328\ud134\uc774 \uc644\uc804\ud788 \ub9dd\uac00\uc9c4\ub2e4\uba74... \ud798\ub4e4\uaca0\uc9c0\ub9cc\uc11c\ub3c4.\\n\\n\uc544\uc774\ub97c \uc88b\uc544\ud558\ub294 \ud3b8\uc5d0 \uc18d\ud558\uba74\uc11c\ub3c4 \\"\ucc98\uc790\uc2dd\uc774 \ud544\uc694\ud558\ub2e4\\"\ub77c\ub294 \uc0dd\uac01\uc744 \uc758\uc2dd\uc801\uc73c\ub85c \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc544\uc774\ub77c\ub294 \uac83\ub3c4 \ud758\ub7ec\uac00\ub294 \ub300\ub85c \uc9c0\ub0b4\ub2e4 \ubcf4\uba74, \uc790\uc5f0\uc2a4\ub808 \uc778\uc0dd\uc758 \ub3d9\ubc18\uc790\uac00 \ud55c \uba85 \ub298\uc5b4\ub098\ub294 \uac70 \uc544\ub2d0\uae4c?\\n\\n\uc544\uc774\uc640 \ud568\uaed8 \ud558\ub354\ub77c\ub3c4 \ubd80\ubaa8\uc774\uae30\ubcf4\ub2e4\ub294 \ud558\ub098\uc758 \ub3d9\ub4f1\ud55c \uc778\uaca9\uccb4, \uac19\uc73c\uba74\uc11c\ub3c4 \uc644\uc804\ud788 \ub2e4\ub978 \uc0b6\uc744 \uc0b4\uace0 \uc788\ub294 \ub610 \ub2e4\ub978 \uc778\uac04\uc73c\ub85c \ud568\uaed8 \ud558\uace0 \uc2f6\ub2e4. \ud754\ud788 \ud45c\ud604\ub418\ub294 \'\uce5c\uad6c\uac19\uc740 \ubd80\ubaa8\'\uc640\ub294 \ub610 \ub2e4\ub978 \ub290\ub08c..?\\n\\n\u3030\ufe0f\u3030\ufe0f\\n\\n\ubd80\ubaa8 | \uc790\uc2dd | \uc5f0\uc778 | \uce5c\uad6c | \uc2a4\uc2b9\\n\\n.\ub2e4\ub974\uba74\uc11c\ub3c4 \ub2e4\ub97c \ubc14 \uc5c6\ub2e4.\\n\\n\u3030\ufe0f\u3030\ufe0f\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/249)"},{"id":"fading-indifference-in-winter-dreams","metadata":{"permalink":"/fading-indifference-in-winter-dreams","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-21-fading-indifference-in-winter-dreams/index.md","source":"@site/blog/2026-10-21-fading-indifference-in-winter-dreams/index.md","title":"\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \uaca8\uc6b8\uafc8 | \ud53c\uce20\uc81c\ub7f4\ub4dc","description":"\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \uaca8\uc6b8\uafc8 | \ud53c\uce20\uc81c\ub7f4\ub4dc","date":"2026-10-21T12:57:32.019Z","tags":[{"inline":false,"label":"Life","permalink":"/tags/life","description":"rudevico\uc758 \uc804\ubc18\uc801\uc778 \uc77c\uc0c1 \uc774\uc57c\uae30"}],"readingTime":0.84,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"fading-indifference-in-winter-dreams","title":"\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \uaca8\uc6b8\uafc8 | \ud53c\uce20\uc81c\ub7f4\ub4dc","date":"2026-10-21T12:57:32.019Z","authors":"hyoyoonnam","tags":["life"],"image":"./cover.png"},"unlisted":false,"prevItem":{"title":"\ud070\uc77c\uc744 \ud558\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c \ucc98\uc790\uc2dd\uc740 \ud070 \ubc29\ud574\uac00 \ub41c\ub2e4.","permalink":"/on-marriage-and-single-life"},"nextItem":{"title":"\ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud55c\ub2e4? - <\ubd80\ubaa8\uc640 \uc790\uc2dd>\uc744 \uc77d\uc73c\uba70","permalink":"/on-parents-and-children"}},"content":"![\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \uaca8\uc6b8\uafc8 | \ud53c\uce20\uc81c\ub7f4\ub4dc](./cover.png)\\n\\n> *\uadf8\uac00 \ubcf4\uae30\uc5d4, \uadf8\ub140\uac00 \uc790\uc2e0\uc744 \ub098\ubb34\ub77c\uc9c0 \uc54a\uc740 \uc774\uc720\ub294 \uadf8\ub140\uac00 \ub4dc\ub7ec\ub0b8 \uc644\ubcbd\ud55c \ubb34\uad00\uc2ec, \uadf8\ub9ac\uace0 \uc2e4\uc81c\ub85c\ub3c4 \uc9c4\uc2ec\ucc98\ub7fc \ubcf4\uc600\ub358 \uadf8 \ubb34\uad00\uc2ec\uc774 \uc870\uae08\uc774\ub77c\ub3c4 \uc605\uc5b4\uc9c0\ub294 \uac78 \uc6d0\uce58 \uc54a\uc558\uae30 \ub54c\ubb38\uc774\ub2e4.* - &lt;\uaca8\uc6b8\uafc8 - \uc2a4\ucf67 F. \ud53c\uce20\uc81c\ub7f4\ub4dc&gt;\\n\\n\x3c!-- truncate --\x3e\\n\\n\ub098\ub294 \ucc45\uc744 \uc74c\ubbf8\ud558\uba70 \uc77d\uc9c0 \uc54a\ub294\ub2e4. \uadf8 \ucc45\uc744 \uc628\uc804\ud788 \uc774\ud574\ud558\ub824 \ud558\uc9c0 \uc54a\uace0 \ub290\ub08c\ub300\ub85c \uc2a5\uc2a5... \uc77d\ub294 \ud3b8\uc778\ub370, \uadf8\ub7f0\ub370 \ub0b4 \uc77d\uc5b4\uac10\uc774 \uba48\uce6b\ud55c \uc21c\uac04\uc774 \uc788\ub2e4.\\n\\n\u3030\ufe0f\u3030\ufe0f\\n\\n**\ubb34\uad00\uc2ec\uc774 \uc605\uc5b4\uc9c4\ub2e4**\ub294 \ud45c\ud604\uacfc \ub9cc\ub09c \ub54c\uc778\ub370, \uc778\uc0c1\uae4a\uc5b4\uc11c [\uac10\uc0c1\uc744 \ub0a8\uaca8\ub193\uae30\uae4c\uc9c0 \ud588\ub2e4](https://chaekchaek.com/download).\\n\\n<figure>\\n\\n![\u1109\u1173\u110f\u1173\u1105\u1175\u11ab\u1109\u1163\u11ba 2026-10-21 20.50.49.png](./chaekchaek-note.png)\\n\\n<figcaption>\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec\uc5d0 \ub0b4\uac00 \ub0a8\uae34 \uac10\uc0c1 - on the chaekchaek</figcaption>\\n</figure>\\n\\n\ubb34\uad00\uc2ec\ud558\uac8c, \ub610\ub294 \uad00\uc2ec\uc774 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc870\ucc28 \uc778\uc9c0\ud558\uc9c0 \uc54a\ub294 \uc218\uc900\uc73c\ub85c \ub300\ud558\ub358 \ub300\uc0c1\uc774 \uc788\ub2e4\uace0 \ud558\uc790. \uac00\ub839 \uc74c\uc2dd\uc810\uc5d0\uc11c \uc5d0\uc5b4\ucee8 \ubc14\ub78c\uc5d0 \ud769\ub0a0\ub9ac\ub294 \ud734\uc9c0\ub77c\ub358\uac00, \ucc45\uc0c1 \uc606 \ubc14\ub2e5\uc5d0 \uc788\ub294 \ud68c\uc0c9 \uba3c\uc9c0 \ubb49\uce58\ub77c\ub358\uac00, \uadf8\ub7f0 \uac83\ub4e4 \ub9d0\uc774\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uadf8 \ubb34\uad00\uc2ec\uc774 \uc605\uc5b4\uc9c0\ub294 \uc21c\uac04\uc774 \uc788\ub2e4. \ud734\uc9c0\uc758 \ud769\ub0a0\ub9bc\uc774 \uac11\uc790\uae30 \uac70\uc2ac\ub9b4 \uc218\ub3c4, \ub204\uad70\uac00 \uac78\uc5b4\uac00\uba70 \uc0dd\uae34 \ubc14\ub78c\uc5d0 \ud718\uc789-\ud558\uace0 \uc6c0\uc9c1\uc774\ub294 \uba3c\uc9c0\uc5d0 \uc2dc\uc120\uc744 \ube7c\uc557\uae38 \uc218\ub3c4...\\n\\n\u3030\ufe0f\u3030\ufe0f\\n\\n\uc0ac\ub78c\uc5d0\uac8c\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\ub85c, \uad00\uc2ec\uc774 \uc0dd\uae30\ub294 \uac8c \uc544\ub2c8\ub77c \ubb34\uad00\uc2ec\uc774 \uc605\uc5b4\uc9c0\ub294 \uac74 \uc544\ub2d0\uae4c.\\n\\n \u3030\ufe0f\u3030\ufe0f\\n\\n<figure>\\n\\n![IMG_2315.jpeg](./winter-dreams.jpg)\\n\\n<figcaption>.\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \ub9c8\uce68.</figcaption>\\n</figure>\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/231)"},{"id":"on-parents-and-children","metadata":{"permalink":"/on-parents-and-children","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-19-on-parents-and-children/index.md","source":"@site/blog/2026-10-19-on-parents-and-children/index.md","title":"\ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud55c\ub2e4? - <\ubd80\ubaa8\uc640 \uc790\uc2dd>\uc744 \uc77d\uc73c\uba70","description":"\ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud55c\ub2e4? - &lt;\ubd80\ubaa8\uc640 \uc790\uc2dd&gt;\uc744 \uc77d\uc73c\uba70","date":"2026-10-19T14:59:21.960Z","tags":[{"inline":false,"label":"Life","permalink":"/tags/life","description":"rudevico\uc758 \uc804\ubc18\uc801\uc778 \uc77c\uc0c1 \uc774\uc57c\uae30"}],"readingTime":1.15,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"on-parents-and-children","title":"\ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud55c\ub2e4? - <\ubd80\ubaa8\uc640 \uc790\uc2dd>\uc744 \uc77d\uc73c\uba70","date":"2026-10-19T14:59:21.960Z","authors":"hyoyoonnam","tags":["life"],"image":"./cover.png"},"unlisted":false,"prevItem":{"title":"\uc605\uc5b4\uc9c0\ub294 \ubb34\uad00\uc2ec | \uaca8\uc6b8\uafc8 | \ud53c\uce20\uc81c\ub7f4\ub4dc","permalink":"/fading-indifference-in-winter-dreams"},"nextItem":{"title":"Be water, my friend.","permalink":"/be-water-my-friend"}},"content":"![\ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud55c\ub2e4? - &lt;\ubd80\ubaa8\uc640 \uc790\uc2dd&gt;\uc744 \uc77d\uc73c\uba70](./cover.png)\\n\\n\uc624\ub298 \ud558\ub8e8\uc758 \ub9c8\ubb34\ub9ac\ub294 \uc5b4\ubb35 \ud2f0\ubc31\uacfc \ud568\uaed8 \ud55c\ub2e4. \uc0ac\uc2e4 \uc6b0\ud14c\ucf54 \uc0ac\ub78c\uc774\ub77c\uba74 \uc775\uc219\ud55c \uc0ac\uc2e4\uc774\uaca0\uc9c0\ub9cc, \ucf54\ub07c\ub9ac\ub294 \uc5b4\ubb35\uc744, \ud2b9\ud788 \uc5b4\ubb35\ud0d5\uc744 \uc88b\uc544\ud558\uc9c0 \uc54a\ub294\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uc624\ub298\uc740 \uc5b4\ubb35 \ud2f0\ubc31\uacfc \ud568\uaed8 \ub9c8\ubb34\ub9ac\ud558\uace0\ud508, \uadf8\ub7f0 \ub0a0\uc774\ub2e4. \ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud558\ub294 \uac78\uae4c?\\n\\n\x3c!-- truncate --\x3e\\n\\n***\\n\\n> \uae30\uc5b5\uc5d0 \ub0a8\uace0, \uacf5\uc801\uc744 \uc313\uace0, \uace0\uadc0\ud55c \uc77c\uc744 \ud589\ud558\ub294 \uac83\uc740 \uc778\uac04\uc5d0\uac8c \uace0\uc720\ud55c \uac83\uc774\ub2e4. \uadf8\ub9ac\ud558\uc5ec \uac00\uc7a5 \uace0\uadc0\ud55c \uc5c5\uc801\uacfc \uae30\ud2c0\uc740 \uc790\uc2dd\uc744 \uac00\uc9c0\uc9c0 \uc54a\uc740 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\uc11c \ube44\ub86f\ub41c\ub2e4. \uc721\uccb4\uc758 \ud615\uc0c1\uc744 \ub0a8\uae30\uc9c0 \ubabb\ud558\ubbc0\ub85c \uc815\uc2e0\uc758 \ud615\uc0c1\uc744 \ud45c\ud604\ud558\ub824\uace0 \ub178\ub825\ud558\uae30 \ub54c\ubb38\uc774\ub2e4.\\n\\n\'\ub300\ub97c \uc787\ub294\ub2e4\'\ub294 \ub3d9\ubb3c \ubcf8\ub2a5\uc5d0\uc11c \ucd9c\ubc1c\ud558\uc5ec \uc790\uc190(\uc721\uccb4\uc758 \ud615\uc0c1)\uc73c\ub85c \ubcf8\ub2a5\uc744 \ucda9\uc871\ud558\uc9c0 \ubabb\ud55c\ub2e4\uba74 \uc815\uc2e0\uc758 \ud615\uc0c1\uc744 \ub0a8\uae30\ub824\uace0 \ub178\ub825\ud55c\ub2e4\ub294 \uc811\uadfc\uc774 \uc7ac\ubc0c\uc5c8\ub2e4.\\n\\n\uc790\uc2dd\uc744 \ub0b3\ub294\ub2e4\ub294 \uac74 \uadf8 \uc790\uccb4\ub85c \uace0\uadc0\ud558\uace0, \uc0b6\uc758 \uc774\uc720\ub098 \ubaa9\ud45c\uac00 \ubc14\ub00c\ub294 \uc0ac\uac74\uc778\ub370, \uc774\uc804\uacfc \uc0b6\uc758 \uc2dc\uac04 \ube44\uc728\uc774 \ubc14\ub00c\ub294 \uac74 \uc0ac\uc2e4\uc774\uc9c0 \uc54a\ub294\uac00? \uc721\uccb4\uc801\uc73c\ub85c\ub098 \uc9c1\uc7a5\uc5d0\uc11c\ub098 \ucee4\ub9ac\uc5b4\uac00 \ud558\uc774\ub97c \ucc0d\uc5b4\uac08 \ub54c \uc988\uc74c\uc5d0 \uacb0\ud63c\ud558\uac8c \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc740\ub370 \uacb0\ud63c\uc744 \uc81c\uccd0\ub450\uace0 \uc77c/\uc5f0\uad6c\uc5d0 \uc9d1\uc911\ud55c\ub2e4\uba74, \uc5ec\uae30\uc11c \ub9d0\ud558\ub294 \uc815\uc2e0\uc758 \ud615\uc0c1\uc774 \ub354 \ub0a8\uaca8\uc9c0\uae34 \ud558\uaca0\ub2e4.\\n\\n\uadf8\ub7f0\ub370 (\uc774 \uacbd\uc6b0\uc5d0\ub294 \uacb0\ud63c\uc758) \ub54c\ub97c \uae30\ub2e4\ub9ac\ub2e4\uac00\ub294 \uc810\uc810 \'\ucd5c\uc0c1\uc758 \ub54c\'\ub97c \ucc3e\uae30 \uc704\ud55c \uc695\uc2ec\uc774 \ucee4\uc9c0\uae30 \ub54c\ubb38\uc5d0 \uc900\ube44\ub418\uc9c0 \uc54a\uc558\ub2e4\uace0 \ub290\uaef4\uc9c0\ub294 \ub54c\uc5d0 \uacb0\ud63c\ud558\ub294 \uac83\ub3c4 \uc88b\uc9c0 \uc54a\uc744\uae4c..\\n\\n> \ubd80\ubaa8\ub294 \uc790\ub140\ub4e4\uc774 \ucde8\ud574\uc57c \ud560 \uc9c1\uc5c5\uacfc \uc9c4\ub85c\ub97c \uc77c\ucc0d \uacb0\uc815\ud574\uc8fc\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4. \ub098\uc774\uac00 \uc5b4\ub9b4\uc218\ub85d \uc720\uc5f0\uc131\ub3c4 \ud06c\uae30 \ub54c\ubb38\uc774\ub2e4. \uc790\uc2dd\uc774 \ud558\uace0 \uc2f6\uc740 \ub300\ub85c \ud558\ub3c4\ub85d \ub0b4\ubc84\ub824\ub450\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud558\uc5ec \uc790\ub140\ub4e4\uc758 \ucde8\ud5a5\uc744 \uc9c0\ub098\uce58\uac8c \uc874\uc911\ud558\ub294 \uac83\uc740 \uc88b\uc9c0 \uc54a\ub2e4. \uc790\ub140\uc758 \ucde8\ud5a5\uc774\ub098 \uc18c\uc9c8\uc774 \ud2b9\ucd9c\ud55c \uac83\uc774\ub77c\uba74, \ubb3c\ub860 \uadf8\ub4e4\uc758 \ub73b\uc744 \uaebe\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\ub2e4.\\n\\n\ubd80\ubaa8\uac00 \uc790\ub140\uc758 \uc9c1\uc5c5\uacfc \uc9c4\ub85c\ub97c \uc77c\ucc0d \uacb0\uc815\ud574\uc918\uc57c \ube60\ub974\uac8c \uc811\ud574\ubcf4\uace0, \uc548 \ub9de\uc558\uc744 \ub54c \ub2e4\ub978 \uac78 \uc54c\uc544\ubcf4\uae30\uc5d0 \ub9ac\uc2a4\ud06c\uac00 \uc801\ub2e4\ub294 \uac74\uac00?(\uc720\uc5f0\uc131\uc774 \ud06c\ub2e4\uace0 \ud558\uae38\ub798..) \uc774\ubc88 \ub0b4\uc6a9\uc740 \uc5b4\ub835\ub2e4.\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/217)"},{"id":"be-water-my-friend","metadata":{"permalink":"/be-water-my-friend","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-18-be-water-my-friend/index.md","source":"@site/blog/2026-10-18-be-water-my-friend/index.md","title":"Be water, my friend.","description":"Be water, my friend.","date":"2026-10-18T14:37:36.357Z","tags":[{"inline":false,"label":"Life","permalink":"/tags/life","description":"rudevico\uc758 \uc804\ubc18\uc801\uc778 \uc77c\uc0c1 \uc774\uc57c\uae30"}],"readingTime":2.29,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"be-water-my-friend","title":"Be water, my friend.","date":"2026-10-18T14:37:36.357Z","authors":"hyoyoonnam","tags":["life"],"image":"./cover.jpg"},"unlisted":false,"prevItem":{"title":"\ucf54\ub07c\ub9ac\ub294 \uc0ac\uc2e4 \uc5b4\ubb35\uc744 \uc88b\uc544\ud55c\ub2e4? - <\ubd80\ubaa8\uc640 \uc790\uc2dd>\uc744 \uc77d\uc73c\uba70","permalink":"/on-parents-and-children"},"nextItem":{"title":"\ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4 - \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8","permalink":"/francis-bacon-on-revenge"}},"content":"![Be water, my friend.](./cover.jpg)\\n\\n## \ubb3c\uc774 \ub418\uae30\\n\\n<figure>\\n\\n![image.png](./rain-warning-ytn.png)\\n\\n<figcaption>\uc0ac\uc9c4 1. \uc11c\uc6b8/\uacbd\uae30 \ud638\uc6b0\uc8fc\uc758\ubcf4 \ub274\uc2a4 \uae30\uc0ac(1) - YTN</figcaption>\\n</figure>\\n\\n<figure>\\n\\n![image.png](./rain-warning-kbs.png)\\n\\n<figcaption>\uc0ac\uc9c4 2. \uc11c\uc6b8/\uacbd\uae30 \ud638\uc6b0\uc8fc\uc758\ubcf4 \ub274\uc2a4 \uae30\uc0ac(2) - KBS</figcaption>\\n</figure>\\n\\n*\uac00\uc744\ube44\uac00, \uadf8\uac83\ub3c4 \uaf64\ub098 \uc138\ucc2c \uac00\uc744\ube44\uac00 \ub0b4\ub9ac\ub294 26\ub144\uc758 \uc77c\uc694\uc77c\uc774\ub2e4.* \uadf8\ub798\ub3c4 \uc624\ud6c4 6\uc2dc \uc988\uc74c\uc5d0\ub294 \ube44\uac00 \uadf8\uccd0\uac00\uae38\ub798 \uc8fc\uc12c\uc8fc\uc12c \ub2ec\ub9b4 \uc900\ube44\ub97c \ud588\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n\ube44\ub85c \uc778\ud574\uc11c \ub2ec\ub77c\uc9c4 \ud48d\uacbd\uc740 \ud0c4\ucc9c\uc758 \uc218\uc704\uc600\ub294\ub370, \ud558\ucc9c\uc758 \uc591 \uc606\uc744 \uc787\ub294 \ub3cc\ub2e4\ub9ac\uac00 \uc7a0\uae30\uae30 \uc9c1\uc804\uae4c\uc9c0 \ubb3c\uc774 \ucc28\uc62c\ub790\ub2e4.\\n\\n<figure>\\n\\n![\u1110\u1161\u11ab\u110e\u1165\u11ab\u1109\u116e\u110b\u1171.jpeg](./stepping-stones.jpg)\\n\\n<figcaption>\uc0ac\uc9c4 3. \ubb3c\uc5d0 \uc7a0\uae30\uae30 \uc9c1\uc804\uc778 \ub3cc\ub2e4\ub9ac</figcaption>\\n</figure>\\n\\n\uc774\ub300\ub85c \uacc4\uc18d\ud574\uc11c \ubb3c\uc744 \ubc1b\uc544\ub0b4\uae30\uc5d0\ub294 \ubb34\ub9ac\ub77c\uace0 \uc0dd\uac01\ud588\ub294\uc9c0 \ud558\ucc9c\uc740 \uc720\uc18d\uc744 \ube60\ub974\uac8c \ub9cc\ub4e4\uc5b4 \uc800 \uba40\ub9ac \uc5b4\ub518\uac00\ub85c \ubb3c\uc744 \ud758\ub824\ubcf4\ub0b4\uace0 \uc788\uc5c8\ub2e4.\\n\\n<figure>\\n\\n![image.png](./river-current.png)\\n\\n<figcaption>\uc0ac\uc9c4 4. \uc5c4\uccad\ub09c \uc591\uacfc \uc18d\ub3c4\ub85c \ud558\ucc9c\uc744 \ud750\ub974\ub294 \ubb3c</figcaption>\\n</figure>\\n\\n\'\uc790\uc5f0\uc740 \ud544\uc694\uc5d0 \ub530\ub77c \uc794\uc794\ud788 \ud750\ub974\uae30\ub3c4, \uc18d\ub3c4\ub97c \ub0b4\uae30\ub3c4 \ud558\ub294\uad6c\ub098\' \uac10\ud0c4\ud558\ub294 \uc640\uc911\uc5d0 \uc5b4\ub834\ud48b\uc774 \uae30\uc5b5\uc5d0 \uc788\ub358 \'\uc790\uc5f0\uc744 \ubaa8\ubc29\ud558\uc5ec \ub9cc\ub4e4\uc5b4\uc9c4 \uae30\uc220\uc774 \ub9ce\ub2e4\'\ub294 \ub9d0\uc774 \uc0dd\uac01\ub0ac\ub2e4.\\n\\n> \uacb0\uad6d \uc778\uc0dd\uc5d0\uc11c \uc5ec\uc720\ub97c \uac00\uc9c0\uace0 \uc0b6\uc774 \uc911\uc694\ud558\uc9c0\ub9cc, \ubc14\ube60\uc57c \ud560 \ub54c\ub294 \ub0b4 \uc778\uc0dd\uc758 \uc720\uc18d\ub3c4 \uc7a0\uc2dc \ube60\ub974\uac8c \ud560 \ud544\uc694\uac00 \uc788\uaca0\uad6c\ub098. \ubb3c\ucc98\ub7fc.\\n\\n\uadf8\ub798\uc11c \ub098\ub294 \ubb3c\uc774 \ub418\uae30\ub85c \ud588\uace0, \uc6b0\ud14c\ucf54 \ud65c\ub3d9 \uae30\uac04\uc774 \uc5bc\ub9c8 \ub0a8\uc9c0 \uc54a\uc740 \uc9c0\uae08\uc5d0\ub294 \uc0c1\ub2f9\ud788 \ube60\ub978 \uc720\uc18d\uc744 \ub9cc\ub4e4\uc5b4 \ub0bc \ud544\uc694\uac00 \uc788\uaca0\ub2e4.\\n\\n<figure>\\n\\n![03_\u1109\u1162\u11bc\u110e\u1166\u1106\u1169\u1107\u1161\u11bc.png](./biomimetics.png)\\n\\n<figcaption>\uc0ac\uc9c4 5. \uc0dd\uccb4\ubaa8\ubc29\ud559(Biomimetics) - wikipedia</figcaption>\\n</figure>\\n\\n<figure>\\n\\n![IMG_2278.jpeg](./run-record.jpg)\\n\\n<figcaption>\uc0ac\uc9c4 6. \uc624\ub298\uc758 \ub2ec\ub9ac\uae30\ub85d</figcaption>\\n</figure>\\n\\n### \ud0c4\ucc9c \uce5c\uad6c\ub4e4\\n\\n\uc9c0\ub09c \ubc88\uc5d0 \ub2ec\ub9b4 \ub54c \ub108\uad6c\ub9ac\ub791 \uc0c8\ub97c \ubd24\ub294\ub370 \uc624\ub298 \uc798 \ubc84\ud168\ub0c8\uc744\uae4c..?\\n\\n<figure>\\n\\n![IMG_2243.jpeg](./raccoon-a.jpg)\\n\\n<figcaption>\uc0ac\uc9c4 7. \ub108\uad6c\ub9acA</figcaption>\\n</figure>\\n\\n<figure>\\n\\n![IMG_2246.jpeg](./raccoon-b.jpg)\\n\\n<figcaption>\uc0ac\uc9c4 8. \ub108\uad6c\ub9acB</figcaption>\\n</figure>\\n\\n<figure>\\n\\n![IMG_2241.jpeg](./bird.jpg)\\n\\n<figcaption>\uc0ac\uc9c4 9. (\uc790\uace0 \uc788\ub294?) \uc0c8</figcaption>\\n</figure>\\n\\n<figure>\\n\\n![IMG_2240.jpeg](./bird-close-up.jpg)\\n\\n<figcaption>\uc0ac\uc9c4 10. \uc0c8 \ud655\ub300</figcaption>\\n</figure>\\n\\n## \ubca0\uc774\ucee8 \uc218\ud544\uc9d1 \uc774\uc57c\uae30 - \uc5ed\uacbd | \ubb38\uc608\ucd9c\ud310\uc0ac\\n\\n\uc774\ubc88 \uc218\ud544\uc5d0\uc11c\ub294 \uc5ed\uacbd\uc744 \uc990\uae30\ub294 \ubc95\uc744 \uc81c\uc2dc\ud55c\ub2e4. \ube44\uc2b7\ud55c \ubb38\uc7a5\uc774 \ub9ce\uc544 \uc774\ub97c \uc815\ub9ac\ud558\ub294 \uac83\uc73c\ub85c \ub9c8\ubb34\ub9ac\ud55c\ub2e4.\\n\\n> \ubc88\uc131\uc5d0 \uc18d\ud558\ub294 \uc88b\uc740 \uac83\uc740 \ud0d0\ub0bc \ub9cc\ud55c \uac83\uc774\uc9c0\ub9cc, \uc5ed\uacbd\uc5d0 \uc18d\ud558\ub294 \uc88b\uc740 \uac83\uc740 \ucc2c\uc591\ud560 \ub9cc\ud55c \uac83 - \uc138\ub124\uce74\\n\\n\uc694\uc998 <strong>[&lt;\uc138\ub124\uce74, \uc624\ub298\uc744 \ube7c\uc557\uae30\uace0 \uc788\ub294 \ub2f9\uc2e0\uc5d0\uac8c&gt;](https://www.yes24.com/product/goods/192474512)</strong>\uac00 \uc720\ud589\ud558\ub358\ub370 \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8\ub3c4 \uc5b8\uae09\ud558\uae38\ub798 \uc2e0\uae30\ud588\ub2e4.\\n\\n> \ubd84\uba85\ud788 \uae30\uc801\uc774 \uc790\uc5f0 \uc704\uc5d0 \uad70\ub9bc\ud558\ub294 \uac83\uc774\ub77c\uba74, \uae30\uc801\uc740 \ub300\uccb4\ub85c \uc5ed\uacbd \uc18d\uc5d0\uc11c \ub098\ud0c0\ub09c\ub2e4.\\n\\n> \ubc88\uc131\uc740 \ubbf8\ub355\uc758 \uc808\uc81c\uc694, \uc5ed\uacbd\uc758 \ubbf8\ub355\uc740 \uc778\ub0b4\ub2e4. \uc778\ub0b4\uac00 \ub3c4\ub355\uc801\uc73c\ub85c \ud6e8\uc52c \uc601\uc6c5\uc801\uc778 \ubbf8\ub355\uc774\ub2e4.\\n\\n> \ubc88\uc131\uc740 \uad6c\uc57d\uc5d0\uc11c \ub9d0\ud558\ub294 \ucd95\ubcf5\uc774\uc694, \uc5ed\uacbd\uc740 \uc2e0\uc57d\uc5d0\uc11c \ub9d0\ud558\ub294 \ucd95\ubcf5\uc774\ub2e4. \uc774 \uc5ed\uacbd\uc774 \ub354 \ud070 \uc740\ud61c\ub97c \uc57d\uc18d\ud574\uc8fc\uace0, \uc2e0\uc758 \uac00\ud638\ub97c \ub354 \uc120\uba85\ud558\uac8c \uacc4\uc2dc\ud574\uc900\ub2e4.\\n\\n> \uc5ed\uacbd \uc18d\uc774\ub77c\uace0 \uc704\uc548\uacfc \ud76c\ub9dd\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc7ac\ubd09\uc77c\uc774\ub098 \uc218\uc608\uc5d0\uc11c \uc2ac\ud504\uace0 \uc7a5\uc911\ud55c \ubc14\ud0d5\uc5d0 \uacbd\ucf8c\ud55c \ubb34\ub2ac\ub97c \ub123\ub294 \uac83\uc774, \ubc1d\uc740 \ubc14\ud0d5\uc5d0 \uc5b4\ub461\uace0 \uce68\uc6b8\ud55c \ubb34\ub2ac\ub97c \ub123\ub294 \uac83\ubcf4\ub2e4 \ud6e8\uc52c \uc990\uac81\ub2e4.\\n\\n> \ubc88\uc131\uc740 \uc545\ub355\uc744 \uac00\uc7a5 \uc798 \ub4dc\ub7ec\ub0b4\uc9c0\ub9cc, \uc5ed\uacbd\uc740 \ubbf8\ub355\uc744 \uac00\uc7a5 \uc798 \ub4dc\ub7ec\ub0b8\ub2e4.\\n\\n### \ub0b4\uac00 \ubab0\ub790\ub358 \ud45c\ud604\ub4e4\\n\\n* **\uc131\ub839:** *holy spirit, holy ghost.* \uae30\ub3c5\uad50\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ub2e8\uc5b4\uc778\ub370, \ub098\ub85c\uc368\ub294 \uc124\uba85\uc744 \ubd10\ub3c4 \uc774\ud574\uac00 \ud798\ub4e4\ub2e4. \uc678\uad6d\uc5d0\uc11c\ub098 \ud55c\uad6d\uc5d0\uc11c\ub098 \uae30\ub3c5\uad50\uc778\ub4e4\ub3c4 \ud5f7\uac08\ub824\ud558\ub294 \uae00\ub3c4 \ub9ce\uc774 \ubcf4\uc778\ub2e4.\\n\\n> \ub610\ud55c \uc131\ub839\uc758 \ubd93\ub05d\uc740 \uc194\ub85c\ubaac\uc758 \uc601\ud654\ubcf4\ub2e4\ub3c4 \uc6a5\uc758 \uace0\ub09c\uc744 \uadf8\ub9ac\ub294 \ub370 \ub354\uc6b1 \ud070 \ud798\uc744 \ub4e4\uc774\uace0 \uc788\ub2e4.\\n\\n* **\uc218\uc608:** \uc190(\ub610\ub294 \ub2e8\uc21c\ud55c \ub3c4\uad6c \uc815\ub3c4\ub9cc \uc0ac\uc6a9\ud558\uc5ec)\uc73c\ub85c \ubb34\uc5b8\uac00\ub97c \ub9cc\ub4dc\ub294 \uac83.\\n\\n> \uc7ac\ubd09\uc77c\uc774\ub098 \uc218\uc608\uc5d0\uc11c \uc2ac\ud504\uace0 \uc7a5\uc911\ud55c \ubc14\ud0d5\uc5d0 \uacbd\ucf8c\ud55c \ubb34\ub2ac\ub97c \ub123\ub294 \uac83\uc774...\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/198)"},{"id":"francis-bacon-on-revenge","metadata":{"permalink":"/francis-bacon-on-revenge","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-18-francis-bacon-on-revenge/index.md","source":"@site/blog/2026-10-18-francis-bacon-on-revenge/index.md","title":"\ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4 - \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8","description":"\ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4 - \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8","date":"2026-10-17T16:07:48.632Z","tags":[{"inline":false,"label":"Life","permalink":"/tags/life","description":"rudevico\uc758 \uc804\ubc18\uc801\uc778 \uc77c\uc0c1 \uc774\uc57c\uae30"}],"readingTime":1.92,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"francis-bacon-on-revenge","title":"\ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4 - \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8","date":"2026-10-17T16:07:48.632Z","authors":"hyoyoonnam","tags":["life"],"image":"./cover.webp"},"unlisted":false,"prevItem":{"title":"Be water, my friend.","permalink":"/be-water-my-friend"},"nextItem":{"title":"\ud584\ubc84\uac70\uc640 \ud568\uaed8\ud558\ub294 \uc774\ubc29\uc778 \ub3c5\ud6c4\uac10","permalink":"/a-hamburger-and-the-stranger"}},"content":"![\ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4 - \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8](./cover.webp)\\n\\n5\uc77c \uc815\ub3c4 \uc804\uc774\uc5c8\uc744\uae4c, \ubb38\uc608 \ucd9c\ud310\uc0ac\uc5d0\uc11c \ucd9c\uac04\ud55c \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8\uc758 \uc218\ud544\uc9d1\uc744 \uc0c0\ub2e4. `\uc544\ub294 \uac83\uc774 \ud798\uc774\ub2e4`\ub77c\ub294 \uba85\uc5b8\uc73c\ub85c \uc720\uba85\ud55c\ub370, \ub098\ub3c4 \uba85\uc5b8 \uc815\ub3c4\ub9cc \uc54c\uace0 \uc788\uc744 \ubfd0, \uc790\uc138\ud788 \uc54c\uc9c0 \ubabb\ud574 \uc6b0\uc5f0\ud788 \ucc45\uc744 \ub9cc\ub09c \uae40\uc5d0 \uc54c\uc544\uac00\uace0 \uc2f6\uc5c8\uc74c\uc774 \uadf8 \uc774\uc720\ub2e4. \uadf8\ub9ac\uace0 \uc57d 270 \ud398\uc774\uc9c0 \uac00\ub7c9\uc758 \ucc45\uc5d0 \uc57d 60\uad8c\uc758 \uc8fc\uc81c\uac00 \uc2e4\ub9b4 \uc815\ub3c4\ub85c \uac01 \uc8fc\uc81c\uc5d0 \ub300\ud55c \ubd84\ub7c9\uc774 \uc801\uc5b4 \'\ud558\ub8e8 1\uc8fc\uc81c \ucc4c\ub9b0\uc9c0\'\ucc98\ub7fc \uc18c\ubc15\ud55c \ucde8\ubbf8\uac00 \ub420 \uc218 \uc788\uaca0\ub2e4\ub294 \uc0dd\uac01\uc774 \ub450 \ubc88\uc9f8 \uc774\uc720\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n<figure>\\n\\n![XL](./bacon-essays.jpg)\\n\\n<figcaption>https://www.yes24.com/product/goods/147564050</figcaption>\\n</figure>\\n\\n## \ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4?\\n\\n> *\ub0a8\uc5d0\uac8c \ud574\ub97c \ub07c\uce58\ub294 \uac83\uc774 \uc88b\uc544\uc11c \ud574\ub97c \ub07c\uce58\ub294 \uc0ac\ub78c\uc774 \uc5b4\ub514 \uc788\uaca0\ub294\uac00? \uc624\ub85c\uc9c0 \uadf8\ub807\uac8c \ud568\uc73c\ub85c\uc368 \uc774\ub4dd\uacfc \ucf8c\ub77d\uacfc \uba85\uc608 \ub530\uc704\ub97c \uc5bb\uc5b4\ub0b4\ub824\uace0 \uadf8\ub7ec\ub294 \uac83\uc774 \uc544\ub2cc\uac00? \uadf8\ub807\ub2e4\uba74 \uc0ac\ub78c\ub4e4\uc774 \ub098\ubcf4\ub2e4\ub3c4 \uc790\uae30 \uc790\uc2e0\uc744 \ub354 \uc0ac\ub791\ud55c\ub2e4 \ud558\uc5ec \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \ubb34\uc5c7\uc774\uaca0\ub294\uac00?* - \ubcf5\uc218, \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8\\n\\n\uc774 \uc8fc\uc7a5\uc744 \ubcf4\ub2c8 \'\uae30\ub300\uac00 \uc5c6\uc73c\uba74 \ud654\ub3c4 \ub098\uc9c0 \uc54a\ub294\ub2e4\'\uac00 \ub5a0\uc624\ub978\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc0c1\ub300\uc758 \ub098\uc05c \uc2b5\uad00\uc744 \'\uadf8\uac70 \ud558\uba74 \ub124\uac00 \uc190\ud574\uc9c0, \ub0b4 \uc190\ud574\ub0d0~\' \ud558\uba74\uc11c \ud53c\ub4dc\ubc31 \ud574\uc8fc\uc9c0 \uc54a\ub294 \uac74 \uc624\ud788\ub824 \uc18c\ud1b5 \ubd80\uc7ac\uac00 \ub41c\ub2e4. \uc11c\ub85c\uc758 \uc131\uc7a5\uc744 \uc704\ud55c\ub2e4\uba74 \ud53c\ub4dc\ubc31 \ud568\uc774 \uc88b\uc740 \uac70 \uc544\ub2cc\uac00..?\\n\\n\ucc45\uc5d0\uc11c\ub294 \'\ud654\ub294 \ub0b4\uc9c0 \ub9d0\uace0 \ucc28\ubd84\ud788 \uc798 \ub9d0\ud558\ub77c\'\ucc98\ub7fc \ub300\uc548\uc744 \uc81c\uc2dc\ud558\ub294 \uac8c \uc544\ub2c8\ub77c \'\ud654\ub97c \ub0bc \ud544\uc694\uac00 \uc5c6\ub2e4\'\ub9cc \ub9d0\ud558\uace0 \uc788\uc5b4\uc11c \'\ud654\ub97c \ub0b8\ub2e4\'\ub294 \ud45c\ud604\uc5d0 \uacb0\uad6d angry\ud558\uac8c \uc0c1\ub300\uc5d0\uac8c \ubb50\ub77c\uace0 \ud558\uae30, normal\ud558\uac8c \ud53c\ub4dc\ubc31\ud558\uae30 \ub4f1\uc774 \ud3ec\ud568\ub41c\ub2e4\uace0 \ubcf4\uc778\ub2e4. \uc774\uac78 \uc804\uc81c\ub85c \ud558\uba74 \uc704 \ubb38\ub2e8\uc5d0\uc11c \ub9d0\ud55c \uc18c\ud1b5 \ubd80\uc7ac\ub85c \uc778\ud574 \uacb0\uad6d \uc11c\ub85c\uc5d0\uac8c \ud574\uac00 \ub418\ub294 \uac70 \uc544\ub2cc\uac00 \uc2f6\ub124..\\n\\n## \ub0b4\uac00 \ubab0\ub790\ub358 \ud45c\ud604\ub4e4\\n\\n* \uace0\ub9e4\ud558\ub2e4: \uc778\uaca9\uc774\ub098 \ud488\uc131, \ud559\uc2dd, \uc7ac\uc9c8 \ub530\uc704\uac00 \ub192\uace0 \ube7c\uc5b4\ub098\ub2e4.\\n\\n> \uc6a5\uc758 \uc815\uc2e0\uc740 \uc774\uc5d0 \ube44\ud558\uc5ec \uace0\ub9e4\ud55c \ubaa9\uc18c\ub9ac\ub97c \uac00\uc9c4\ub2e4.\\n\\n* \uc7a0\uc5b8: \uc131\uacbd\uc758 \uc81c 24 / 20\uad8c. \uc0c1\ub2f9\uc218\uc758 \uad6c\uc808\uc744 \uc194\ub85c\ubaac\uc774 \uc9c1\uc811 \uc9c0\uc5c8\uac70\ub098 \ud3b8\uc9d1\ud588\ub2e4\uace0 \uc54c\ub824\uc838 \uc788\ub2e4. \uc5b8\uc5b4\ubcc4 \uba85\uce6d\uc740 \ub2e4\uc74c\uacfc \uac19\ub2e4. (\ub0b4\uac00 \ud574\uc11d\ud558\uae30\ub85c\ub294 \uaca9\uc5b8, \uc870\uc5b8 \uc815\ub3c4\ub85c \uc0dd\uac01\ub41c\ub2e4.)\\n\\n<table>\\n  <tbody>\\n    <tr><th scope=\\"row\\">\ud788\ube0c\ub9ac\uc5b4</th><td>\u05de\u05e9\u05dc\u05d9\xa0(Mishlei)</td></tr>\\n    <tr><th scope=\\"row\\">\uadf8\ub9ac\uc2a4\uc5b4</th><td>\u03a0\u03b1\u03c1\u03bf\u03b9\u03bc\u03af\u03b1\u03b9 (Paroimiai)</td></tr>\\n    <tr><th scope=\\"row\\">\ub77c\ud2f4\uc5b4</th><td>Proverbia</td></tr>\\n    <tr><th scope=\\"row\\">\uc601\uc5b4</th><td>Proverbs</td></tr>\\n    <tr><th scope=\\"row\\">\ud55c\uad6d\uc5b4</th><td>\uc7a0\uc5b8(\u7bb4\u8a00) (\ubc14\ub298\ub85c \ucc0c\ub974\ub294 \ub9d0)</td></tr>\\n  </tbody>\\n</table>\\n\\n## \ud53c\ub4dc\ubc31 to rilog\\n\\n### 1. \ud45c\uac00 \uae00\uba38\ub9ac \ud558\uc704 \uc601\uc5ed\uc73c\ub85c \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694\\n\\n* \uae00\uba38\ub9ac\\n  * \uae00\uba38\ub9ac \ud558\uc704 \uc601\uc5ed\\n* \uae00\uba38\ub9ac\\n\\n> \uc778\uc6a9\uc740 \uae00\uba38\ub9ac \ud558\uc704 \uc601\uc5ed\uc73c\ub85c \ub428\\n\\n* \uae00\uba38\ub9ac\\n\\n<table>\\n  <tbody>\\n    <tr><td>\ud45c\ub294 \uae00\uba38\ub9ac \ud558\uc704 \uc601\uc5ed\uc774 \uc548 \ub428</td><td></td></tr>\\n    <tr><td></td><td></td></tr>\\n  </tbody>\\n</table>\\n\\n### 2. \uba85\ub839\uc5b4 \uac80\uc0c9\uc5d0\uc11c table\uc758 \uacb0\uacfc\uac00 \uc5c6\uc5b4\uc694\\n\\n`/table` \uce58\uba74 \ud45c\uac00 \ub098\uc62c \uac70\ub77c \uae30\ub300\ud558\ub294\ub370 \uadf8\ub807\uc9c0 \uc54a\uc74c.\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@homo_scribens/posts/195)"},{"id":"a-hamburger-and-the-stranger","metadata":{"permalink":"/a-hamburger-and-the-stranger","editUrl":"https://github.com/hyoyoonnam/blog/2026-10-07-a-hamburger-and-the-stranger/index.md","source":"@site/blog/2026-10-07-a-hamburger-and-the-stranger/index.md","title":"\ud584\ubc84\uac70\uc640 \ud568\uaed8\ud558\ub294 \uc774\ubc29\uc778 \ub3c5\ud6c4\uac10","description":"IMG_2110.jpeg","date":"2026-10-06T18:33:46.544Z","tags":[{"inline":false,"label":"\ud68c\uace0","permalink":"/tags/retrospective"}],"readingTime":2.41,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"a-hamburger-and-the-stranger","title":"\ud584\ubc84\uac70\uc640 \ud568\uaed8\ud558\ub294 \uc774\ubc29\uc778 \ub3c5\ud6c4\uac10","date":"2026-10-06T18:33:46.544Z","authors":"hyoyoonnam","tags":["\ud68c\uace0"],"image":"./hamburger.jpg"},"unlisted":false,"prevItem":{"title":"\ub0a8\uc5d0\uac8c \ud654\ub97c \ub0bc \uae4c\ub2ed\uc774 \uc5c6\ub2e4 - \ud504\ub79c\uc2dc\uc2a4 \ubca0\uc774\ucee8","permalink":"/francis-bacon-on-revenge"},"nextItem":{"title":"[BE] \uc678\ubd80 API \uc5f0\ub3d9\uc740 \uc804\ub2ec\uc774 \uc544\ub2c8\ub77c \ubc88\uc5ed\uc774\ub2e4","permalink":"/translating-external-apis"}},"content":"![IMG_2110.jpeg](./hamburger.jpg)\\n\\n\uc0ac\uc2e4 \ud568\uaed8\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ub0b4\uac00 \ubb34\uc790\ube44\ud558\uac8c \uba39\uc5b4\uce58\uc6e0\uae30 \ub54c\ubb38. \uc544\ub2c8, \uc0ac\uc2e4 \uba39\uae30 \uc804\ubcf4\ub2e4 \ub098\uc640 \ub354 \ud568\uaed8\uc778 \uac78\uae4c? *\uc544\ubb34\ub798\ub3c4 \uc0c1\uad00\uc5c6\uaca0\ub2e4.*\\n\\n\x3c!-- truncate --\x3e\\n\\n\uc9c0\uae08 \uc2dc\uac01\uc740 2\uc2dc 50\ubd84\uc774\ub2e4. \uadf8\ub9ac\uace0 10\uc6d4 7\uc77c \uc218\uc694\uc77c\uc774\ub2e4. \uc7a5\uc18c\ub294 \uc218\ub0b4\uc5ed \ub9e5\ub3c4\ub0a0\ub4dc. 24\uc2dc\uac04 \ud504\ub79c\ucc28\uc774\uc988\uac00 \uc788\ub2e4\ub294 \uac74 \uc9d1\uc774 \uc544\ub2c8\uace0\uc11c\ub3c4 \uc5b8\uc81c\ub77c\ub3c4 \uba38\ubb34\ub97c \uc218 \uc788\ub2e4\ub294, \uadf8\ub7f0 \uc548\uc815\uac10\uc744 \ub0b4\uac8c \uc900\ub2e4.\\n\\n\ub098\ub294 \uc65c \uc774 \uc2dc\uac04\uc5d0 \uae68\uc5b4\uc788\uc73c\uba70, \uadf8\uac83\ub3c4 \uc544\ub291\ud55c \uc9d1\uc744 \ub194\ub450\uace0\uc11c\ub294, \uc9c0\uae08 \uc5ec\uae30\uc5d0 \uc788\ub294 \uac78\uae4c? \uc774 \uae00\uc5d0\uc11c \ub098\ub97c \ub9cc\ub0ac\ub4ef\uc774, \uc774\ubc29\uc778 \ub3c5\ud6c4\uac10\uc744 \uc4f0\ub7ec \uc654\ub2e4. \uc774\uc655 \uc0c8\ubcbd\ub0b4 \uc791\uc5c5\uc744 \ud560 \uac70\ub77c\uba74, \ud5c8\uae30\ub3c4 \ucc44\uc6b0\uace0 \uacf5\uac04 \ubd84\uc704\uae30\ub3c4 \ubc14\uafb8\uba74 \uc88b\uc558\uaca0\ub2e4\ub294 \ud310\ub2e8\uc774\uc5c8\ub2e4.\\n\\n\uc0ac\uc2e4 \uc774\ubc29\uc778 \ub3c5\ud6c4\uac10\uc744 \uc4f0\ub824\uace0 \ud55c \uac74 \uc544\ub2c8\ub2e4. \ubb3c\ub860, \uc368\uc57c\ub9cc \ud588\ub2e4. \ucd5c\uadfc \uc774\ubc29\uc778 \ucc45\uc744 \uc77d\uace0 \ud06c\ub8e8\ub4e4\uacfc \uc774\uc57c\uae30\ub97c \ub098\ub208 \uc801\uc774 \uc788\uace0, \uadf8 \ud6c4\uc18d \ud65c\ub3d9\uc73c\ub85c \ub3c5\ud6c4\uac10\uc744 \uc368\uc624\uae30\ub85c \ud588\uc73c\ub2c8\uae4c. \uc774 \uae00\uc744 \uc801\uae30 \uc804, \ub0b4\uac00 \ud558\uace0 \uc788\ub358 \uc791\uc5c5\uc740 \ub9c8\uc774\ub9ac\uc5bc\ud2b8\ub9bd(\uc774\ud558 \'\ub9c8\ub9ac\ud2b8\') \uc2e0\uc785 \uacf5\ucc44 \uc9c0\uc6d0\uc744 \uc704\ud55c \ud65c\ub3d9 \uc815\ub9ac\uc600\ub2e4.\\n\\n\uadf8\ub7f0\ub370 \ubb38\ub4dd \uc774\ub7f0 \uc0dd\uac01\uc774 \ub4e4\uc5c8\ub2e4.\\n\\n* \ub9c8\ub9ac\ud2b8 \uc9c0\uc6d0\uc744 \uc704\ud574 \uc9c0\ub09c \uc6b0\ud14c\ucf54 \ud65c\ub3d9\uc5d0\uc11c\uc758 \ud65c\ub3d9\uc744 \uc815\ub9ac\ud558\ub2c8, \ub9c8\ub9ac\ud2b8\uc640 \uc6b0\ud14c\ucf54 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc9c0\ud5a5\ud558\ub294 \ubc14\uac00 \'\ubb38\uc81c \uc911\uc2ec\uc758 \ud574\uacb0\'\ub85c \ube44\uc2b7\ud558\ub2e4.\\n* (\uc785\uc0ac\ud55c\ub2e4\uba74) \ub0b4\uac00 \uc9c0\uae08 \uc88b\uc544\ud558\ub294 \ubd84\uc57c\ub97c \ub9c8\ub9ac\ud2b8\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub179\uc5ec\ub0bc\uae4c?\\n  * \ucc45\uc774 \uc88b\ub2e4. \ucc45\uc5d0 \ub098\uc624\ub294 \uc601\ud654\ub098 \uc74c\uc545, \ub2e4\ub978 \ucc45, \uc74c\uc2dd\uacfc \uc7a5\uc18c\ub294 \ub0b4\uac8c \ub354 \ub9ce\uc740 \ud638\uac10\uc744 \uc900\ub2e4. \uc8fc\ub85c \uc77c\ubcf8 \ubb38\ud559\uc5d0\uc11c \ub354\uc6b1 \uadf8\ub7ec\ud55c\ub370, \uc77c\ubcf8 \uc560\ub2c8\uba54\uc774\uc158\uc5d0 \ub098\uc624\ub294 \uc7a5\uc18c\ub97c \ucc3e\uc544 \ub2e4\ub2c8\uba70 \uc0ac\uc9c4\ucc0d\ub294 \uac83\uc774 \uc720\ud589\ud558\ub4ef, \ucc45\uc5d0 \ub098\uc624\ub294 \uc7a5\uc18c\ub97c \ubc29\ubb38\ud558\uac70\ub098 \uc74c\uc2dd\uc744 \uba39\uc744 \uc218 \uc788\uac8c \ub3d9\uc120\uc744 \uacc4\ud68d\ud574\uc8fc\uba74 \uc5b4\ub5a8\uae4c? (\uc74c\uc545\uc774 \ub9ce\uae34 \ud588\uc9c0\ub9cc) \ubb34\ub77c\uce74\ubbf8 \ud558\ub8e8\ud0a4\uc758 \uc560\ud504\ud130\ub2e4\ud06c\uc5d0 \ub098\uc624\ub294 \uac83\ub4e4\uc744 \ucc45 \ub4b7\uba74\uc5d0 \uc801\uc73c\uba70 \uc77d\uc5c8\uc744 \ub54c\uac00 \uae30\uc5b5\ub09c\ub2e4. \uc7ac\ubbf8\ub3c4 \uc788\uace0, \uc778\uc0dd\uc744 \uc0b4\uc544\uac00\uba70 \ub098\ub9cc\uc758 \uc704\ud0a4\ub97c \ub9cc\ub4e4\uc5b4 \ubcf4\uace0 \uc2f6\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5c8\ub2e4.\\n\\n![\u1109\u1173\u110f\u1173\u1105\u1175\u11ab\u1109\u1163\u11ba 2026-10-07 03.02.31.png](./after-dark-notes.png)\\n\\n* \ub2ec\ub9ac\uae30\uac00 \uc88b\ub2e4. \ud574\uc678\uc5ec\ud589\uc744 \uc88b\uc544\ud558\uc9c0 \uc54a\uace0, \uc2eb\uc5b4\ud558\uc9c0\ub3c4 \uc54a\ub294. \ubcc4 \uac10\ud765\uc5c6\ub294 \ub098\uc778\ub370, \ucd5c\uadfc\uc5d0\ub294 \ud574\uc678\uc5d0\uc11c \ub7ec\ub2dd\ud558\ub294 \uac78 \uc0c1\uc0c1\ud558\uba74 \uc2ec\uc7a5\uc774 \ubc85\ucc28\uc624\ub974\uae30\uae4c\uc9c0 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \'\uc88b\uc740 \ub2ec\ub9ac\uae30 \ucf54\uc2a4\'\ub294 \uacc4\ud68d\ud558\uae30 \uc5b4\ub835\ub2e4. \uae34 \uac70\ub9ac\ub97c \ub2ec\ub9b4 \uacc4\ud68d\uc77c \ub54c \ub354\uc6b1 \uadf8\ub7ec\ud55c\ub370(\uc6b4\ub3d9\uc7a5 \ud2b8\ub799\ub9cc \ubc45\uae00\ubc45\uae00 \ub3cc\uba74 \uc7ac\ubbf8\uac00 \ub5a8\uc5b4\uc9c0\ub2c8\uae4c..) \uad6d\ub0b4\uc5d0\uc11c\ub3c4 \uc27d\uc9c0 \uc54a\uc740 \uc77c\uc774\ub77c \ud574\uc678 \ub098\uac00\uc11c\ub294 \ub354 \uc5b4\ub824\uc6b8 \uac70\ub77c \uc0dd\uac01\ud55c\ub2e4. \uc0ac\uc6a9\uc790\ub4e4\uc774 \uc548\uc2ec\ud558\uace0 \ub7ec\ub2dd\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d9\uc120\uc744 \uc0c1\uc138\ud558\uac8c \uacc4\ud68d\ud574\uc8fc\uba74 \uc5b4\ub5a8\uae4c?\\n\\n\uc704\uc5d0\uc11c \uc8fc\uc800\ub9ac\uc8fc\uc800\ub9ac \uc801\uc5c8\ub4ef, \ub9c8\ub9ac\ud2b8\uc758 \ubc29\ud5a5\uc131 \uc18d\uc5d0\uc11c \ub0b4\uac00 \uc7ac\ubbf8\uc788\uac8c \uc9c0\ub0bc \uc218 \uc788\ub2e4\ub294 \uae30\ub300\uac00 \ucef8\uace0 \uc6b0\ud14c\ucf54\uc5d0\uc11c \uc758\uc2dd\uc801\uc73c\ub85c \ud6c8\ub828\ud558\ub358 \uac00\uc124 \uacc4\ud68d, \ub370\uc774\ud130 \uae30\ubc18 \uc758\uc0ac\uacb0\uc815, \ubd84\uc57c\ub97c \uac00\ub9ac\uc9c0 \uc54a\uace0 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ud574\ubcf4\ub294 \uacbd\ud5d8\uae4c\uc9c0\ub3c4 \ub9c8\ub9ac\ud2b8\ub97c \uc704\ud574 \ub0b4\uac8c \uc8fc\uc5b4\uc84c\ub358 \uc77c\ub4e4\uc774\ub77c\uace0\uae4c\uc9c0 \ub290\uaef4\uc9c4\ub2e4.\\n\\n\uadf8\ub7f0\ub370, \uc774\ub7f0 \uc0dd\uac01\ub3c4 \ub4e0\ub2e4. \uc9c0\uae08 \ub0b4\uac00 \uc801\ub294 \uacbd\ud5d8\uc744, \ub2e4\ub978 \uae30\uc5c5\uc5d0\uc11c\ub3c4 \uc54c\uc544\ubd10\uc904\uae4c? \uac00\uce58\ub85c \uc778\uc815\ud574\uc904\uae4c? \ub2e4\ub978 \ubc31\uc5d4\ub4dc \ud06c\ub8e8\ub4e4\uc774 \uae30\uc5c5\uc5d0 \uc9c0\uc6d0\ud558\uae30 \uc704\ud574 \uc900\ube44\ud558\ub294 \ubc29\ud5a5\uacfc\ub294 \ucc28\uc774\uac00 \uc788\ub124?\\n\\n> *\ub098\ub294, \ucde8\uc5c5 \uc2dc\uc7a5\uc5d0\uc11c\uc758 \uc774\ubc29\uc778\uc778\uac00?*\\n\\n\uc704 \uace0\ubbfc\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0\uac00 \uc774 \ub3c5\ud6c4\uac10\uc758 \uc54c\ud30c\uc774\uc790 \uc624\uba54\uac00\uc774\ub2e4. \uace0\ubbfc\uc774\uae30\ub3c4 \ud558\uace0, \ubd88\uc548\uc774\uae30\ub3c4 \ud558\uba70, \ub3c4\uc804\uc774\uae30\ub3c4 \ud558\ub2e4. \uc774 \uc0c1\ud669\uc5d0 \ubd99\uc5ec\uc9c4 \uc5ec\ub7ec \uc774\ub984\ud45c\ub4e4\uc744, \uc5b4\ub5bb\uac8c \ud480\uc5b4\ub0bc\uc9c0\ub294 \ubaa8\ub974\uaca0\ub2e4.\\n\\n\uc774\uac83\uc870\ucc28\ub3c4 \uac00\uc124\uc774\uace0, \uac80\uc99d\uc774 \uc694\uad6c\ub41c\ub2e4. \ud504\ub85c\uc81d\ud2b8\ub098 \uc124\ubb38\uc5d0\uc11c\uc758 \uac00\uc124\uacfc\ub294 \ub2ec\ub9ac, \uadf8\ubcf4\ub2e4 \ud6e8\uc52c, \ubb34\uac70\uc6b4 \uac83\uc774\uc9c0\ub9cc. \uadf8\ub798\ub3c4 \ub0b4\uac00 \uac10\ub0b4\ud574\uc57c \ub41c\ub2e4.\\n\\n> *\uc774\uac83\uc774 \uc0b6\uc778\uac00? \uc88b\ub2e4. \uadf8\ub7ec\uba74 \ub2e4\uc74c\uc5d0\ub3c4 \ub2e4\uc2dc \ud558\uaca0\ub2e4.*\\n\\n\uc774 \ub3c5\ud6c4\uac10\uc5d0\uc11c \uc774\ubc29\uc778\uc758 \ub0b4\uc6a9\uc5d0 \uad00\ud574\uc11c\ub294 \uc801\uc9c0 \uc54a\uc558\uc9c0\ub9cc, \uadf8 \ubaa8\ub4e0 \ub0b4\uc6a9\uc774 \ub0b4 \ub2e8\uae30 \uae30\uc5b5 \uacf5\uac04\uc5d0 \uc788\uc744 \ub54c\ubcf4\ub2e4 \ubafc\ub974\uc18c\uc5d0 \uac00\uae4c\uc6cc\uc9d0\uc744 \ub290\ub080\ub2e4. \uadf8 \uc7a5\uba74\uc740 \uc5b4\ub5bb\uace0, \uadf8 \ubb38\uc7a5\uc740 \ubb58 \ud45c\ubc29\ud558\uace0, \uc774\ub7f0 \uc0dd\uac01\uc744 \ud558\uba70 \ucc45 \ub044\ud2b8\uba38\ub9ac\uc5d0 \uc801\ub294 \uac83\ubcf4\ub2e4 \ub9d0\uc774\ub2e4.\\n\\n\ub0b4\uac00 \ucc45\uc744 \ub300\ud558\ub358 \uc790\uc138\ub294 \uadf8 \uc18d\uc758 \ub4f1\uc7a5\uc778\ubb3c\ub4e4\uacfc \uc2dc\ub300\ub97c \ub290\ub07c\uace0, \ud5a5\uc720\ud590\ub294 \uac83\uc774\uc5c8\ub2e4. \ucc45\uc73c\ub85c \ud558\uc5ec\uae08 \ub2e4\ub978 \uc778\ubb3c\uc758 \uc0b6\uc744 \ubc30\uc6b4\ub2e4\uace0\ub4e4 \ud558\uc9c0 \uc54a\ub294\uac00. \uadf8\ub7f0\ub370 \uc9c0\uae08\uc740 \ubafc\ub974\uc18c\uc758 \uc0b6\uc73c\ub85c\ubd80\ud130\ub77c\uba74, \ub418\ub824 \uba40\uc5b4\uc84c\ub2e4. \ucc45\uc758 \ub0b4\uc6a9\uc740 \ubaa8\ub974\uaca0\ub2e4. \ucc45\uc758 \ub0b4\uc6a9\uc740 \ubaa8\ub974\uc9c0\ub9cc, \ub098\ub294 \uc774 \uc21c\uac04 \uc774\ubc29\uc778\uc774 \ub41c\ub2e4.\\n\\n### *3\uc2dc 33\ubd84. \uc774 \uae00\uc740 \ub05d\ub09c\ub2e4.*\\n\\n![IMG_2111.jpeg](./after-the-meal.jpg)\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@rudevico/posts/155)"},{"id":"translating-external-apis","metadata":{"permalink":"/translating-external-apis","editUrl":"https://github.com/hyoyoonnam/blog/2026-08-28-translating-external-apis/index.md","source":"@site/blog/2026-08-28-translating-external-apis/index.md","title":"[BE] \uc678\ubd80 API \uc5f0\ub3d9\uc740 \uc804\ub2ec\uc774 \uc544\ub2c8\ub77c \ubc88\uc5ed\uc774\ub2e4","description":"\uc678\ubd80 API \uc5f0\ub3d9\uc744 \ub2e8\uc21c\ud55c DTO \ub9e4\ud551\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c \ub2e4\ub978 \uacc4\uc57d\uc744 \ubc88\uc5ed\ud558\ub294 \uacfc\uc815*\uc73c\ub85c \ubc14\ub77c\ubcfc \uc218 \uc788\uc5b4\uc694.","date":"2026-08-28T03:19:38.489Z","tags":[{"inline":false,"label":"\uae30\uc220","permalink":"/tags/tech"}],"readingTime":6.2,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"translating-external-apis","title":"[BE] \uc678\ubd80 API \uc5f0\ub3d9\uc740 \uc804\ub2ec\uc774 \uc544\ub2c8\ub77c \ubc88\uc5ed\uc774\ub2e4","date":"2026-08-28T03:19:38.489Z","authors":"hyoyoonnam","tags":["\uae30\uc220"]},"unlisted":false,"prevItem":{"title":"\ud584\ubc84\uac70\uc640 \ud568\uaed8\ud558\ub294 \uc774\ubc29\uc778 \ub3c5\ud6c4\uac10","permalink":"/a-hamburger-and-the-stranger"},"nextItem":{"title":"SQ3R\uc774\ub780","permalink":"/explanation-about-SQ3R"}},"content":":::note[\uc774 \uae00\uc744 \uc77d\uc73c\uba74]\\n\\n* \uc678\ubd80 API \uc5f0\ub3d9\uc744 \ub2e8\uc21c\ud55c DTO \ub9e4\ud551\uc774 \uc544\ub2c8\ub77c **\uc11c\ub85c \ub2e4\ub978 \uacc4\uc57d\uc744 \ubc88\uc5ed\ud558\ub294 \uacfc\uc815**\uc73c\ub85c \ubc14\ub77c\ubcfc \uc218 \uc788\uc5b4\uc694.\\n* \uc678\ubd80 \ub370\uc774\ud130\uc758 \ubc88\uc5ed \uacbd\uacc4\ub97c \uc5b4\ub514\uc5d0 \ub450\uace0, \uc5b8\uc81c \ub354 \ubc14\uae65\uc73c\ub85c \uc62e\uaca8\uc57c \ud558\ub294\uc9c0 \uc54c \uc218 \uc788\uc5b4\uc694.\\n\\n:::\\n\\n{/* truncate */}\\n\\n## 1. DTO\ub97c \ubd84\ub9ac\ud558\uba74 \uc678\ubd80 API\ub85c\ubd80\ud130 \ub3c5\ub9bd\uc801\uc77c\uae4c?\\n\\nChaekchaek\uc740 \ub3c4\uc11c \uac80\uc0c9\uc744 \uc704\ud574 \uc54c\ub77c\ub518 Search API\ub97c \uc0ac\uc6a9\ud55c\ub2e4.\\n\\n\uc54c\ub77c\ub518\uc5d0\uc11c \ubc1b\uc740 \uc751\ub2f5\uc744 \uadf8\ub300\ub85c \ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0 \ubc18\ud658\ud558\uc9c0\ub294 \uc54a\uc558\ub2e4. \uc678\ubd80 API \uc751\ub2f5\uc744 \ubc1b\ub294 DTO\uc640 \ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0 \ubc18\ud658\ud560 DTO\ub97c \ucc98\uc74c\ubd80\ud130 \ub530\ub85c \ub9cc\ub4e4\uc5c8\ub2e4.\\n\\n```less\\nAladin Search API\\n        \u2193     (\ubc31\uc5d4\ub4dc \uacbd\uacc4 \uc2dc\uc791)\\nAladinSearchResponse\\n        \u2193\\nBookSearchResponse\\n        \u2193     (\ubc31\uc5d4\ub4dc \uacbd\uacc4 \uc885\ub8cc)\\nChaekchaek Client\\n```\\n\\n\uac89\uc73c\ub85c \ubcf4\uba74 \uc678\ubd80 API\uc640 \uacf5\uac1c API\ub294 \uc774\ubbf8 \ubd84\ub9ac\ub418\uc5b4 \uc788\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uc2e4\uc81c `BookSearchResponse`\uc5d0\ub294 \uc54c\ub77c\ub518 API\uc758 \ud45c\ud604 \ubc29\uc2dd\uc778 `totalResults`, `startIndex`, `itemsPerPage` \ub4f1\uc774 \uc5ec\uc804\ud788 \ub0a8\uc544 \uc788\ub2e4.\\n\\n```java\\npublic record BookSearchResponse(\\n        int totalResults,\\n        int startIndex,\\n        int itemsPerPage,\\n        boolean hasNext,\\n        List<BookItem> items\\n) {\\n}\\n```\\n\\n\uac1d\uccb4\ub294 \ub458\ub85c \ub098\ub258\uc5c8\uc9c0\ub9cc, **\uc678\ubd80 API\uac00 \ub370\uc774\ud130\ub97c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd\uc740 \uacf5\uac1c \uacc4\uc57d\uc5d0 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc5c8\ub2e4.**\\n\\n\ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc758\uc874\ud574\uc57c \ud558\ub294 \ub300\uc0c1\uc740 `\uc54c\ub77c\ub518\uc758 \uacc4\uc57d`\uc774 \uc544\ub2c8\ub77c `Chaekchaek\uc774 \uc815\uc758\ud55c \uacc4\uc57d`\uc774\ub2e4.\\n\\n**DTO\ub97c \ubd84\ub9ac\ud558\ub294 \uc77c\uacfc \uc678\ubd80 \uacc4\uc57d\uc73c\ub85c\ubd80\ud130 \ub3c5\ub9bd\ud558\ub294 \uc77c\uc740 \uac19\uc9c0 \uc54a\uc558\ub2e4.**\\n\\n***\\n\\n## 2. \uc678\ubd80 API\uc640 \uc6b0\ub9ac \uc11c\ube44\uc2a4\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5b8\uc5b4\ub97c \uc4f4\ub2e4\\n\\n\uac19\uc740 \ucc45 \uac80\uc0c9 API\ub77c\ub3c4 \uacf5\uae09\uc790\ub9c8\ub2e4 \ub370\uc774\ud130\ub97c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4.\\n\\n| \uc758\ubbf8         | \uc54c\ub77c\ub518                       | \ub2e4\ub978 \uacf5\uae09\uc790                  |\\n| ---------- | ------------------------- | ----------------------- |\\n| \uac80\uc0c9 \uacb0\uacfc      | `item`                    | `documents`             |\\n| \uc800\uc790         | \uc5ed\ud560\uae4c\uc9c0 \ud3ec\ud568\ud55c `author: String` | `authors: String[]`     |\\n| \ubc88\uc5ed\uc790        | `author` \uc548\uc5d0 \ud3ec\ud568            | `translators: String[]` |\\n| \ub2e4\uc74c \ud398\uc774\uc9c0     | \ud398\uc774\uc9c0 \uad00\ub828 \uac12\uc744 \uc774\uc6a9\ud574 \uacc4\uc0b0          | `is_end` \ub4f1 \ubcc4\ub3c4 \uc0c1\ud0dc \uc81c\uacf5     |\\n\\n\ud544\ub4dc \uc774\ub984\ub9cc \ub2e4\ub978 \uac83\ub3c4 \uc544\ub2c8\ub2e4.\\n\\n\uac19\uc740 \uc815\ubcf4\ub97c \uc5b4\ub5a4 \ub2e8\uc704\ub85c \ub098\ub204\uace0 \uc5b4\ub5a4 \uc0c1\ud0dc\ub85c \ud45c\ud604\ud560\uc9c0 \uc790\uccb4\uac00 \ub2e4\ub974\ub2e4.\\n\\n\ub450 \ud45c\ud604 \uc911 \uc5b4\ub290 \ud558\ub098\uac00 \uc808\ub300\uc801\uc73c\ub85c \ub354 \uc62c\ubc14\ub978 \uac83\uc740 \uc544\ub2c8\ub2e4.\\n\\n**\uc54c\ub77c\ub518\uc5d0\ub294 \uc54c\ub77c\ub518\uc758 \ubaa8\ub378**\uc774 \uc788\uace0, **Chaekchaek\uc5d0\ub294 Chaekchaek\uc758 \ubaa8\ub378**\uc774 \uc788\ub2e4.\\n\\n\uc678\ubd80 API \uc5f0\ub3d9\uc740 \ub2e8\uc21c\ud788 \ud544\ub4dc\uba85\uc744 \ubc14\uafb8\ub294 \uc791\uc5c5\uc774 \uc544\ub2c8\ub2e4. **\uc678\ubd80 \uc2dc\uc2a4\ud15c\uc758 \uc815\ubcf4\ub97c \uc6b0\ub9ac \uc11c\ube44\uc2a4\uc5d0\uc11c \uc720\uc758\ubbf8\ud55c \uc815\ubcf4\ub85c \ubc88\uc5ed**\ud558\ub294 \uc791\uc5c5\uc774\ub2e4.\\n\\n\uc2e4\uc81c\ub85c \ud588\ub358 \ubc88\uc5ed\uc740 \ub2e4\uc74c \uc138 \uac00\uc9c0\ub2e4.\\n\\n1. \uc678\ubd80\uc758 \uc6a9\uc5b4\ub97c \uc6b0\ub9ac \uc11c\ube44\uc2a4\uc758 \uc6a9\uc5b4\ub85c \ubc14\uafb8\ub294 \uac83\\n   * ex. \uac80\uc0c9\ub41c \ucc45\uc758 \uac1c\uc218\uc5d0 \ub300\ud55c \uc6a9\uc5b4\ub97c `totalResults` -> `totalCount`\\n2. \uc678\ubd80\uc758 \ube44\uc815\ud615 \ud45c\ud604\uc744 \uc6b0\ub9ac \uc11c\ube44\uc2a4\uac00 \uc0ac\uc6a9\ud560 \uad6c\uc870\ub85c \ubc14\uafb8\ub294 \uac83\\n   * ex. \uc800\uc790\uc640 \uc2dd\uc790 \ud45c\ud604\uc744 `\ubaa8\ub450 \ud558\ub098\uc758 \ubb38\uc790\uc5f4` -> `\uc800\uc790, \uc2dd\uc790 \uac01\uac01 \ubb38\uc790\uc5f4 \ubc30\uc5f4`\\n3. \uc678\ubd80 \uc2dc\uc2a4\ud15c\uc758 \uc0c1\ud0dc \uc815\ubcf4\ub97c \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ucde8\ud560 \ub2e4\uc74c \ud589\ub3d9\uc73c\ub85c \ubc14\uafb8\ub294 \uac83\\n   * ex. \ud398\uc774\uc9c0\ub124\uc774\uc158\uc744 `\ud604\uc7ac \ud398\uc774\uc9c0 \ubc88\ud638` -> `\ub2e4\uc74c \ud398\uc774\uc9c0 \ubc88\ud638`\\n\\n\ud2b9\ud788 \ub4a4\uc758 \ub450 \uc791\uc5c5\uc5d0\ub294 \ub2e8\uc21c \ub9e4\ud551\uc744 \ub118\uc5b4 **\uc6b0\ub9ac \uc11c\ube44\uc2a4\uac00 \ubb34\uc5c7\uc744 \uc758\ubbf8 \uc788\ub294 \uc815\ubcf4\ub85c \ubcfc \uac83\uc778\uc9c0\uc5d0 \ub300\ud55c \uc815\ucc45**\uc774 \ub2f4\uae34\ub2e4.\\n\\n***\\n\\n## 3. \uc678\ubd80 DTO\ub294 \uc678\ubd80\uc758 \uc5b8\uc5b4\ub97c \ubcf4\uc874\ud55c\ub2e4\\n\\n\uc774\ub7f0 \uc758\ubb38\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4.\\n\\n> \uc5b4\ucc28\ud53c \uc6b0\ub9ac \uc11c\ube44\uc2a4\uac00 `author`\uc640 `translator`\ub97c \uad6c\ubd84\ud574\uc11c \uc0ac\uc6a9\ud560 \uac70\ub77c\uba74, \uc54c\ub77c\ub518\uc73c\ub85c\ubd80\ud130 \uc751\ub2f5\uc744 \ubc1b\ub294 \uc21c\uac04\ubd80\ud130 \ub098\ub204\uba74 \ub418\ub294 \uac70 \uc544\ub2c8\uc57c?\\\\\\n> \uad73\uc774 `AladinSearchResponse`\uc640 `BookSearchResponse`\ub97c \ub098\ub20c \ud544\uc694\uac00 \uc788\uc744\uae4c?\\n\\n\ubb3c\ub860 \uae30\uc220\uc801\uc73c\ub85c\ub294 \uac00\ub2a5\ud558\ub2e4. \uadf8\ub798\ub3c4 \uc54c\ub77c\ub518 \uc751\ub2f5\uc6a9 DTO\ub294 \uc720\uc9c0\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4.\\n\\nSOLID \uc6d0\uce59\uc740 \uc774\ubbf8 \uc775\uc219\ud558\ub2e4\uace0 \uac00\uc815\ud558\uaca0\ub2e4. \uadf8\uc911\uc5d0\uc11c\ub3c4 SRP\ub294 \uc678\ubd80 \uc751\ub2f5\uc744 \ubc1b\ub294 DTO\uac00 \ubcc4\ub3c4\ub85c \ud544\uc694\ud55c \uc774\uc720\ub97c \uc798 \uc124\uba85\ud55c\ub2e4.\\n\\n\ucc45 \uac80\uc0c9 API\uc5d0 \uc4f0\uc774\ub294 \ub450 DTO\ub294 \uc11c\ub85c \ub2e4\ub978 \uc774\uc720\ub85c \ubcc0\uacbd\ub41c\ub2e4.\\n\\n```javascript\\nAladinSearchResponse\uc758 \ubcc0\uacbd \uc774\uc720\\n\u2192 \uc54c\ub77c\ub518 API\uc758 \uacc4\uc57d\uc774 \ubc14\ub00c\uc5c8\uc744 \ub54c\\n\\nChaekchaek\uc758 \uac80\uc0c9 \uacb0\uacfc \ubaa8\ub378\uc758 \ubcc0\uacbd \uc774\uc720\\n\u2192 Chaekchaek\uc758 \uc694\uad6c\uc0ac\ud56d\uc774 \ubc14\ub00c\uc5c8\uc744 \ub54c\\n```\\n\\n\ub450 DTO\ub294 \uc11c\ub85c \ub2e4\ub978 \ucc45\uc784\uc744 \uac00\uc9c4\ub2e4.\\n\\n\ub450 DTO\ub97c \ubd84\ub9ac\ud574\uc57c \uc678\ubd80 API\uc758 \ubcc0\ud654\uac00 \uc6b0\ub9ac \uc11c\ube44\uc2a4\uc758 \uacc4\uc57d\uc73c\ub85c \uadf8\ub300\ub85c \uc804\ud30c\ub418\ub294 \uc77c\uc744 \ub9c9\uc744 \uc218 \uc788\ub2e4.\\n\\n***\\n\\n## 4. \ubc88\uc5ed\uc740 \uc774\ub984\uc744 \ubc14\uafb8\ub294 \uac83\ubcf4\ub2e4 \ub9ce\uc740 \uc77c\uc744 \ud55c\ub2e4\\n\\n\uc2e4\uc81c \uad6c\ud604\uc5d0\uc11c \ud2b9\ud788 \ud544\uc694\ud588\ub358 \ubc88\uc5ed\uc740 \ub450 \uac00\uc9c0\uc600\ub2e4.\\n\\n### 4.1. \uae30\uc5ec\uc790 \ud45c\ud604\uc744 \uad6c\uc870\ub85c \ubc88\uc5ed\ud55c\ub2e4\\n\\n\uc54c\ub77c\ub518\uc740 \uc800\uc790\uc640 \ubc88\uc5ed\uc790\ub97c \ub2e4\uc74c\ucc98\ub7fc \ud558\ub098\uc758 \ubb38\uc790\uc5f4\uc5d0 \ub2f4\ub294\ub2e4.\\n\\n```json\\n\uc564\ub514 \uc704\uc5b4 (\uc9c0\uc740\uc774), \ubc15\uc544\ub78c (\uc62e\uae34\uc774)\\n```\\n\\n\ud558\uc9c0\ub9cc \uc6b0\ub9ac \ud074\ub77c\uc774\uc5b8\ud2b8\ub294 \uc800\uc790\uc640 \ubc88\uc5ed\uc790\ub97c \uad6c\ubd84\ud574 \uc0ac\uc6a9\ud574\uc57c \ud588\ub2e4.\\n\\n```json\\n{\\n  \\"authors\\": [\\"\uc564\ub514 \uc704\uc5b4\\"],\\n  \\"translators\\": [\\"\ubc15\uc544\ub78c\\"]\\n}\\n```\\n\\n\uadf8\ub798\uc11c \ubb38\uc790\uc5f4\uc744 \ud574\uc11d\ud558\ub294 `AladinContributorParser`\ub97c \ub9cc\ub4e4\uc5c8\ub2e4.\\n\\n\uc774 \uacfc\uc815\uc5d0\uc11c \uc27c\ud45c\ub9cc \uae30\uc900\uc73c\ub85c \ub098\ub20c \uc218\ub294 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\ub3c4 \uc54c\uac8c \ub410\ub2e4.\\n\\n```javascript\\n\ubbfc\uad00\uc2dd (\ud544\uba85, \uccad\uc6d0) (\uc9c0\uc740\uc774)\\n```\\n\\n\uad04\ud638 \uc548\uc758 \uc27c\ud45c\ub294 \uc0ac\ub78c\uc744 \uad6c\ubd84\ud558\ub294 \uae30\ud638\uac00 \uc544\ub2c8\ub2e4.\\n\\n\uc54c\ub77c\ub518\uc774 \uc81c\uacf5\ud558\ub294 \ubb38\uc790\uc5f4\uc758 \uaddc\uce59\uc744 \ud574\uc11d\ud558\uace0, \uc774\ub97c Chaekchaek\uc774 \uc774\ud574\ud560 \uc218 \uc788\ub294 \uad6c\uc870\ub85c \ubcc0\ud658\ud574\uc57c \ud588\ub2e4.\\n\\n\uc911\uc694\ud55c \uac83\uc740 \ud30c\uc2f1 \uc54c\uace0\ub9ac\uc998 \uc790\uccb4\uac00 \uc544\ub2c8\ub2e4.\\n\\n**\uc678\ubd80\uc758 \ud45c\ud604\uc744 \uadf8\ub300\ub85c \uc804\ub2ec\ud558\uc9c0 \uc54a\uace0 \uc6b0\ub9ac \uc11c\ube44\uc2a4\uc5d0 \ud544\uc694\ud55c \uc758\ubbf8\ub85c \ubc14\uafb8\uc5c8\ub2e4**\ub294 \ub370 \uc788\ub2e4.\\n\\n\uc774\ub54c\ubd80\ud130 \ubb34\uc5c7\uc744 \ubcf4\uc874\ud558\uace0 \ubb34\uc5c7\uc744 \ubc84\ub9b4\uc9c0\ub3c4 \uacb0\uc815\ud558\uac8c \ub41c\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ud604\uc7ac \uc11c\ube44\uc2a4\uc5d0\uc11c `\uc9c0\uc740\uc774`, `\uc62e\uae34\uc774`\ub9cc \uc0ac\uc6a9\ud558\uace0 `\uadf8\ub9bc`, `\uac10\uc218`, `\uc5ee\uc740\uc774`\ub97c \uc81c\uc678\ud55c\ub2e4\uba74, \uadf8\uac83 \uc5ed\uc2dc \ud558\ub098\uc758 \uacb0\uc815\uc774\ub2e4.\\n\\n> **\ubc88\uc5ed \uacfc\uc815\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \uc815\ubcf4 \uc190\uc2e4\ub3c4 \ud558\ub098\uc758 \uc815\ucc45\uc774\ub2e4.**\\n\\n### 4.2. \ud398\uc774\uc9c0 \uc0c1\ud0dc\ub97c \ub2e4\uc74c \ud589\ub3d9\uc73c\ub85c \ubc88\uc5ed\ud55c\ub2e4\\n\\n\uc54c\ub77c\ub518\uc740 \ub2e4\uc74c \uc138 \uac12\uc73c\ub85c \ud398\uc774\uc9c0 \uc815\ubcf4\ub97c \ud45c\ud604\ud55c\ub2e4.\\n\\n```javascript\\ntotalResults\\nstartIndex\\nitemsPerPage\\n```\\n\\n\ucc98\uc74c\uc5d0\ub294 \uc774 \uac12\ub4e4\uacfc `hasNext`\ub97c \uacf5\uac1c API\uc5d0\ub3c4 \uc81c\uacf5\ud588\ub2e4.\\n\\n\uadf8\ub7ec\uba74 \ud074\ub77c\uc774\uc5b8\ud2b8\ub294 \ub2e4\uc74c \ud398\uc774\uc9c0\ub97c \uc694\uccad\ud558\uae30 \uc704\ud574 \uc774\ub7f0 \uaddc\uce59\uc744 \uc54c\uc544\uc57c \ud55c\ub2e4.\\n\\n```js\\nconst nextPage = hasNext ? startIndex + 1 : null;\\n```\\n\\n\ud558\uc9c0\ub9cc \uc774 \uacc4\uc0b0 \uaddc\uce59\uc740 \uc54c\ub77c\ub518\uc758 \ud398\uc774\uc9c0 \ubaa8\ub378\uc744 \uc544\ub294 \uc11c\ubc84\uac00 \ucc98\ub9ac\ud560 \uc218 \uc788\uace0, \ucc98\ub9ac\ud558\ub294 \ud3b8\uc774 \ub0ab\ub2e4.\\n\\n\uadf8\ub798\uc11c \uacf5\uac1c \uc751\ub2f5\uc740 \ub2e4\uc74c\ucc98\ub7fc \ub2e8\uc21c\ud574\uc84c\ub2e4.\\n\\n```java\\npublic record BookSearchResponse(\\n        int totalCount,\\n        Integer nextPage,\\n        List<BookItem> items\\n) {\\n}\\n```\\n\\n\uc774\uc81c \ud074\ub77c\uc774\uc5b8\ud2b8\ub294 \uc54c\ub77c\ub518\uc758 \ud398\uc774\uc9c0\ub124\uc774\uc158 \ubc29\uc2dd\uc744 \ubab0\ub77c\ub3c4 \ub41c\ub2e4. `nextPage`\uac00 \uc788\ub2e4\uba74 \uadf8 \uac12\uc744 \uc694\uccad\ud558\uba74 \ub41c\ub2e4.\\n\\n```less\\nnextPage = 3\\n\u2192 \ub2e4\uc74c \uc694\uccad\uc5d0\uc11c 3\uc744 \uc0ac\uc6a9\ud55c\ub2e4.\\n\\nnextPage = null\\n\u2192 \ub354 \uc774\uc0c1 \uc694\uccad\ud560 \ud398\uc774\uc9c0\uac00 \uc5c6\ub2e4.\\n```\\n\\n\uc5ec\uae30\uc11c `hasNext`\uc640 `nextPage`\ub294 \ube44\uc2b7\ud574 \ubcf4\uc774\uc9c0\ub9cc \uc758\ubbf8\uac00 \ub2e4\ub974\ub2e4.\\n\\n`hasNext`\ub294 **\ud604\uc7ac \uc0c1\ud0dc**\ub97c \uc54c\ub824\uc900\ub2e4.\\n\\n\ubc18\uba74 `nextPage`\ub294 **\ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ub2e4\uc74c\uc5d0 \ud574\uc57c \ud560 \ud589\ub3d9\uc5d0 \ud544\uc694\ud55c \uac12**\uc744 \uc54c\ub824\uc900\ub2e4.\\n\\n\ud074\ub77c\uc774\uc5b8\ud2b8\ub294 \ub354 \uc774\uc0c1 `startIndex`, `itemsPerPage`\uc758 \uc758\ubbf8\ub098 \ub2e4\uc74c \ud398\uc774\uc9c0\ub97c \uacc4\uc0b0\ud558\ub294 \ubc29\ubc95\uc744 \uc54c \ud544\uc694\uac00 \uc5c6\ub2e4.\\n\\n\ud575\uc2ec\uc740 \ud544\ub4dc\ub97c \uc904\uc778 \ub370 \uc788\uc9c0 \uc54a\ub2e4.\\n\\n> **\uc678\ubd80 \uc2dc\uc2a4\ud15c\uc758 \uc0c1\ud0dc\ub97c \uadf8\ub300\ub85c \ub178\ucd9c\ud558\ub294 \ub300\uc2e0, \uc6b0\ub9ac \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ucde8\ud560 \ub2e4\uc74c \ud589\ub3d9\uc73c\ub85c \ubc88\uc5ed\ud588\ub2e4.**\\n\\n***\\n\\n## 5. \ubc88\uc5ed\uc758 \uacbd\uacc4\ub294 \uc5b4\ub514\uc5d0 \ub458\uae4c?\\n\\n\ub2f9\uc2dc \ubc88\uc5ed\uc740 `BookSearchService`\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc84c\ub2e4.\\n\\n```javascript\\nAladin Search API\\n        \u2193\\nAladinBookClient\\n        \u2193\\nAladinSearchResponse\\n        \u2193\\nBookSearchService\\n  - \uae30\uc5ec\uc790 \uad6c\uc870\ud654\\n  - nextPage \uacc4\uc0b0\\n  - \ud544\ub4dc \ubcc0\ud658\\n        \u2193\\nBookSearchResponse\\n        \u2193\\nChaekchaek Client\\n```\\n\\n\uc774 \uad6c\uc870 \ub355\ubd84\uc5d0 \ud074\ub77c\uc774\uc5b8\ud2b8\ub294 \uc54c\ub77c\ub518\uc758 \ud544\ub4dc\uba85\uc774\ub098 \ud398\uc774\uc9c0 \uacc4\uc0b0 \uaddc\uce59\uc744 \uc54c \ud544\uc694\uac00 \uc5c6\uc5c8\ub2e4.\\n\\n\ub2e4\ub9cc `BookSearchService`\ub294 \uc5ec\uc804\ud788 `AladinSearchResponse`, `AladinBookItem`\ucc98\ub7fc \uc678\ubd80 \uacf5\uae09\uc790\uc758 \ud0c0\uc785\uc744 \uc9c1\uc811 \uc54c\uace0 \uc788\uc5c8\ub2e4.\\n\\n**\uc678\ubd80 \uacc4\uc57d\uc740 \uacf5\uac1c API\uae4c\uc9c0 \uc624\uc9c0 \uc54a\uc558\uc9c0\ub9cc, \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \uc11c\ube44\uc2a4\uae4c\uc9c0\ub294 \ub4e4\uc5b4\uc640 \uc788\uc5c8\ub2e4.**\\n\\n\uadf8\ub807\ub2e4\uace0 \uc774 \uad6c\uc870\uac00 \ucc98\uc74c\ubd80\ud130 \uc798\ubabb\ub41c \uc120\ud0dd\uc774\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4.\\n\\n\ub2f9\uc2dc \uac80\uc0c9 \uacf5\uae09\uc790\ub294 \ud558\ub098\uc600\uace0 \uac80\uc0c9 \uae30\ub2a5\uc744 \ube60\ub974\uac8c \uc644\uc131\ud558\ub294 \uc77c\uc774 \ub354 \uc911\uc694\ud588\ub2e4.\\n\\n**\ucd94\uc0c1\ud654 \uc790\uccb4\ub3c4 \ube44\uc6a9\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.**\\n\\n\uc911\uc694\ud55c \uac83\uc740 \ucc98\uc74c\ubd80\ud130 \ubaa8\ub4e0 \uacbd\uacc4\ub97c \uc644\ubcbd\ud558\uac8c \ub9cc\ub4dc\ub294 \uc77c\uc774 \uc544\ub2c8\ub77c, **\ud604\uc7ac \uacbd\uacc4\uac00 \uc5b4\ub5a4 \ubcc0\uacbd \ube44\uc6a9\uc744 \ub0a8\uae30\uace0 \uc788\ub294\uc9c0 \uc544\ub294 \uac83**\uc774\ub2e4.\\n\\n\uac80\uc0c9 \uacf5\uae09\uc790\uc758 \uad50\uccb4\ub098 \ucd94\uac00\uac00 \uc2e4\uc81c \ubcc0\uacbd \uac00\ub2a5\uc131\uc73c\ub85c \ub2e4\uac00\uc628\ub2e4\uba74, \ubc88\uc5ed\uc774 \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \uc11c\ube44\uc2a4\uc5d0 \ub3c4\ub2ec\ud558\uae30 \uc804\uc5d0 \ub05d\ub098\ub3c4\ub85d \uacbd\uacc4\ub97c \uc62e\uae38 \uc218 \uc788\ub2e4.\\n\\n```javascript\\nAladin Search API\\n        \u2193\\nAladin Adapter\\n  - \uc678\ubd80 \uacc4\uc57d \ud574\uc11d\\n  - \uae30\uc5ec\uc790 \uad6c\uc870\ud654\\n  - \ud398\uc774\uc9c0 \uc815\ubcf4 \uacc4\uc0b0\\n        \u2193\\nBookSearchResult\\n        \u2193\\nBookSearchService\\n```\\n\\n\uc11c\ube44\uc2a4\uac00 \ubc1b\ub294 \uc2dc\uc810\uc5d0\ub294 \uc774\ubbf8 Chaekchaek\uc774 \uc815\uc758\ud55c \uac80\uc0c9 \uacb0\uacfc\uac00 \ub41c\ub2e4.\\n\\n\uc774\uc81c `BookSearchService`\ub294 \uac80\uc0c9 \uacb0\uacfc\uac00 \uc5b4\ub290 \uacf5\uae09\uc790\uc5d0\uc11c \uc654\ub294\uc9c0, \uacf5\uae09\uc790\uac00 \ub370\uc774\ud130\ub97c \uc5b4\ub5a4 \ud615\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\ub294\uc9c0 \uc54c \ud544\uc694\uac00 \uc5c6\ub2e4.\\n\\n\uc911\uc694\ud55c \uac83\uc740 \ud2b9\uc815 \uc778\ud130\ud398\uc774\uc2a4\ub098 \uc5b4\ub311\ud130 \ud328\ud134 \uc790\uccb4\uac00 \uc544\ub2c8\ub2e4.\\n\\n> **\uc88b\uc740 \uacbd\uacc4\uc758 \uc704\uce58\ub294 \ucc98\uc74c\ubd80\ud130 \uace0\uc815\ub418\uc5b4 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ubcc0\uacbd \uc555\ub825\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4.**\\n\\n***\\n\\n## 6. \uc678\ubd80 \uc751\ub2f5\uc774 \ubc14\ub00c\uba74 \ubc88\uc5ed\ub3c4 \ud2c0\ub9b4 \uc218 \uc788\ub2e4\\n\\n\uc55e\uc5d0\uc11c\ub294 \uc54c\ub77c\ub518\uc758 \uae30\uc5ec\uc790 \ubb38\uc790\uc5f4\uc744 `AladinContributorParser`\uac00 \ud574\uc11d\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4.\\n\\n```javascript\\n\uc564\ub514 \uc704\uc5b4 (\uc9c0\uc740\uc774), \ubc15\uc544\ub78c (\uc62e\uae34\uc774)\\n```\\n\\n\uc774 \ud30c\uc11c\ub294 `(\uc9c0\uc740\uc774)`, `(\uc62e\uae34\uc774)`\uc640 \uac19\uc740 \uc54c\ub77c\ub518\uc758 \ud45c\ud604 \uaddc\uce59\uc744 \uc54c\uace0 \uc788\ub2e4.\\n\\n\uadf8\ub7f0\ub370 \uc5ec\uae30\uc5d0\ub294 \ud55c \uac00\uc9c0 \uc804\uc81c\uac00 \uc788\ub2e4.\\n\\n**\uc54c\ub77c\ub518\uc774 \uc55e\uc73c\ub85c\ub3c4 \uc6b0\ub9ac\uac00 \uc608\uc0c1\ud55c \ud615\uc2dd\uc73c\ub85c \uac12\uc744 \ub0b4\ub824\uc900\ub2e4\ub294 \uc804\uc81c\ub2e4.**\\n\\n\ub9cc\uc57d \uc0c8\ub85c\uc6b4 \uc5ed\ud560(ex. \uc5ee\uc740\uc774)\uc774 \ucd94\uac00\ub418\uac70\ub098, \uae30\uc874\uacfc \ub2e4\ub978 \ud615\uc2dd\uc758 \ubb38\uc790\uc5f4(ex.\uc9c0\uc740\uc774=\uc564\ub514 \uc704\uc5b4, ...)\uc774 \ub0b4\ub824\uc628\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c?\\n\\nJSON \ud544\ub4dc\uac00 \uc0ac\ub77c\uc9c4 \uacbd\uc6b0\ucc98\ub7fc \uc5ed\uc9c1\ub82c\ud654 \ub2e8\uacc4\uc5d0\uc11c \ubc14\ub85c \uc2e4\ud328\ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \ub354 \uae4c\ub2e4\ub85c\uc6b4 \uacbd\uc6b0\ub294 **\ucf54\ub4dc\ub294 \uc815\uc0c1\uc801\uc73c\ub85c \uc2e4\ud589\ub418\ub294\ub370 \uacb0\uacfc\ub9cc \uc798\ubabb\ub418\ub294 \uacbd\uc6b0**\ub2e4.\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ud30c\uc11c\uac00 \uc5b4\ub5a4 \uae30\uc5ec\uc790\ub97c \uc800\uc790\ub85c \uc798\ubabb \ubd84\ub958\ud558\uac70\ub098, \uc54c \uc218 \uc5c6\ub294 \uc5ed\ud560\uc744 \uadf8\ub0e5 \ubc84\ub9b0\ub2e4\uba74 **\uc694\uccad \uc790\uccb4\ub294 \uc131\uacf5**\ud55c\ub2e4. \ubb38\uc81c\ub294 **\uc798\ubabb\ub41c \ub370\uc774\ud130\uac00 \uc815\uc0c1\uc801\uc778 \uac80\uc0c9 \uacb0\uacfc\ucc98\ub7fc \ud074\ub77c\uc774\uc5b8\ud2b8\uae4c\uc9c0 \uc804\ub2ec\ub420 \uc218 \uc788\ub2e4**\ub294 \uac83\uc774\ub2e4.\\n\\n\uc678\ubd80 \uc751\ub2f5\uc758 \ubcc0\ud654\ub97c \uc5b4\ub5bb\uac8c \ubc1c\uacac\ud560\uc9c0, \ud574\uc11d\ud560 \uc218 \uc5c6\ub294 \uac12\uc744 \uc5b4\ub5bb\uac8c \ucc98\ub9ac\ud560\uc9c0, \uc5b4\ub290 \uc218\uc900\uae4c\uc9c0 \ubc29\uc5b4\ud560\uc9c0\ub294 \ubcc4\ub3c4\uc758 \uc8fc\uc81c\ub85c \ub354 \ub2e4\ub904\ubcfc \uc218 \uc788\ub2e4.\\n\\n***\\n\\n## 7. \uc678\ubd80 API \uc5f0\ub3d9\uc740 \ubc88\uc5ed\uc774\ub2e4\\n\\n\ucc98\uc74c\uc5d0\ub294 \uc678\ubd80 API \uc5f0\ub3d9\uc744 \ub2e8\uc21c\ud788 \ub370\uc774\ud130\ub97c \ubc1b\uc544 \uc804\ub2ec\ud558\ub294 \uc77c\uc774\ub77c\uace0 \uc0dd\uac01\ud588\ub2e4.\\n\\n```javascript\\n\uc54c\ub77c\ub518 \uc751\ub2f5\\n\u2192 DTO\uc5d0 \ub2f4\ub294\ub2e4\\n\u2192 \ud544\uc694\ud55c \ud544\ub4dc\ub9cc \uace8\ub77c \ubc18\ud658\ud55c\ub2e4\\n```\\n\\n\ud558\uc9c0\ub9cc \uad6c\ud604\ud558\uba74\uc11c \uc2e4\uc81c\ub85c \ud55c \uc77c\uc740 \ub2ec\ub790\ub2e4.\\n\\n\uc54c\ub77c\ub518\uc774 \ud558\ub098\uc758 \ubb38\uc790\uc5f4\ub85c \uc81c\uacf5\ud55c \uae30\uc5ec\uc790 \uc815\ubcf4\uc5d0\uc11c \uc800\uc790\uc640 \ubc88\uc5ed\uc790\ub97c \ub098\ub234\ub2e4.\\n\\n```javascript\\n\uc564\ub514 \uc704\uc5b4 (\uc9c0\uc740\uc774), \ubc15\uc544\ub78c (\uc62e\uae34\uc774)\\n\\n\u2193\\n\\nauthors: [\\"\uc564\ub514 \uc704\uc5b4\\"]\\ntranslators: [\\"\ubc15\uc544\ub78c\\"]\\n```\\n\\n\uc54c\ub77c\ub518\uc774 \uc81c\uacf5\ud55c \ud398\uc774\uc9c0 \uc815\ubcf4\ub3c4 \uadf8\ub300\ub85c \ub178\ucd9c\ud558\uc9c0 \uc54a\uace0, \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ubc14\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 `nextPage`\ub85c \ubc14\uafe8\ub2e4.\\n\\n```javascript\\ntotalResults + startIndex + itemsPerPage\\n\\n\u2193\\n\\nnextPage\\n```\\n\\n\uc54c\ub77c\ub518\uc774 \uc81c\uacf5\ud55c \ud398\uc774\uc9c0 \uc815\ubcf4\ub3c4 \uadf8\ub300\ub85c \ub178\ucd9c\ud558\uc9c0 \uc54a\uace0, \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ubc14\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 `nextPage`\ub85c \ubc14\uafe8\ub2e4.\\n\\n```javascript\\n\uc54c\ub77c\ub518\uc758 \ud398\uc774\uc9c0 \uc815\ubcf4\\ntotalResults + startIndex + itemsPerPage\\n\\n\u2193\\n\\n\ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc0ac\uc6a9\ud560 \uac12\\nnextPage\\n```\\n\\n\uc774\ucc98\ub7fc \uc678\ubd80 API \uc5f0\ub3d9\uc5d0\uc11c\ub294 \ub2e8\uc21c\ud788 \uac12\uc744 \uc62e\uae30\ub294 \uac83\ubcf4\ub2e4, **\uc678\ubd80\uc758 \ud45c\ud604\uc744 \uc6b0\ub9ac \uc11c\ube44\uc2a4\uc5d0 \ud544\uc694\ud55c \ud615\ud0dc\ub85c \ubc14\uafb8\ub294 \uc77c**\uc774 \ub354 \uc911\uc694\ud588\ub2e4.\\n\\n\uc774 \uae00\uc5d0\uc11c \ub9d0\ud558\ub294 **\ubc88\uc5ed**\uc740 \ubc14\ub85c \uc774 \uacfc\uc815\uc744 \ub73b\ud55c\ub2e4.\\n\\n---\\n\\n[\ub9ac\ub85c\uadf8 \uc6d0\ubb38](https://www.rilog.kr/@chaekchaek/posts/23)"},{"id":"explanation-about-SQ3R","metadata":{"permalink":"/explanation-about-SQ3R","editUrl":"https://github.com/hyoyoonnam/blog/2026-03-17-SQ3R\uc774\ub780/index.md","source":"@site/blog/2026-03-17-SQ3R\uc774\ub780/index.md","title":"SQ3R\uc774\ub780","description":"SQ3R\uc740 \uae00\uc744 \uc77d\uc73c\uba74\uc11c \'\uc798 \ud559\uc2b5\ud558\uae30 \uc704\ud55c\' \ubc29\ubc95\ub860\uc774\ub2e4.","date":"2026-03-17T00:00:00.000Z","tags":[{"inline":false,"label":"SQ3R_\uc758\uc2dd\uc801\uc73c\ub85c_\uc5f0\uc2b5\ud558\uae30","permalink":"/tags/sq-3-r-\uc758\uc2dd\uc801\uc73c\ub85c-\uc5f0\uc2b5\ud558\uae30"}],"readingTime":1.26,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"explanation-about-SQ3R","title":"SQ3R\uc774\ub780","authors":"hyoyoonnam","tags":["SQ3R_\uc758\uc2dd\uc801\uc73c\ub85c_\uc5f0\uc2b5\ud558\uae30"],"status":"\ud83d\udfe9_done","topics":["[[woowa]]","[[Lv 1]]"],"started":"2026-03-17T00:00:00.000Z","deadline(or finished)":"2026-03-17T15:37:00.000Z"},"unlisted":false,"prevItem":{"title":"[BE] \uc678\ubd80 API \uc5f0\ub3d9\uc740 \uc804\ub2ec\uc774 \uc544\ub2c8\ub77c \ubc88\uc5ed\uc774\ub2e4","permalink":"/translating-external-apis"},"nextItem":{"title":"unmodifiableList\uc640 ImmutableList","permalink":"/difference-between-collections-unmodifiablelist-and-List-of-immutablelist"}},"content":"**SQ3R**\uc740 \uae00\uc744 \uc77d\uc73c\uba74\uc11c \'\uc798 \ud559\uc2b5\ud558\uae30 \uc704\ud55c\' \ubc29\ubc95\ub860\uc774\ub2e4.\\n\\n\uae00\uc744 \ub2e8\uc21c\ud788 \uc77d\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc758\uc2dd\uc801\uc73c\ub85c \uc77d\uc74c\uc73c\ub85c\uc368 \uc2a4\uc2a4\ub85c \uc9c8\ubb38\uc744 \uc0dd\uac01\ud558\uace0 \uadf8\uc5d0 \ub300\ud55c \ub2f5\uc744 \uc5bb\uc73c\ub824\ub294 \uc790\uc138\ub85c \uc784\ud55c\ub2e4.\\n\\n## \ub4e4\uc5b4\uac00\uba70\\n\\n\ub2e4\uc74c\uc740 \ucc38\uace0 \uc790\ub8cc\ub4e4\uc744 \ud1b5\ud574 SQ3R\uc774 \ubb34\uc5c7\uc774\uace0, \uc5b4\ub5bb\uac8c \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uc9c0 \uc815\ub9ac\ud55c \uac83\uc774\ub2e4.\\n\\n[\ud568\uaed8 \uc790\ub77c\uae30(\uae40\ucc3d\uc900)](https://product.kyobobook.co.kr/detail/S000001033071)\ub77c\ub294 \ucc45\uc744 \uc77d\uc73c\uba70 \uc811\ud55c \ubc29\ubc95\ub860\uc774\uace0, \ucd5c\uadfc \ub4e4\uc5b4 \uc0c8\ub85c\uc6b4 \uc9c0\uc2dd\uc744 \'\ube60\ub974\uba74\uc11c\ub3c4 \ud6a8\uacfc\uc801\uc73c\ub85c\' \uc2b5\ub4dd\ud558\ub294 \uae30\uc220\uc744 \ubc30\uc6b8 \ud544\uc694\uac00 \ub290\uaef4\uc838 \uc790\uc138\ud788 \uc54c\uc544\ubcf4\uace0 \uc801\uc6a9\ud574\ubcf4\uae30\ub85c \ud588\ub2e4.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Survey\\n\\n\uc544\uc9c1 \uae00\uc744 \uc77d\uc9c0 \ub9c8\ub77c. \uae00\uc758 \uad6c\uc131(\ubaa9\ucc28, \uc81c\ubaa9, \ubd80\uc81c\ubaa9, ...)\uc744 \ubcf4\uba70 \uc804\uccb4\ub97c \ud30c\uc545\ud558\ub77c.\\n\\n## Question\\n\\n\'S\' \ub2e8\uacc4\uc5d0\uc11c \uc774\ud574/\uc608\uce21/\ud30c\uc545\ub418\uc9c0 \uc54a\uc740 \uae00 \uc694\uc18c\uc5d0 \ub300\ud55c \uc9c8\ubb38\uc744 \uc791\uc131\ud558\ub77c.\\n\\nex. \'\ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\uc758 \ub2ec\uc778\' \ucc55\ud130\uc5d0\uc11c\ub294 \ubb34\uc2a8 \uc774\uc57c\uae30\ub97c \ub2e4\ub8f0\uae4c? \ub2e8\uc21c\ud788 \ub2ec\uc778 \uc790\ub791\ub9cc \ud560\uae4c? \uc544\ub2c8\uba74 \ub2ec\uc778\uc758 \ub178\ud558\uc6b0\ub97c \uacf5\uac1c\ud560\uae4c? \ub0b4\uac00 \ub2ec\uc778\ucc98\ub7fc \ub418\ub824\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud560\uae4c? ...\\n\\n:::note\\n\ub9cc\ub4e0 \uc9c8\ubb38\ub4e4\uc744 \ud574\uacb0\ud560 \ubaa9\uc801\uc73c\ub85c \uae00\uc744 \uc77d\ub294\ub2e4\uba74, \uc5b4\ub290 \ubd80\ubd84\uc5d0 \uc9d1\uc911\ud574\uc11c \uc77d\uc5b4\uc57c \ud560 \uc9c0\uac00 \ubcf4\uc778\ub2e4.\\n:::\\n\\n## Read\\n\\n\'Q\'\ub97c \ud1b5\ud574 \ubc1c\uacac\ud55c \'\ub0b4\uac00 \uc9d1\uc911\ud560 \ubd80\ubd84\'\uc5d0 \ud615\uad11\ud39c\uc744 \uce58\uac70\ub098 \uba54\ubaa8\ub97c \ub0a8\uae30\uba70 \uc77d\uc5b4\ub77c. \ub0b4 \uc2dc\uac01\uc774 \ubb3c\ub9ac\uc801\uc73c\ub85c\ub3c4 \uadf8 \uacf3\uc5d0 \uc9d1\uc911\ub418\uac8c\ub054 \ud558\ub77c.\\n\\n## Recite\\n\\n\'Q\'\ub97c \ud574\uc18c\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc5d0 \uc9d1\uc911\ud558\uc5ec \uae00\uc744 \uc77d\uc5c8\ub2e4\uba74, (\uc798 \uc77d\uc5c8\ub2e4\uba74 \ud574\uc18c\ub418\uc5c8\uc744\ud14c\ub2c8) \uc2a4\uc2a4\ub85c \uc9c8\ubb38\uc5d0 \ub300\ud574 \uc18c\ub9ac\ub0b4\uc5b4 \ub2f5\ubcc0\ud558\ub77c.\\n\\n\uc774\ub54c \ub2f5\ubcc0\ud558\uae30 \uc5b4\ub824\uc6e0\ub358 \uc9c8\ubb38\uc744 \uae30\ub85d\ud558\uace0, \ub2e4\uc74c \'R\'\uc5d0\uc11c \ud65c\uc6a9\ud558\ub77c.\\n\\n## Review\\n\\n\'Q\'\uc5d0\uc11c \uc791\uc131\ud588\ub358 \uc9c8\ubb38\ub4e4\uc744 \ud1b5\ud574 \ubcf5\uc2b5\ud558\ub77c.\\n\\n\uc774\ub54c \uc9c8\ubb38 \ub9ac\uc2a4\ud2b8\ub294 \ub0b4\uac00 \uc77d\uc740 \uae00\ub85c\ubd80\ud130 \ubb3c\ub9ac\uc801\uc73c\ub85c \ubd84\ub9ac\ud558\ub77c(\ud034\uc988\uc6a9 \uce74\ub4dc\ub97c \uc791\uc131\ud55c\ub2e4\uac70\ub098).\\n\\n\uc9c8\ubb38\uacfc \uae00\uc774 \ud568\uaed8 \uc788\uc73c\uba74, \uc790\uc5f0\uc2a4\ub7fd\uac8c \uae00\ub85c\ubd80\ud130 clue\ub97c \uc5bb\uac8c \ub418\ub294\ub370 \'\uc790\uc2e0\uc774 \uc774\ud574\ud588\ub2e4\ub294 \ucc29\uac01\'\uc744 \ud558\uae30 \uc27d\uc0c1\uc774\ub2e4.\\n\\n\uc628\uc804\ud788 \ubcf8\uc778\uc758 \uae30\uc5b5 \uc18d\uc5d0\uc11c \ub044\uc9d1\uc5b4\ub0b4\ub294, \uadf8 \ud798\ub4e0 \uacfc\uc815\uc744 \uacaa\uc5b4\uc57c \ub41c\ub2e4. \uc2e4\uc81c \uc2dc\ud5d8\uc744 \ubcfc \ub54c\ub3c4 \ucc45\uc744 \ucc38\uace0\ud560 \uc218\ub294 \uc5c6\uc9c0 \uc54a\uc740\uac00!!(\uc624\ud508\ubd81 \uc2dc\ud5d8\ub3c4 \uc788\uc9c0\ub9cc...)\\n\\n## References\\n- [\ud568\uaed8 \uc790\ub77c\uae30(\uae40\ucc3d\uc900)](https://product.kyobobook.co.kr/detail/S000001033071) - \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4 \ubc30\uc6b0\uae30\uc758 \ub2ec\uc778\\n- [SQ3R - Harvard Univ.](https://academicresourcecenter.harvard.edu/2024/03/27/sq3r/)"},{"id":"difference-between-collections-unmodifiablelist-and-List-of-immutablelist","metadata":{"permalink":"/difference-between-collections-unmodifiablelist-and-List-of-immutablelist","editUrl":"https://github.com/hyoyoonnam/blog/2026-03-13-unmodifiable-list\uc640-immutable-list/index.md","source":"@site/blog/2026-03-13-unmodifiable-list\uc640-immutable-list/index.md","title":"unmodifiableList\uc640 ImmutableList","description":"1. \'\uc218\uc815\uc774 \ubd88\uac00\ub2a5\ud55c\' \uceec\ub809\uc158\uacfc \'\ubd88\ubcc0\' \uceec\ub809\uc158\uc758 \ucc28\uc774\ub97c view\uc640 capture\ub85c \uc124\uba85\ud560 \uc218 \uc788\uc5b4\uc694.","date":"2026-03-13T00:00:00.000Z","tags":[{"inline":false,"label":"Java","permalink":"/tags/java"}],"readingTime":2.56,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"difference-between-collections-unmodifiablelist-and-List-of-immutablelist","title":"unmodifiableList\uc640 ImmutableList","authors":"hyoyoonnam","tags":["Java"],"status":"\ud83d\udfe9_done","topics":["[[woowa]]","[[Lv 1]]","[[Java]]"],"started":"2026-03-13T00:00:00.000Z","deadline(or finished)":"2026-03-16T22:00:00.000Z"},"unlisted":false,"prevItem":{"title":"SQ3R\uc774\ub780","permalink":"/explanation-about-SQ3R"},"nextItem":{"title":"message \uc804\uc1a1\uacfc \uba54\uc11c\ub4dc \ud638\ucd9c\uc740 \ub2e4\ub974\ub2e4.","permalink":"/difference-between-message-sending-and-method-calling"}},"content":":::note[\uc774 \uae00\uc744 \uc77d\uc73c\uba74]\\n\\n1. \'\uc218\uc815\uc774 \ubd88\uac00\ub2a5\ud55c\' \uceec\ub809\uc158\uacfc \'\ubd88\ubcc0\' \uceec\ub809\uc158\uc758 \ucc28\uc774\ub97c view\uc640 capture\ub85c \uc124\uba85\ud560 \uc218 \uc788\uc5b4\uc694.\\n\\n2. \ub2e4\uc74c \ub450 \ucf54\ub4dc\ub85c \uc0dd\uc131\ud55c \uceec\ub809\uc158 \uac1d\uccb4\uc758 \ucc28\uc774\ub97c \uc54c \uc218 \uc788\uc5b4\uc694.\\n    - `Collections.unmodifiableList()`\\n    - `List.of()` \ub610\ub294 `List.copyOf()`\\n\\n:::\\n\\n\x3c!-- truncate --\x3e\\n\\n# 1. \uacf5\ud1b5\uc810: \uc218\uc815 \uba54\uc11c\ub4dc\ub97c \ud638\ucd9c\ud558\uba74 \uc608\uc678\uac00 \ubc1c\uc0dd\ud55c\ub2e4\\n\\n\uc218\uc815 \uba54\uc11c\ub4dc\ub97c \ud638\ucd9c\ud558\uba74 `UnsupportedOperationException` \uc608\uc678\uac00 \ubc1c\uc0dd\ud55c\ub2e4.\\n\\n<iframe\\n  frameBorder=\\"0\\"\\n  src=\\"https://onecompiler.com/java/44gg6wqev?codeEditors=true&hideNew=true&hideNewFile=true\\"\\n  width=\\"100%\\"\\n  height=\\"600px\\"\\n  title=\\"Unmodifiable vs Immutable List Java Example\\">\\n</iframe>\\n\\n# 2. \ucc28\uc774\uc810\\n\\n## 2.1. \uad6c\ud604\uccb4 \ud074\ub798\uc2a4\uac00 \ub2e4\ub974\ub2e4\\n\\n<iframe\\n  frameBorder=\\"0\\"\\n  src=\\"https://onecompiler.com/java/44gh4m5rq?codeEditors=true&hideNew=true&hideNewFile=true\\"\\n  width=\\"100%\\"\\n  height=\\"600px\\"\\n  title=\\"Unmodifiable vs Immutable List Java Example\\">\\n</iframe>\\n\\n## 2.2. \uc6d0\ubcf8 \uceec\ub809\uc158\uacfc\uc758 \uad00\uacc4\uc131\uc774 \ub2e4\ub974\ub2e4\\n\\n### UnmodifiableList\\n\\n`UnmodifiableRandomAccessList` \uad6c\ud604\uccb4(\uc774\ud558 `UnmodifiableList`)\ub294 \uc6d0\ubcf8 \uceec\ub809\uc158\uc5d0 \ub300\ud55c **view**\uc774\ub2e4.\\n\\n\ub2e4\uc74c\ucc98\ub7fc \uc6d0\ubcf8 \uceec\ub809\uc158\uc778 `list`\ub97c \ud544\ub4dc\ub85c \uac00\uc9c0\uace0, \uc678\ubd80\uc5d0\uc11c \uceec\ub809\uc158 \uba54\uc11c\ub4dc\ub97c \ud638\ucd9c\ud558\uba74 \uadf8\ub300\ub85c `list.method()`\ub97c \ub300\uc2e0 \ud638\ucd9c\ud558\uc5ec \ub9ac\ud134\ud558\ub294 \ud504\ub85d\uc2dc\uc5d0 \ubd88\uacfc\ud558\ub2e4.\\n\\n\ub530\ub77c\uc11c, \uc6d0\ubcf8 \uceec\ub809\uc158\uc778 list\uc758 \ucc38\uc870\ub97c `x001`, view(\ub610\ub294 \ud504\ub85d\uc2dc)\uc778 UnmodifiableList\uc758 \ucc38\uc870\ub97c `x002`\ub77c\uace0 \ud55c\ub2e4\uba74 `x002.add()`\ub294 \ubd88\uac00\ub2a5\ud558\uace0 `x001.add()`\ub294 \uac00\ub2a5\ud558\ub2e4.\\n\\n\ub610\ud55c `x001`\uc5d0 \ubcc0\ud654\uac00 \uc0dd\uae30\uba74, \uc774\ub97c \ud544\ub4dc\ub85c \uac00\uc9c0\ub294 `x002`\uc5d0\ub3c4 \ubc18\uc601\ub41c\ub2e4.\\n\\n```java\\nstatic class UnmodifiableList<E> extends UnmodifiableCollection<E>\\n                              implements List<E> {\\n    final List<? extends E> list;\\n\\n    UnmodifiableList(List<? extends E> list) {\\n        super(list);\\n        this.list = list;\\n    }\\n\\n    ...\\n\\n    public E get(int index) {return list.get(index);}\\n\\n    public void add(int index, E element) {\\n        throw new UnsupportedOperationException();\\n    }\\n    ...\\n}\\n```\\n\\n<br></br>\\n\\n\ub2e4\uc74c \uc608\uc2dc\ub97c \ubcf4\uc790.\\n\\n<iframe\\n  frameBorder=\\"0\\"\\n  src=\\"https://onecompiler.com/java/44gh57eya?codeEditors=true&hideNew=true&hideNewFile=true\\"\\n  width=\\"100%\\"\\n  height=\\"600px\\"\\n  title=\\"Unmodifiable vs Immutable List Java Example\\">\\n</iframe>\\n\\n### ImmutableList\\n\\n\uce74\ud53c\ub97c \ud55c \uc21c\uac04\uc758 \uc6d0\ubcf8 \uceec\ub809\uc158\uc744 capture\ud55c \ub9ac\uc2a4\ud2b8\ub2e4. \uc989, \uc6d0\ubcf8 \ub9ac\uc2a4\ud2b8\ub85c\ubd80\ud130 \ub3c5\ub9bd\uc801\uc774\ub2e4.\\n\\n```java\\n// List.java\\n...\\nstatic <E> List<E> copyOf(Collection<? extends E> coll) {\\n    return ImmutableCollections.listCopy(coll);\\n}\\n...\\n```\\n\\n```java\\n// ImmutableCollections.java\\n...\\nstatic <E> List<E> listCopy(Collection<? extends E> coll) {\\n    ...\\n    } else {\\n        // \uacb0\uad6d \uc804\uccb4\ub97c \ubcf5\uc0ac\ud574\uc11c \ub118\uae34\ub2e4 = \uc6d0\ubcf8\uacfc \ub3c5\ub9bd\ub41c \uc0c8\ub85c\uc6b4 \uceec\ub809\uc158\\n        return (List<E>)List.of(coll.toArray());\\n    }\\n}\\n...\\n```\\n\\n# 2. List.copyOf()\uc5d0 \ubd88\ubcc0 \uceec\ub809\uc158\uc744 \uc804\ub2ec\ud558\uba74, \ubcf5\uc0ac\ub97c \uc218\ud589\ud558\uc9c0 \uc54a\uace0 \uadf8\ub300\ub85c \ubc18\ud658\ud55c\ub2e4\\n\\n\uc704\uc5d0\uc11c\ub294 \ubcf5\uc7a1\ud558\ub2e4\uace0 \ud310\ub2e8\ud574 \uc124\uba85\ud558\uc9c0 \uc54a\uc740 \ubd80\ubd84\uc774 \uc788\ub2e4. \uc77c\ub2e8 `ImmutableCollections.listCopy()`\uc758 \uba54\uc11c\ub4dc \ubc14\ub514 \uc804\uccb4\ub97c \ucca8\ubd80\ud55c\ub2e4. \uc5ec\uae30\uc11c \uccab \ubc88\uc9f8 `if` \ubd84\uae30\ub97c \ubcf4\uc790.\\n\\n```java\\nstatic <E> List<E> listCopy(Collection<? extends E> coll) {\\n    // List12\uc640 ListN\uc740 \ub458 \ub2e4 AbstractImmutableList\uc758 \uc790\uc2dd\uc774\ub2e4. \uc989, \ubd88\ubcc0 \ub9ac\uc2a4\ud2b8\ub2e4.\\n    // \uadf8\ub807\ub2e4. List.copyOf()\ub294 \ubd88\ubcc0 \ub9ac\uc2a4\ud2b8\uac00 \uc778\uc790\ub85c \uc624\uba74 \uc544\ubb34 \uc791\uc5c5\ub3c4 \uc218\ud589\ud558\uc9c0 \uc54a\uace0, \uc778\uc790\ub85c \ub4e4\uc5b4\uc628 \uceec\ub809\uc158\uc744 \uadf8\ub300\ub85c \ub9ac\ud134\ud55c\ub2e4.\\n    if (coll instanceof List12 || (coll instanceof ListN<?> c && !c.allowNulls)) {\\n        return (List<E>)coll;\\n    // \uc774 \ubc11\uc740 \ubb34\uc2dc\\n    } else if (coll.isEmpty()) {\\n        return List.of();\\n    } else {\\n        return (List<E>)List.of(coll.toArray());\\n    }\\n}\\n```\\n\\n<br></br>\\n\\n\uc0ac\uc2e4 \uad6c\ud604\uc744 \uc9c1\uc811 \ubcf4\uc9c0 \uc54a\ub354\ub77c\ub3c4, Javadoc\uc758 Implementation Note\ub97c \ud1b5\ud574 \ud655\uc778\ud560 \uc218 \uc788\ub2e4.\\n\\n:::note[Implementation Note:]\\n\\nIf the given Collection is an unmodifiable List, calling copyOf will generally not create a copy.\\n\\n:::\\n\\n<br></br>\\n\\n\ub2e4\uc74c \uc608\uc2dc\ub97c \ubcf4\uc790. `List.copyOf(\ubd88\ubcc0\ub9ac\uc2a4\ud2b8)`\uc640 \uc6d0\ubcf8\uc758 \ucc38\uc870\uac00 \ub3d9\uc77c\ud55c \uac83\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4.\\n\\n<iframe\\n  frameBorder=\\"0\\"\\n  src=\\"https://onecompiler.com/embed/java/44gg6962y?codeEditors=true&hideNew=true&hideNewFile=true\\"\\n  width=\\"100%\\"\\n  height=\\"500px\\">\\n</iframe>\\n\\n\ub2e4\uc74c \uc608\uc2dc\uc5d0\uc11c\ub294 `List.copyOf(\ubd88\ubcc0\ub9ac\uc2a4\ud2b8)`\uac00 \uc544\ubb34 \uac83\ub3c4 \uc218\ud589\ud558\uc9c0 \uc54a\uc74c\uc744 \uc218\uce58\uc801\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \ubc88 \uba54\uc11c\ub4dc\ub97c \ud638\ucd9c\ud574\ub3c4 \ubcf5\uc0ac\uac00 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc73c\ubbc0\ub85c, 0ms\uac00 \uc18c\uc694\ub41c\ub2e4.\\n\\n<iframe\\n  frameBorder=\\"0\\"\\n  src=\\"https://onecompiler.com/embed/java/44gh5xgjx?codeEditors=true&hideNew=true&hideNewFile=true\\"\\n  width=\\"100%\\"\\n  height=\\"500px\\">\\n</iframe>\\n\\n## References"},{"id":"difference-between-message-sending-and-method-calling","metadata":{"permalink":"/difference-between-message-sending-and-method-calling","editUrl":"https://github.com/hyoyoonnam/blog/2026-01-18-message\uc640-operation\uc740-\ub2e4\ub974\ub2e4/index.md","source":"@site/blog/2026-01-18-message\uc640-operation\uc740-\ub2e4\ub974\ub2e4/index.md","title":"message \uc804\uc1a1\uacfc \uba54\uc11c\ub4dc \ud638\ucd9c\uc740 \ub2e4\ub974\ub2e4.","description":"\uc6b0\ub9ac\ub294 \ud754\ud788 \'\uba54\uc11c\ub4dc\ub97c \ud638\ucd9c\ud55c\ub2e4\'\ub294 \ud45c\ud604\uc744 \uc4f4\ub2e4. \ud558\uc9c0\ub9cc \uac1d\uccb4\uc9c0\ud5a5\uc801\uc778 \uad00\uc810\uc5d0\uc11c \uc5c4\ubc00\ud788 \ud558\uc790\uba74 \'\uba54\uc2dc\uc9c0\ub97c \uc804\uc1a1\ud55c\ub2e4\'\ub294 \ud45c\ud604\uc774 \ub354 \uc801\uc808\ud558\ub2e4.","date":"2026-01-18T00:00:00.000Z","tags":[{"inline":false,"label":"\uac1d\uccb4\uc9c0\ud5a5","permalink":"/tags/object-oriented","description":"\uac1d\uccb4\uc9c0\ud5a5 \ud504\ub85c\uadf8\ub798\ubc0d\uc5d0 \ub300\ud55c \uc774\uc57c\uae30"}],"readingTime":1.48,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"difference-between-message-sending-and-method-calling","title":"message \uc804\uc1a1\uacfc \uba54\uc11c\ub4dc \ud638\ucd9c\uc740 \ub2e4\ub974\ub2e4.","authors":"hyoyoonnam","tags":["\uac1d\uccb4\uc9c0\ud5a5"],"started":"2026-01-18T00:00:00.000Z","deadline(or finished)":null},"unlisted":false,"prevItem":{"title":"unmodifiableList\uc640 ImmutableList","permalink":"/difference-between-collections-unmodifiablelist-and-List-of-immutablelist"},"nextItem":{"title":"2025 \uc778\ud504\ub7f0 \uc5f0\ub9d0 \uc5b4\uc6cc\ub4dc \'\ub2f5\ubcc0\uc655\' \uc218\uc0c1!","permalink":"/inflearn-2025-end-of-year-awards"}},"content":"\uc6b0\ub9ac\ub294 \ud754\ud788 \'*\uba54\uc11c\ub4dc\ub97c \ud638\ucd9c\ud55c\ub2e4*\'\ub294 \ud45c\ud604\uc744 \uc4f4\ub2e4. \ud558\uc9c0\ub9cc \uac1d\uccb4\uc9c0\ud5a5\uc801\uc778 \uad00\uc810\uc5d0\uc11c \uc5c4\ubc00\ud788 \ud558\uc790\uba74 \'*\uba54\uc2dc\uc9c0\ub97c \uc804\uc1a1\ud55c\ub2e4*\'\ub294 \ud45c\ud604\uc774 \ub354 \uc801\uc808\ud558\ub2e4.\\n\\n\ub450 \ud45c\ud604\uc774 \uac19\ub2e4\ub294 \uc624\ud574\ub294 \uc815\uc801 \ud0c0\uc785 \uc5b8\uc5b4\uc778 Java\ub85c \ud559\uc2b5\ud588\uae30 \ub54c\ubb38\uc778\ub370, \uc774\ubc88 \uae30\ud68c\uc5d0 \ub3d9\uc801 \ud0c0\uc785 \uc5b8\uc5b4\uc778 Javascript\uc640\uc758 \ube44\uad50\ub97c \ud1b5\ud574 \uadf8 \ucc28\uc774\ub97c \ud655\uc778\ud558\uc790.\\n\\n\x3c!-- truncate --\x3e\\n\\n---\\n\\n## 0. \uc0ac\uc804 \uc9c0\uc2dd\uacfc \uc6a9\uc5b4\\n\\n```java\\n// \ub9ac\ud134 \ud0c0\uc785, \uba54\uc11c\ub4dc\uba85, \ud30c\ub77c\ubbf8\ud130 \ub4f1\uc740 \'\uc120\uc5b8\'\uc774\ub2e4. \'\uba54\uc11c\ub4dc \uc2dc\uadf8\ub2c8\ucc98\', \'\uc778\ud130\ud398\uc774\uc2a4\', \'\uc624\ud37c\ub808\uc774\uc158\'\uc774\ub77c\uace0\ub3c4 \ud55c\ub2e4.\\npublic void sayHello(String name) {\\n\\t// \uba54\uc11c\ub4dc \ubc14\ub514\ub294 \'\uad6c\ud604\'\uc774\ub2e4. \uadf8\ub0e5 \'\uba54\uc11c\ub4dc\'\ub77c\uace0\ub3c4 \ud55c\ub2e4.\\n\\tSystem.out.println(\\"\uc548\ub155 \\" + name + \\"!\\");\\n}\\n```\\n\\n## 1. Java, \uc815\uc801 \ud0c0\uc785 \uc5b8\uc5b4\\n\\nJava\ub294 \uc815\uc801 \ud0c0\uc785 \uc5b8\uc5b4\uc774\uae30 \ub54c\ubb38\uc5d0 compile-time\uc5d0 \ucef4\ud30c\uc77c\ub7ec\uac00 \uadf8 \ud0c0\uc785\uc744 \uccb4\ud06c\ud55c\ub2e4.\\n\ub530\ub77c\uc11c sender\uac00 \uba54\uc2dc\uc9c0\ub97c \uc804\uc1a1\ud558\ub824\uace0 \ud560 \ub54c, receiver \uac1d\uccb4\uac00 \ud574\ub2f9 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uac00\uc9c0\uace0 \uc788\uc9c0 \uc54a\ub2e4\uba74 \uc2e4\ud589(\uba54\uc11c\ub4dc \uc804\uc1a1)\uc870\ucc28 \ud560 \uc218 \uc5c6\ub2e4.\\n\uc989, compile error\uac00 \ubc1c\uc0dd\ud55c\ub2e4.\\n\\n\uc774\ub85c \uc778\ud574 Java\uc640 \uac19\uc740 \uc815\uc801 \ud0c0\uc785 \uc5b8\uc5b4\uc5d0\uc11c\ub294 \'\uba54\uc2dc\uc9c0 \uc804\uc1a1\'\uacfc \'\uba54\uc11c\ub4dc \ud638\ucd9c\'\uc774 \uac19\ub2e4\ub294 \ucc29\uac01\uc744 \ud558\uae30 \uc27d\ub2e4.\\n\\n<iframe\\n frameBorder=\\"0\\"\\n src=\\"https://onecompiler.com/embed/java/44axz2pcq?codeEditors=true&hideNew=true&hideNewFile=true\\" \\n width=\\"100%\\"\\n height=\\"500px\\">\\n</iframe>\\n\\n## 2. Javascript, \ub3d9\uc801 \ud0c0\uc785 \uc5b8\uc5b4\\n\\n\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\ub294 \ub3d9\uc801 \ud0c0\uc785 \uc5b8\uc5b4\uc774\uae30 \ub54c\ubb38\uc5d0 \ucef4\ud30c\uc77c\ub7ec\uac00 `sayHello()` \uba54\uc11c\ub4dc\uc758 \uc874\uc7ac \uc5ec\ubd80\ub97c \ucef4\ud30c\uc77c \ud0c0\uc784\uc5d0 \uccb4\ud06c\ud558\uc9c0 \uc54a\ub294\ub2e4.\\n\ub530\ub77c\uc11c \ud574\ub2f9 \uba54\uc11c\ub4dc\ub97c \uac00\uc9c0\uc9c0 \uc54a\ub294 `rock` \uac1d\uccb4\uc5d0\uac8c\ub3c4 \uba54\uc2dc\uc9c0\ub97c \uc804\uc1a1\ud560 \uc218\ub294 \uc788\ub2e4(\ubb3c\ub860 \uba54\uc11c\ub4dc\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub370 \uc2e4\ud589\ud55c\ub2e4\uba74 \ub7f0\ud0c0\uc784\uc5d0 \uc5d0\ub7ec\uac00 \ubc1c\uc0dd\ud55c\ub2e4).\\n\\n<iframe\\n frameBorder=\\"0\\"\\n src=\\"https://onecompiler.com/embed/java/44axefzbe?codeEditors=true&hideNew=true&hideNewFile=true\\" \\n width=\\"100%\\"\\n height=\\"500px\\">\\n</iframe>\\n\\n### \uc2ec\uc9c0\uc5b4\ub294 \uc804\uc1a1\ub41c \uba54\uc2dc\uc9c0\uc5d0 \ud574\ub2f9\ud558\ub294 \uc778\ud130\ud398\uc774\uc2a4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc5d0\ub7ec\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4.\\n\\n\ub2e4\uc74c \ucf54\ub4dc\ub294 \'\uba54\uc11c\ub4dc \ud638\ucd9c\'\uc774\ub77c\ub294 \uad00\uc810\uc5d0\uc11c\ub294 \uc124\uba85\uc774 \ubd88\uac00\ud558\ub2e4. `rock` \uac1d\uccb4 \uc548\uc5d0\ub294 `sayHello()`\ub77c\ub294 \ucf54\ub4dc\uac00 \ubb3c\ub9ac\uc801\uc73c\ub85c \uc874\uc7ac\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4.\\n\\n\ub300\uc2e0 \'\uba54\uc2dc\uc9c0 \uc804\uc1a1\'\uc774\ub77c\ub294 \uad00\uc810\uc5d0\uc11c \uc124\uba85\uc774 \uac00\ub2a5\ud55c\ub370, sender\ub294 \uadf8\uc800 `sayHello`\ub77c\ub294 \uc774\ub984\uc758 \uba54\uc2dc\uc9c0\ub97c \uc804\uc1a1\ud588\uc744 \ubfd0\uc774\uace0, receiver\uac00 \uadf8 \uba54\uc2dc\uc9c0\ub97c \ub09a\uc544\ucc44\uc11c \ub3d9\uc801\uc73c\ub85c \uc751\ub2f5\ud55c \uc0c1\ud669\uc774\ub2e4.\\n\\n<iframe\\n frameBorder=\\"0\\"\\n src=\\"https://onecompiler.com/embed/java/44ay38vb2?codeEditors=true&hideNew=true&hideNewFile=true\\" \\n width=\\"100%\\"\\n height=\\"500px\\">\\n</iframe>\\n\\n## References\\n\uc624\ube0c\uc81d\ud2b8(\uc870\uc601\ud638, p.49)"},{"id":"inflearn-2025-end-of-year-awards","metadata":{"permalink":"/inflearn-2025-end-of-year-awards","editUrl":"https://github.com/hyoyoonnam/blog/2025-12-24-\uc778\ud504\ub7f0-\uc5f0\ub9d0-\uc5b4\uc6cc\ub4dc-\uc218\uc0c1/index.md","source":"@site/blog/2025-12-24-\uc778\ud504\ub7f0-\uc5f0\ub9d0-\uc5b4\uc6cc\ub4dc-\uc218\uc0c1/index.md","title":"2025 \uc778\ud504\ub7f0 \uc5f0\ub9d0 \uc5b4\uc6cc\ub4dc \'\ub2f5\ubcc0\uc655\' \uc218\uc0c1!","description":"my-award","date":"2025-12-24T00:00:00.000Z","tags":[{"inline":false,"label":"Life","permalink":"/tags/life","description":"rudevico\uc758 \uc804\ubc18\uc801\uc778 \uc77c\uc0c1 \uc774\uc57c\uae30"}],"readingTime":2.84,"hasTruncateMarker":true,"authors":[{"name":"HyoYoonNam","title":"Software Engineer","url":"https://linkedin.com/in/hyoyoonnam","page":null,"description":"Java, Spring\uc744 \uba54\uc778\uc73c\ub85c \ud558\ub294 \ucde8\uc900\uc0dd\uc785\ub2c8\ub2e4.","socials":{"linkedin":"https://www.linkedin.com/in/hyoyoonnam/","github":"https://github.com/hyoyoonnam","email":"mailto:dev.rudevico@gmail.com"},"imageURL":"https://github.com/hyoyoonnam.png","key":"hyoyoonnam"}],"frontMatter":{"slug":"inflearn-2025-end-of-year-awards","title":"2025 \uc778\ud504\ub7f0 \uc5f0\ub9d0 \uc5b4\uc6cc\ub4dc \'\ub2f5\ubcc0\uc655\' \uc218\uc0c1!","authors":"hyoyoonnam","tags":["life"],"image":"./my-award.png","started":"2025-12-24T00:00:00.000Z","deadline(or finished)":"2025-12-24T15:00:00.000Z","status":"\ud83d\udfe9_done"},"unlisted":false,"prevItem":{"title":"message \uc804\uc1a1\uacfc \uba54\uc11c\ub4dc \ud638\ucd9c\uc740 \ub2e4\ub974\ub2e4.","permalink":"/difference-between-message-sending-and-method-calling"}},"content":"![my-award](./my-award.png)\\n\\n\uc778\ud504\ub7f0 2025 \uc5f0\ub9d0 \uc5b4\uc6cc\ub4dc\uc5d0\uc11c \'\ub2f5\ubcc0\uc655\'\uc5d0 \uc120\uc815\ub418\uc5c8\ub2e4!\\n\\n![jerry](https://media1.tenor.com/m/wOlC5m7NikkAAAAd/%EC%A0%9C%EB%A6%AC%EC%9D%B8%EC%82%AC-%EC%A1%B4%EC%A4%91.gif)\\n\\n\ub124, \uc81c\uac00 \uc218\uc0c1\uc790 \ub9de\uc2b5\ub2c8\ub2e4. \uc774 \uc0c1\uc740 \uc800\ub9cc \ubc1b\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ub178\ub825\ud574 \uc900 \uc81c\uc791\uc9c4\uacfc (... \uc911\ub7b5)\\n\\n\x3c!-- truncate --\x3e\\n\\n---\\n\\n## \uc120\ubb3c\uc744 \ubc1b\uae30\uae4c\uc9c0\\n![inflearn-awards-2025](./inflearn-awards-2025.png)\\n\uc0ac\uc2e4 \uc5f0\ub9d0 \uc5b4\uc6cc\ub4dc\uac00 \uc874\uc7ac\ud55c\ub2e4\ub294 \uac83\ub3c4 \ubab0\ub790\uace0, \uc120\ubb3c \ubc30\uc1a1\uc744 \uc704\ud55c \uc8fc\uc18c\ub97c \uc785\ub825\ud574\ub2ec\ub77c\ub294 \uba54\uc77c\uc870\ucc28\ub3c4 \ub298 \uc624\ub294 \uc778\ud504\ub7f0 \uad11\uace0 \uba54\uc77c\uc778 \uc904 \uc54c\uace0 \uc9c0\ub098\ucce4\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uaf3c\uaf3c\ud55c \uc778\ud504\ub7f0 \uce21\uc5d0\uc11c\ub294 \ubb38\uc790\ub85c \ud55c\ubc88 \ub354 \uc548\ub0b4\ud574\uc92c\uace0, \ub355\ubd84\uc5d0 \ubc30\uc1a1\uc9c0\ub97c \ubb34\uc0ac\ud788 \uc785\ub825\ud560 \uc218 \uc788\uc5c8\ub2e4.\\n\\n![present-1](./present-1.jpg)\\n![present-2](./present-2.jpg)\\n\uadf8\ub807\uac8c \ub3c4\ucc29\ud55c \uc120\ubb3c\uc740 \uc640\uc778\uacfc \uce58\uc988! \uc778\ud504\ub7f0\uc744 \ud1b5\ud574 \uc5f4\uc2ec\ud788 \uacf5\ubd80\ud558\ub294 \uc5b4\ub978\uc774\ub4e4\uc744 \uc704\ud55c \ub9de\ucda4 \uc120\ubb3c\uc774\ub2e4.\\n\\n![present-3](./present-3.jpg)\\n\\n## \ub098\ub294 \uc65c \ub2f5\ubcc0\uc744 \ub2ec\uae30 \uc2dc\uc791\ud588\uc744\uae4c?\\n\uacb0\ub860\ubd80\ud130 \ub9d0\ud558\uc790\uba74 \ub0a8\ub4e4\uc758 \uc9c8\ubb38\uc5d0 \ub2f5\ubcc0\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ub0b4 \uc2a4\uc2a4\ub85c \uc5bb\ub294 \ubc30\uc6c0\uc774 \ub9ce\uc558\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub9ac\uace0 \ub2f5\ubcc0\uc744 \ub2e4\ub294 \uac83 \uc790\uccb4\uac00 \uc7ac\ubc0c\ub2e4.\\n\\n\ub2e8\uc21c\ud788 \ub0b4\uac00 \uc544\ub294 \uac83\uacfc \ub0a8\uc774 \uc54c\ub3c4\ub85d \ub3d5\ub294 \uac83 \uac04\uc5d0\ub294 \uaf64\ub098 \ud070 \uac04\uadf9\uc774 \uc874\uc7ac\ud55c\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4. \uc544\ub2c8, \uc2ec\uc9c0\uc5b4\ub294 \'\ub098 \ud63c\uc790 \uc544\ub294 \uac83\'\uc740 \uc9c4\uc815\ud55c \uc54e\uc774 \uc544\ub2d0 \uc218\ub3c4 \uc788\uaca0\ub2e4.\\n\\n\uadf8\ub3c4 \uadf8\ub7f4 \uac83\uc774 \ub098 \ub610\ud55c \ub2f5\ubcc0\uc744 \ub2e4\ub294 \uacfc\uc815\uc5d0\uc11c \\"\uc544, \uc774 \uc9c8\ubb38\uc5d0 \ub300\ud55c \ub2f5\uc774 \ubb54\uc9c0 \ub0b4\uac00 \uc798 \uc54c\uc9c0! \uc54c\ub824\uc918\uc57c\uaca0\ub2e4!\\"\ub77c\ub294 \uc0dd\uac01\uc5d0 \uae00\uc744 \uc791\uc131\ud558\ub2e4\uac00\ub3c4,\\n\\"\uc5b4, \ub098\ub294 \uc774 \ubd80\ubd84\uc744 \ub2f9\uc5f0\ud558\uac8c \uc0dd\uac01\ud558\uae34 \ud588\ub294\ub370, \uc774 \uc0ac\ub78c\ud55c\ud14c\ub294 \ubb50\ub77c\uace0 \uc124\uba85\ud574\uc57c \ub418\ub098?\\"\ub77c\uac70\ub098, \\"\ub0b4\uac00 \uc544\ub294 \uc9c0\uc2dd\uc774 \uc9c4\uc9dc fact\uac00 \ub9de\ub098? \uacf5\uc2dd \ub808\ud37c\ub7f0\uc2a4\uac00 \uc788\ub098?\\"\ub77c\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5b4 \uba48\uce6b\ud55c \uc801\uc774 \ub9ce\ub2e4.\\n\\n\ub0a8\uc5d0\uac8c \uc54c\ub824\uc900\ub2e4\ub294 \uac83\uc758 \ubb34\uac8c\uac10\uc740 \uadf8\ub807\ub2e4.\\n\\n\uadf8\ub9ac\uace0 \uae00\uc744 \uc774\uc5b4\uac00\uae30 \uc704\ud574 \ub0b4\uac00 \uc544\ub294 \uc9c0\uc2dd\uc744 \ub0a8\uc5d0\uac8c \uc124\uba85\ud560 \uc218 \uc788\ub3c4\ub85d \uc815\uc81c\ud558\uace0, \uadfc\uac70\ub97c \ucc3e\ub294 \uacfc\uc815\uc5d0\uc11c \ub0b4\uac00 \uac00\uc9c4 \uc9c0\uc2dd\uc5d0 \ub6ab\ub824 \uc788\ub358 \ube48 \uad6c\uba4d\ub4e4\uc744 \ucc44\uc6b0\uac8c \ub41c\ub2e4.\\n\\n## \uc778\ud504\ub7f0\uc744 \ud5a5\ud55c \uc560\uc815\\n![smile](./smile.gif)\\n\\n\uadf8 \uc804\ubd80\ud130 \uc778\ud504\ub7f0\uc744 \uc88b\uc544\ud558\uace0, \ub9cc\uc871\ud558\uba70 \uc0ac\uc6a9\ud588\uc9c0\ub9cc \uc774\ub807\uac8c \uc5f0\ub9d0 \uc120\ubb3c\uc744 \ubc1b\uc73c\ub2c8 \uadf8 \uc560\uc815\uc774 \ub354 \ucee4\uc9d0\uc744 \uc228\uae38 \uc218\uac00 \uc5c6\ub2e4.\\n\\n\ub9c8\uce68 \uc778\ud504\ub7f0 \uce21\uc5d0\uc11c \ub0a8\uae30\uace0 \uc2f6\uc740 \ub9d0\uc744 \uc791\uc131\ud560 \uae30\ud68c\ub97c \uc8fc\uae38\ub798 \uc560\uc815\uc744 \uafb9\uafb9 \ub2f4\uc544\ubd24\ub2e4. \uc544\ub798\ub85c \uadf8 \uae00\uc744 \ub0a8\uae30\uba70, \uc774\ubc88 \ud3ec\uc2a4\ud305\uc740 \ub05d!\\n\\n---\\n\\n#### \uc778\ud504\ub7f0\uc5d0\uac8c \ud55c\ub9c8\ub514\\n> \uc774\ub7f0 \uc774\ubca4\ud2b8\uac00 \uc788\uc73c\ub9ac\ub77c\uace0\ub294 \uc0c1\uc0c1\ub3c4 \ubabb\ud588\ub294\ub370 \uc5f0\ub9d0\uc5d0 \uae30\ubd84 \uc88b\uc740 \uc77c\uc774 \uc0dd\uacbc\ub124\uc694!\\n> \\n> \ucd5c\uadfc 2\ub2ec \uc815\ub3c4\ub294 \ucde8\uc5c5\uc744 \uc704\ud574 \ubc30\ub2ec\uc758 \ubbfc\uc871 \ubd80\ud2b8\ucea0\ud504\uc5d0 \ucc38\uc5ec\ud558\uba70 \uae30\ubcf8\uae30\ub9cc \ub2e4\uc9c0\ub290\ub77c \uc778\ud504\ub7f0\uc744 \ub35c \ucc3e\uac8c \ub418\uc5c8\ub294\ub370, \uadf8 \uc804\ubd80\ud130 \uafb8\uc900\ud788 \ud574\uc624\ub358 \ub2f5\ubcc0 \ud65c\ub3d9 \ub355\uc5d0 \uc88b\uc740 \uc790\ub9ac\uc5d0 \ud568\uaed8\ud558\uac8c \ub418\uc5c8\ub124\uc694.\\n> \\n> \uc81c\uac00 \uc790\ubc1c\uc801\uc73c\ub85c \ub2f5\ubcc0\uc744 \ud65c\ubc1c\ud558\uac8c \uc791\uc131\ud55c \u2018\ub098\uc5d0\uac8c \ub3c4\uc6c0\uc774 \ub41c\ub2e4\u2018 \uadf8\ub9ac\uace0 \u2018\ub204\uad70\uac00 \ub0b4 \ub2f5\ubcc0\uc73c\ub85c \ub098\ucc98\ub7fc \ub3c4\uc6c0\uc744 \ubc1b\uaca0\uad6c\ub098\u2018 \uc0dd\uac01\ud588\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n> \\n> \uc800 \uc5ed\uc2dc\ub3c4 \ub2e4\ub978 \uc218\uac15\uc0dd\ub4e4\uc774 \ub0a8\uaca8 \uc900 \ub2f5\ubcc0\uc73c\ub85c\ubd80\ud130 \uc0c8\ub85c\uc6b4 \uc758\ubb38\uc744 \uac00\uc9c0\uace0 \ud574\uacb0\ud574\uac00\ub294 \uacfc\uc815\uc5d0\uc11c \uc131\uc7a5\ud560 \uc218 \uc788\uc5c8\uc5b4\uc694. \ub204\uad70\uac00 \ub0a8\uaca8 \ub454 \ub2f5\ubcc0\uc744 \ud1b5\ud574 \uc5bb\uac8c \ub41c \uc778\uc0ac\uc774\ud2b8\ub3c4 \ub9ce\uc558\uace0\uc694.\\n>\\n> \uc774\ub807\uac8c \uacbd\ud5d8\ud55c \uac10\uc0ac\ud568\uc5d0 \ubcf4\ub2f5\ud558\uace0\uc790 \ub2f5\ubcc0\uc744 \uc2dc\uc791\ud558\uac8c \ub418\uc5c8\ub124\uc694. \ubb3c\ub860 \ub0a8\uc5d0\uac8c \uc124\uba85\ud558\uae30 \uc704\ud55c \ub2f5\ubcc0\uc744 \uc791\uc131\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uc81c \uc2a4\uc2a4\ub85c \ubd80\uc871\ud55c \ubd80\ubd84\uc744 \ucc44\uc6b0\uba70 \uc131\uc7a5\ud558\uae30\ub3c4 \ud588\uace0\uc694.\\n> \\n> \ucc98\uc74c \ud504\ub85c\uadf8\ub798\ubc0d \uacf5\ubd80\ub97c \uc2dc\uc791\ud560 \ub54c \uc811\ud588\ub358 \ud50c\ub7ab\ud3fc\uc774 \uc778\ud504\ub7f0\uc778 \ub9cc\ud07c \ub9ce\uc740 \uc560\uc815\uc774 \uac00\ub294 \uc11c\ube44\uc2a4\uc785\ub2c8\ub2e4.\\n> \\n> \ucd5c\uadfc \uba87 \ub144\uc0c8 \ubaa8\ubc14\uc77c \uc571 \uc5c5\ub370\uc774\ud2b8\ub098 \uc2e0\uae30\ub2a5 \ucd9c\uc2dc, \uc774\ubca4\ud2b8 \uc9c4\ud589 \ub4f1\uc744 \ud558\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \u2018\uc815\ub9d0 \ub178\ub825\ud558\uace0 \uc788\uad6c\ub098. \uc55e\uc73c\ub85c \ub354 \uc131\uc7a5\ud558\ub294 \uc11c\ube44\uc2a4\uac00 \ub418\uaca0\uad6c\ub098\u2018 \uc0dd\uac01\ud558\uba70 \uad1c\uc2dc\ub9ac \uc81c\uac00 \ubfcc\ub4ef\ud568\uc744 \ub290\ub07c\uace4 \ud588\uc5b4\uc694.\\n> \\n> \uc81c \uacbd\uc6b0\uc5d0\ub294 \uc778\ud504\ub7f0 \ub0b4\uc5d0\uc11c \ud544\uc694\ud55c \uac15\uc758\ub97c \ubaa8\ub450 \ucc3e\uc744 \uc218 \uc788\uc5c8\uae30\uc5d0 \ud0c0 \uc11c\ube44\uc2a4(\uc798 \ubaa8\ub974\uc9c0\ub9cc \uc544\ub9c8 \uad6d\ub0b4\uc5d0 2, 3\uac1c \uc815\ub3c4\uc758 \uacbd\uc7c1\uc790\uac00 \uc788\ub294 \uac78\ub85c \uae30\uc5b5\ud569\ub2c8\ub2e4)\ub294 \uac00\uc785\uc870\ucc28 \ud55c \uc801\uc774 \uc5c6\ub124\uc694.\\n> \\n> \uc778\ud504\ub7f0 \uce21\uc5d0\uc11c \ud604\uc7ac \uc2e0\uaddc \uac00\uc785\uc790\uc5d0 \ub300\ud55c \uc5b4\ub5a4 \uc774\uc810\uc744 \uc8fc\ub294\uc9c0\ub294 \ubaa8\ub974\uc9c0\ub9cc, \uc801\uadf9\uc801\uc778 \ud61c\ud0dd\uc744 \uc900\ub2e4\uba74 \ud55c\ubc88 \uac15\uc758\ub97c \ub4e3\uae30 \uc2dc\uc791\ud558\uba74 \ub77d\uc778\ub418\uc9c0 \uc54a\uc744\uae4c \ud558\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5b4 \uc758\uacac \ub0a8\uaca8\uc694.\\n> \\n> \uadf8\ub9ac\uace0 \ub300\ud559 \ubcf8\ubd80\ub098 \ud559\uc0dd\ud68c \uce21\uacfc \uc5f0\ub77d\ud574\uc11c \ucea0\ud37c\uc2a4 \ub0b4\uc5d0\uc11c \uc790\uadf8\ub9c8\ud55c \uc774\ubca4\ud2b8 \ubd80\uc2a4\ub97c \uc5f4\uc5b4 \uac15\uc758\ub098 \ucfe0\ud3f0 \uc99d\uc815\uc744 \ud574\ub3c4 \uc2e0\uaddc \uc720\uc785\uc790 \ubaa8\uc9d1\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\uc544\uc694.\\n> \\n> \uc5c5\uc885\uc774 \ub2e4\ub974\uae34 \ud558\uc9c0\ub9cc, \ub178\uc158\uc758 \uacbd\uc6b0 \ub300\ud559\uc0dd \uc5e0\ubc84\uc11c\ub354\ub97c \ubaa8\uc9d1\ud574\uc11c \ub178\uc158\uc744 \ud64d\ubcf4\ud558\uae30\ub3c4 \ud558\uace0, \ubaac\uc2a4\ud130 \uc5d0\ub108\uc9c0\ub4dc\ub9c1\ud06c\uc758 \uacbd\uc6b0 \uc74c\ub8cc \ubb34\ub8cc \ub098\ub214 \ud589\uc0ac\ub97c \uc790\uc8fc \uc9c4\ud589\ud558\ub354\ub77c\uace0\uc694.\\n> \\n> \uae00\uc744 \uc791\uc131\ud558\uba74\uc11c \ub4dc\ub294 \uc0dd\uac01\uc778\ub370 (\ucc38\uc5ec\ud560 \uac15\uc0ac\ub2d8\uc774 \uacc4\uc2e4\uc9c4 \ubaa8\ub974\uc9c0\ub9cc) \uc778\ud504\ub7f0 \uc8fc\ucd5c\ub85c \ud574\uc11c \ub300\ud559 \uce21\uc5d0 \ucd08\uccad \uac15\uc5f0\uc744 \uc694\uad6c\ud558\uba74 \ube44\uad50\uc801 \uc798 \uc131\uc0ac\ub418\uc9c0 \uc54a\uc744\uae4c \uc2f6\uae30\ub3c4 \ud558\ub124\uc694. \\n> \\n> \uae00\uc774 \uae38\uc5c8\ub294\ub370, \uc5f0\ub9d0 \uc798 \ub9c8\ubb34\ub9ac\ud558\uc2dc\uace0 \uc778\ud504\ub7f0\uacfc \uc800 \ubaa8\ub450 \ubaa9\ud45c\ud55c \ubc14\ub97c \uc870\uae08\uc529 \uc774\ub8e8\ub294 2026\ub144\uc774 \ub418\uae30\ub97c \uc751\uc6d0\ud569\ub2c8\ub2e4!"}]}}')}}]);